window.MEFOS_FIXED_BANK.push(...[{"id":"neuro20261004-1.6-173","number":"173","statement":"Durante el desarrollo embrionario y la configuración anatómica del tercer ventrículo, el surco hipotalámico sirve de límite entre:","options":["El epitálamo (dorsal) y el tálamo (ventral).","El tálamo (dorsal) y el hipotálamo (ventral) en las paredes laterales del tercer ventrículo.","El subtálamo y la hipófisis anterior.","La lámina terminal y la comisura blanca anterior."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-105 / G0567 del banco canónico | integración: Tema 1.2 + Tema 1.6 | archivos: Neuro_Parte2.pdf | referencias indicadas: 10-29 Clase_ Desarrollo Embrionario / Tema 1.6 - Diencéfalo 25- 26.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-174","number":"174","statement":"Respecto a las aferencias y eferencias del Locus Coeruleus localizado en la región dorsolateral de la protuberancia rostral, señale la opción CORRECTA:","options":["Es el principal centro noradrenérgico del sistema nervioso central y envía proyecciones difusas a toda la corteza, tálamo, cerebelo y médula espinal.","Es la fuente principal de acetilcolina para la corteza cerebral.","Sintetiza GABA para inhibir el tronco encefálico durante la vigilia.","Se ubica en las pirámides bulbares."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-106 / G0676 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.6 + Tema 1.9.3 | archivos: Neuro_Parte3.pdf | referencias indicadas: 10-30 Clase de repaso_ sistema nervioso / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-175","number":"175","statement":"¿Cuál de las siguientes afirmaciones sobre el Lemnisco Trigeminal en el tronco del encéfalo es CORRECTA?:","options":["Conduce información sensitiva (táctil, dolorosa y térmica) proveniente de la cara y cabeza contralateral hacia el núcleo ventral posteromedial (VPM) del tálamo.","Conduce la información auditiva binaural hacia los colículos inferiores.","Transporta fibras motoras desde la corteza motora a la médula espinal.","Se origina exclusivamente en los núcleos de la columna dorsal (grácil y cuneiforme)."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-107 / G0678 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.10 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-3-preguntas.pdf / examenes neuro compl (1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-176","number":"176","statement":"El límite superior (rostral) que separa macroscópicamente el mesencéfalo y tronco del encéfalo del diencéfalo está delimitado por:","options":["El surco bulbopontino anterior.","Un plano inclinado que pasa por encima de los colículos superiores (comisura posterior) y el borde superior del fosa interpeduncular (cuerpos mamilares).","El agujero occipital (foramen magno).","La decusación de las pirámides."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-108 / G0684 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 | archivos: Neuro_Parte3.pdf | referencias indicadas: Tema 1.5.1 - Tronco del encéfalo 25-26.pdf / 09-18 Clase_ Tronco del Encéfalo","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-177","number":"177","statement":"En la región tegmental pontomesencefálica del tronco del encéfalo, ¿qué núcleos albergan la mayor densidad de neuronas colinérgicas ascendentes encargadas de activar el tálamo y mantener el estado de vigilia y atención?:","options":["Núcleo pedunculopontino y núcleo tegmental dorsolateral.","Núcleo del rafe magno y rafe oscuro.","Locus coeruleus y área postrema.","Sustancia negra pars compacta."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-109 / G0685 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.8 | archivos: Neuro_Parte3.pdf | referencias indicadas: 09-25 Clase_ Neuroanatomía del Mesencéfalo y Sistemas Moduladores Colinérgicos","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-178","number":"178","statement":"El fascículo retroflejo de Meynert (trato habenulointerpeduncular) es una importante vía eferente del sistema límbico/epitálamo que conecta los núcleos de la habénula con qué núcleo específico ubicado en el mesencéfalo:","options":["Núcleo interpeduncular (situado en el tegmento ventral de la fosa interpeduncular).","Núcleo ambiguo.","Núcleo solitario.","Núcleo rojo."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-110 / G0687 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 | archivos: Neuro_Parte3.pdf | referencias indicadas: 09-25 Clase_ Neuroanatomía del Mesencéfalo / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-179","number":"179","statement":"Respecto a la disposición espacial del Lemnisco Medial a medida que asciende por el tronco del encéfalo desde su origen en el bulbo hasta el tálamo, señale la afirmación CORRECTA:","options":["En el bulbo raquídeo se sitúa ventral y cercano a la línea media (sagital), mientras que al ascender por la protuberancia y mesencéfalo se desplaza progresivamente en dirección lateral y dorsal.","Mantiene una posición exactamente idéntica y lateral durante todo su recorrido.","Transporta sensibilidad térmica y dolorosa de las extremidades inferiores.","Se ubica en el interior de las pirámides bulbares."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-111 / G0693 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.10 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-3-preguntas.pdf / TEMA 3 – TRONCO DEL ENCÉFALO.pdf / 09-24 Clase_ Neuroanatomía - Vías Sensitivas","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-180","number":"180","statement":"¿Qué estructura del mesencéfalo sirve como centro de relevo auditivo reflejo integrador enviando axones a través del brazo del colículo inferior hacia el cuerpo geniculado medial del tálamo?:","options":["Colículo inferior.","Colículo superior.","Núcleo rojo.","Núcleo ambiguo."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-112 / G0710 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.11.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: 09-25 Clase_ Neuroanatomía del Mesencéfalo / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-181","number":"181","statement":"Una oclusión aguda de la Arteria Espinal Anterior en la médula torácica provoca isquemia de los dos tercios anteriores de la médula. ¿Qué combinación funcional se alterará y cuál permanecerá PRESERVADA?:","options":["Se pierde la motilidad voluntaria (vía corticoespinal) y la sensibilidad termoalgésica (vía espinotalámica), manteniéndose intactas la propiocepción consciente y la sensibilidad vibratoria de los cordones posteriores.","Se pierde únicamente la sensibilidad táctil epicrítica y vibratoria, conservando intacta la función motora.","Se produce una anestesia total sin afectación de la vía motora.","Se afectan exclusivamente las funciones cognitivas superiores."],"answer":0,"explanation":"Hack de Disociación Vascular: A artéria espinal anterior irriga as astas anteriores e os cordões anteriores e laterais. Os cordões posteriores [grácil e cuneiforme] dependem do sistema arterial posterior, preservando o tato epicrítico e a propriocepção consciente).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-113 / G0724 del banco canónico | integración: Tema 1.4 + Tema 1.6 + Tema 1.10 | archivos: Neuro_Parte4.pdf | referencias indicadas: 09-18 Clase_ Vascularización de la médula espinal / ex. 2021 (respuestas).pdf (Pregunta #10) / Recopilación preguntas neuro (1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-182","number":"182","statement":"Respecto a la vía espinotalámica (que conduce sensibilidad nociceptiva y térmica), señale cuál es la secuencia exacta de decusación y trayecto en la médula espinal:","options":["Las neuronas de 2º orden tienen sus somas en las astas posteriores (lámina II - sustancia gelatinosa), sus axones decusan por la comisura blanca anterior e ingresan en el cordón blanco lateral contralateral para ascender al tálamo.","Las neuronas de 1º orden decusan en las pirámides bulbares y viajan por el cordón posterior ipsilateral.","Las neuronas de 2º orden ascienden no cruzadas por el cordón anterior ipsilateral.","Decusan en el mesencéfalo a través de la decusación tegmental ventral."],"answer":0,"explanation":"No incluida en el material.","hack":"A diferencia del cordón posterior, la vía espinotalámica decusa inmediatamente dentro de la propia médula espinal cruzando la comisura blanca anterior.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-114 / G0734 del banco canónico | integración: Tema 1.4 + Tema 1.6 + Tema 1.10 | archivos: Neuro_Parte4.pdf | referencias indicadas: 10-21 Clase_ Modulación del dolor y sustancia gelatinosa3132 / ex. 2021 (respuestas).pdf (Pregunta #10) / 11-06 Tutoría","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-183","number":"183","statement":"Además del tracto espinotalámico lateral (componente sensorial-discriminativo del dolor), la médula espinal origina los tractos espinoreticular y espinomesencefálico en las astas posteriores. ¿Hacia qué estructuras proyectan y qué dimensión del dolor codifican?:","options":["Proyectan a la formación reticular del tronco y sustancia gris periacueductal (SGP) para mediar las respuestas afectivo-emocionales, autonómicas y el despertar por dolor.","Proyectan a la corteza visual occipital para la localización espacial del estímulo.","Proyectan al núcleo rojo para la modulación de los flexores.","Transmiten propiocepción consciente del cuello."],"answer":0,"explanation":"No incluida en el material.","hack":"Espinotalámico: \"Dónde y cuánto duele\" (sensorial/discriminativo, tálamo VPL -> S1). Espinoreticular / Espinomesencefálico: \"Sufrimiento, alerta y reacción vegetativa\" (afectivo/emocional, SGP e formación reticular).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-115 / G0750 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.6 + Tema 1.10 | archivos: Neuro_Parte4.pdf | referencias indicadas: 10-21 Clase_ Modulación del dolor / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #182) / TEMA 11 – SISTEMA SOMATOSENSORIAL .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-184","number":"184","statement":"El tracto espinoreticular es una vía ascendente polisináptica que acompaña a la vía espinotalámica. Sus fibras hacen sinapsis en la formación reticular del tronco del encéfalo y proyectan hacia los núcleos intralaminares del tálamo. ¿Cuál es su papel neurofisiológico esencial?:","options":["Activar el sistema de alerta o despertar (ARAS) y provocar respuestas vegetativas y emocionales desencadenadas por estímulos nociceptivos continuos.","Discriminar exactamente la localización espacial del roce en la yema de los dedos.","Transmitir impulsos motores voluntarios a las motoneuronas gamma.","Coordinar la marcha atáxica cerebelosa."],"answer":0,"explanation":"No incluida en el material.","hack":"Mientras que la vía espinotalámica directa codifica \"dónde y cuánto duele\" (componente rápido/discriminativo), la vía espinoreticular conduce el dolor lento/sordo e ingresa a la formación reticular para activar el estado de alerta (sueño-vigilia) y desencadenar las respuestas autonómicas ante el dolor.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-116 / G0754 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.6 + Tema 1.10 | archivos: Neuro_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #193) / 10-20 Clase_ Sistema Sensorial y Receptores Sensitivos.mp / TEMA 2 – MÉDULA ESPINAL .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-185","number":"185","statement":"El tracto espinotalámico anterior (que discurre por el cordón blanco anterior de la médula espinal) se encarga de conducir qué modalidad sensitiva específica:","options":["Tacto no discriminativo (protopático / grueso) y sensación de presión.","Propiocepción consciente y vibración (palestesia).","Dolor punzante agudo y temperatura.","Visión y audición refleja."],"answer":0,"explanation":"No incluida en el material.","hack":"Tracto Espinotalámico Anterior: Tacto protopático (grosero/no discriminativo) y presión. Tracto Espinotalámico Lateral: Dolor y temperatura (termoalgesia). Cordón Posterior (Grácil/Cuneiforme): Tacto epicrítico (fino/discriminativo), vibración y propiocepción consciente.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-117 / G0774 del banco canónico | integración: Tema 1.4 + Tema 1.6 + Tema 1.10 | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: 10-20 Clase magistral_ Sistema somatosensorial / TEMA 11 – SISTEMA SOMATOSENSORIAL .pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #266)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-186","number":"186","statement":"Respecto a la distribución general de los grandes tractos en la sustancia blanca de la médula espinal, señale la opción CORRECTA:","options":["El cordón posterior contiene exclusivamente tractos ascendentes sensitivos (Grácil y Cuneiforme); el cordón anterior y lateral contienen una mezcla de tractos ascendentes (Espinotalámico, Espinocerebelosos) y descendentes (Corticoespinales, Rubroespinal, Vestibuloespinales y Reticuloespinales).","El cordón posterior contiene el tracto corticoespinal lateral.","El cordón anterior contiene únicamente fibras amielínicas C.","Todos los tractos motores descendentes discurren por el cordón posterior."],"answer":0,"explanation":"No incluida en el material.","hack":"Cordón posterior = 100% sensitivo ascendente (sin vías motoras descendentes). Cordones anterior y lateral = Mixtos (vías ascendentes sensitivas + vías motoras piramidales y extrapiramidales).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-118 / G0791 del banco canónico | integración: Tema 1.4 + Tema 1.6 + Tema 1.9.1 + Tema 1.9.3 + Tema 1.10 | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: 12-05 Clase magistral_ Tractos extrapiramidales / TEMA 2 – MÉDULA ESPINAL .pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-187","number":"187","statement":"¿Cuál de las seis capas de la neocorteza cerebral se caracteriza por recibir la mayor cantidad de aferencias sensoriales específicas procedentes de los núcleos de relevo del tálamo (p. ej., VPL, VPM, CGL, CGM)?:","options":["Capa IV o Granulosa Interna.","Capa V o Piramidal Interna.","Capa I o Molecular.","Capa II o Granulosa Externa."],"answer":0,"explanation":"No incluida en el material.","hack":"Capa IV (Granulosa Interna): Capa receptora/input principal de aferencias talámicas específicas. Por ello está hipertrofiada en las cortezas sensitivas primarias (S1, V1, A1). Capa V (Piramidal Interna): Capa de salida/output principal hacia la médula y tronco (vía piramidal). Capa VI (Multiforme): Proyecta de regreso al tálamo (corticotalámica).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-119 / G0797 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.10 | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: wuolah-free-EXAMEN-2017-2018-1 (1).pdf (Pregunta #70) / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf / 10-20 Clase magistral_ Sistema somatosensorial","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-188","number":"188","statement":"La cápsula interna es una gruesa lámina de sustancia blanca de proyección. En un corte transversal del cerebro (corte de Flechsig/Rambaut), el brazo posterior de la cápsula interna se sitúa exactamente entre:","options":["El tálamo (medial) y el núcleo lenticular / globo pálido (lateral).","El núcleo caudado (medial) y el putamen (lateral).","El claustro (medial) y la corteza de la ínsula (lateral).","La cabeza del núcleo caudado y el cuerpo calloso."],"answer":0,"explanation":"No incluida en el material.","hack":"Relaciones anatómicas de la cápsula interna (pregunta fija de examen): Brazo anterior: entre la cabeza del núcleo caudado (medial) y el núcleo lenticular (lateral). Rodilla: punto de flexión entre caudado, tálamo y lenticular (lleva la vía corticonuclear/corticobulbar). Brazo posterior: entre el tálamo (medial) y el núcleo lenticular (lateral) (lleva la vía corticoespinal y radiaciones talámicas).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-120 / G0802 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.9.2 | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #80) / Tema 1.7 - Telencéfalo 25-26 (2).pdf / 10-09 Clase_ Neuroanatomía - Hipocampo y Sustancia Blanca","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-189","number":"189","statement":"El fórnix (trígono cerebral) es un tracto de sustancia blanca eferente fundamental del hipocampo. Indique la afirmación CORRECTA sobre sus conexiones y trayecto:","options":["Nace en las fimbrias del hipocampo, pasa sobre el tálamo formando los pilares posteriores, el cuerpo y las columnas anteriores, y termina principalmente en los cuerpos mamilares del hipotálamo.","Conecta directamente la corteza auditiva primaria con el cuerpo geniculado lateral.","Cruza la comisura posterior para ingresar al cerebelo por el pedúnculo superior.","Forma la pared lateral del IV ventrículo."],"answer":0,"explanation":"No incluida en el material.","hack":"El fórnix es la principal vía de salida del hipocampo (subículo/alvéolo -> fimbria -> pilar posterior -> cuerpo -> columna anterior -> cuerpo mamilar del hipotálamo). Forma el techo del tercer ventrículo y el piso del ventrículo lateral en esa región, integrando el célebre Circuito de Papez.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-121 / G0806 del banco canónico | integración: Tema 1.6 + Tema 1.7 | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #86) / Tema 1.7 - Telencéfalo 25-26 (2).pdf / 10-09 Clase_ Neuroanatomía - Hipocampo y Sustancia Blanca","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-190","number":"190","statement":"¿Cuál es la única modalidad sensorial consciente cuyas aferencias primarias alcanzan directamente la corteza cerebral (corteza piriforme / uncus del lóbulo temporal) sin hacer un relevo directo previo en el tálamo?:","options":["Olfato (vía olfatoria).","Visión.","Audición.","Propiocepción consciente."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Única Excepción Sensorial: La vía olfatoria es la única vía sensitiva que NO hace relevo previo en el tálamo antes de llegar a su corteza primaria (paleocórtex / corteza piriforme del uncus temporal). Todas las demás vías sensitivas (visión, audición, gusto, somatosensibilidad) pasan obligatoriamente por un núcleo de relevo talámico específico antes de proyectar al neocórtex.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-122 / G0809 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.11.3 | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #89) / TEMA 14 – GUSTO Y OLFATO .pdf / 10-07 Clase_ Organización Celular y Funcional de la Corteza","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-191","number":"191","statement":"¿En qué región cortical específica se localiza el área gustativa primaria (área 43 de Brodmann) que recibe aferencias procedentes del núcleo del tracto solitario a través del núcleo ventral posteromedial (VPM) del tálamo?:","options":["En la porción inferior del giro postcentral y el opérculo frontoparietal / pared insular anterior adyacente.","En el polo occipital dentro de la cuña.","En el giro temporal inferior en la cara basolateral.","En el giro cingulado anterior."],"answer":0,"explanation":"No incluida en el material.","hack":"El Área Gustativa Primaria (Área 43 de Brodmann) se ubica en el pie del giro postcentral (área somatosensorial de la lengua) y se extiende hacia el opérculo frontal e ínsula anterior. La información del gusto (pares VII, IX y X -> Núcleo del Tracto Solitario -> Tálamo VPM) proyecta a esta región para la percepción consciente del sabor.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-123 / G0840 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.9.1 + Tema 1.10 + Tema 1.11.3 | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #162) / TEMA 6 – TELENCÉFALO.pdf / Tema 1.7 - Telencéfalo 25-26 (2).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-192","number":"192","statement":"El Circuito de Papez es la vía clásica de integración de la emoción y la consolidación de la memoria episódica. Indique la secuencia anatómica exacta del flujo de información a través de este circuito cerrado:","options":["Hipocampo -> Fórnix -> Cuerpos Mamilares -> Tracto Mamilotalámico -> Núcleo Anterior del Tálamo -> Cíngulo -> Giro Parahipocampal -> Hipocampo.","Tálamo VPL -> Cápsula Interna -> Corteza Motora M1 - > Bulbo -> Médula.","Amígdala -> Núcleo Rojo -> Cerebelo -> Núcleo Dentado -> Tálamo VA.","Subículo -> Nervio Óptico -> Quiasma -> Cintilla -> Cuerpo Geniculado Lateral."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Secuencia de Papez (Pregunta Fija de Examen): Hipocampo / Subículo emite fibras por el Fórnix hacia los 2. Cuerpos Mamilares (hipotálamo). Los cuerpos mamilares proyectan por el Tracto Mamilotalámico (de Vicq d'Azyr) al 4. Núcleo Anterior del Tálamo. El núcleo anterior proyecta a la 6. Corteza Cingulada (Giro del Cíngulo). El cíngulo envía fibras por el cingulum al 8. Giro Parahipocampal / Corteza Entorrinal, regresando al Hipocampo.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-124 / G0841 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.8 | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #165) / 11-06 Tutoría_ Memoria (Papez) / 10-08 Clase_ Sistema Límbico","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-193","number":"193","statement":"La comisura posterior (comisura epitalámica) es una estructura de sustancia blanca ubicada en la unión del mesencéfalo y el diencéfalo. ¿Qué función refleja esencial realiza al conectar las áreas pretectales de ambos lados?:","options":["Permite la respuesta consensual del reflejo fotomotor pupilar (la iluminación de un solo ojo produce la miosis de ambas pupilas).","Conecta la corteza motora primaria con la médula espinal.","Modula la audición tonotópica en los giros de Heschl.","Transmite el dolor somático de los miembros inferiores."],"answer":0,"explanation":"No incluida en el material.","hack":"En la vía del reflejo fotomotor, los axones del núcleo pretectal de un lado decusan a través de la comisura posterior para estimular el núcleo accesorio del oculomotor (Edinger-Westphal) del lado opuesto. Esto garantiza que la miosis sea simultánea y bilateral (reflejo consensual).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-125 / G0842 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.7 + Tema 1.11.1 | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #168) / 10-27 Clase_ Vía Visual y Reflejos Oculares / TEMA 12 – VISIÓN.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-194","number":"194","statement":"Las fibras comisurales conectan estructuras homólogas de ambos hemisferios cerebrales. Aparte del cuerpo calloso y la comisura anterior, ¿qué comisura interconecta las habénulas y núcleos epitalámicos en la pared posterior del tercer ventrículo?:","options":["Comisura habenular.","Comisura de Gudden.","Comisura del fórnix.","Quiasma óptico."],"answer":0,"explanation":"No incluida en el material.","hack":"La comisura habenular se ubica en el epítalamo, justo superior a la glándula pineal y la comisura posterior, interconectando los núcleos habenulares de ambos hemisferios para la integración olfativo-somática y respuestas emocionales.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-126 / G0851 del banco canónico | integración: Tema 1.6 + Tema 1.7 | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #187) / TEMA 6 – TELENCÉFALO.pdf / 10-09 Clase_ Neuroanatomía - Hipocampo y Sustancia Blanca","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-195","number":"195","statement":"En un corte coronal del cerebro a nivel de los cuerpos mamilares, ¿qué estructura de sustancia blanca separa la cabeza del núcleo caudado y el tálamo (medialmente) del putamen y globo pálido (lateralmente)?:","options":["Cápsula interna.","Cápsula externa.","Cápsula extrema.","Cuerpo calloso."],"answer":0,"explanation":"No incluida en el material.","hack":"La cápsula interna es la principal vía de proyección cerebral. Separa medialmente a la cabeza del caudado y al tálamo, respecto al núcleo lenticular (putamen y globo pálido) que se sitúa lateralmente.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-127 / G0854 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.9.2 | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #198) / 10-09 Clase_ Neuroanatomía - Hipocampo y Sustancia Blanca / TEMA 6 – TELENCÉFALO.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-196","number":"196","statement":"En la microanatomía del hipocampo, el subículo (subiculum) representa la zona de transición histológica entre la alocorteza (de 3 capas) y la neocorteza. ¿Cuál es su papel fundamental en la conectividad del hipocampo?:","options":["Es la principal estructura eferente de la formación hipocampal, recibiendo axones de la región CA1 y proyectando masivamente hacia la corteza entorrinal y hacia los cuerpos mamilares a través del fórnix.","Es la corteza visual primaria del lóbulo occipital.","Inerva de forma motora voluntaria los músculos del diafragma.","Se encarga de la producción del líquido cefalorraquídeo."],"answer":0,"explanation":"No incluida en el material.","hack":"El subículo actúa como la \"puerta de salida\" principal del hipocampo. Recibe la proyección de las neuronas de CA1 y proyecta masivamente tanto de regreso a la corteza entorrinal (para enviar información consolidada al neocórtex) como hacia los cuerpos mamilares a través de las fibras del fórnix.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-128 / G0864 del banco canónico | integración: Tema 1.6 + Tema 1.7 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf / Tema 1.7 - Telencéfalo 25-26 (2).pdf / 10-09 Clase_ Neuroanatomía - Hipocampo","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-197","number":"197","statement":"En la pared posterior del tercer ventrículo, la comisura posterior (epitalámica) cruza la línea media inmediatamente dorsal al acueducto de Silvio. ¿Qué reflejo ocular coordinado depende críticamente del cruce de fibras a través de esta comisura?:","options":["Reflejo fotomotor consensual (la iluminación de una pupila produce la miosis de ambas pupilas al conectar las áreas pretectales bilateralmente).","Reflejo corneal motor.","Reflejo miotático del cuádriceps.","Secreción salival por la glándula parótida."],"answer":0,"explanation":"No incluida en el material.","hack":"La comisura posterior interconecta las áreas pretectales de ambos lados del mesencéfalo. Gracias a este cruce comisural, la señal luminosa que entra por un solo ojo activa el núcleo accesorio del oculomotor (Edinger-Westphal) de ambos lados, provocando miosis pupilar bilateral (reflejo consensual).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-129 / G0865 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.11.1 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: 10-27 Clase_ Vía Visual y Reflejos Oculares / TEMA 12 – VISIÓN.pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-198","number":"198","statement":"La porción sublenticular de la cápsula interna pasa ventralmente al núcleo lenticular. ¿Qué importante vía sensorial atraviesa esta porción en su camino hacia la corteza temporal?:","options":["Las radiaciones acústicas (vía auditiva) procedentes del cuerpo geniculado medial hacia los giros transversos de Heschl (áreas 41 y 42).","El tracto corticoespinal lateral.","Las fibras espinotalámicas de la pierna.","La vía olfatoria directa."],"answer":0,"explanation":"No incluida en el material.","hack":"Porción Sublenticular: Lleva la radiación auditiva desde el cuerpo geniculado medial hasta los giros de Heschl. Porción Retrolenticular: Lleva la radiación óptica desde el cuerpo geniculado lateral hasta la cisura calcarina.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-130 / G0871 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.11.2 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: 10-09 Clase_ Neuroanatomía - Hipocampo y Sustancia Blanca / TEMA 6 – TELENCÉFALO.pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-199","number":"199","statement":"Con relación a la organización interna y núcleos del tálamo, indique la afirmación FALSA:","options":["La lámina medular interna contiene en su espesor a los núcleos intralaminares, entre los que destaca el núcleo centromediano.","El núcleo pulvinar se localiza en el extremo posterior del tálamo y se encarga del procesamiento de asociación visual y somatosensorial.","El núcleo geniculado lateral recibe aferencias auditivas procedentes del colículo inferior del mesencéfalo y proyecta a la corteza auditiva primaria en el lóbulo temporal.","El núcleo ventral anterior (VA, porción lateral) forma parte de los circuitos motores talámicos recibiendo aferencias del globo pálido y sustancia negra."],"answer":2,"explanation":"No incluida en el material.","hack":"Hack de Inversión Metatalámica de la Profesora Aitana: Cuerpo Geniculado LATERAL (CGL): Recibe información VISUAL de la cintilla óptica y proyecta a la corteza visual primaria (área 17 de Brodmann / cisura calcarina). Cuerpo Geniculado MEDIAL (CGM): Recibe información AUDITIVA del colículo inferior y proyecta a la corteza auditiva primaria (giros transversos de Heschl / áreas 41 y 42). (Mnemotecnia de clase: Lateral = Luz/Visión; Medial = Música/Audición).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-131 / G0872 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.11.2 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #48) / ex. 2 (respuestas).pdf (Pregunta #21) / 10-30 Clase magistral_ Neuroanatomía meníngea, vías medulares","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-200","number":"200","statement":"Con respecto a los tractos y conexiones del hipotálamo, señale la relación CORRECTA:","options":["Fórnix — principal eferencia de la amígdala que conecta directamente con los cuerpos mamilares hipotalámicos.","Tracto mamilotalámico (de Vicq d'Azyr) — conecta los cuerpos mamilares con el núcleo anterior del tálamo, formando parte del circuito de Papez.","Fascículo longitudinal dorsal (de Schütz) — conecta el hipotálamo directamente con la habénula del epitálamo.","Tracto tuberoinfundibular — conecta el núcleo supraóptico con la neurohipófisis."],"answer":1,"explanation":"No incluida en el material.","hack":"Fórnix: Es la eferencia principal del HIPOCAMPO (no de la amígdala) hacia los cuerpos mamilares. Vía Amigdalófuga Ventral y Estría Terminal: Son las eferencias de la AMÍGDALA hacia el hipotálamo. Tracto Tuberoinfundibular: Conecta el núcleo arcuato/infundibular con la adenohipófisis (sistema porta hipofisario); el tracto hipotálamo-hipofisario (supraóptico/paraventricular) conecta con la neurohipófisis.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-132 / G0874 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #106) / ex. 2 (respuestas).pdf (Pregunta #19) / 10-06 Clase_ Neuroanatomía del Hipotálamo","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-201","number":"201","statement":"El núcleo reticular del tálamo (NRT) es una delgada capa de neuronas que envuelve la superficie lateral del tálamo por fuera de la lámina medular externa. ¿Cuál es su peculiaridad neurofisiológica y su neurotransmisor característico?:","options":["Es el único núcleo del tálamo que no proyecta directamente a la corteza cerebral; libera GABA e inhibe a las neuronas de relevo talámico para modular la puerta de entrada sensorial hacia la corteza.","Proyecta axones glutamatérgicos excitadores hacia la corteza motora primaria.","Recibe aferencias olfatorias directas sin pasar por el III ventrículo.","Libera melatonina en respuesta a la oscuridad."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Único Núcleo Inhibidor Talámico: La profesora Aitana destaca en la clase magistral que el Núcleo Reticular del Tálamo (NRT) es la ÚNICA estructura del tálamo que libera GABA. Recibe colaterales de las vías tálamo-corticales y cortico-talámicas y ejerce un bucle de inhibición recurrente sobre el resto de núcleos talámicos, regulando el estado de sueño-vigilia.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-133 / G0876 del banco canónico | integración: Tema 1.6 + Tema 1.7 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: 10-30 Clase magistral_ Neuroanatomía meníngea, vías medulares / wuolah-free-PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-202","number":"202","statement":"Respecto a las estructuras que componen el epitálamo, señale la afirmación CORRECTA sobre los núcleos habenulares y la glándula pineal:","options":["Los núcleos habenulares se ubican en el extremo posterosuperior del diencéfalo (trígono de la habénula) e integran respuestas emocionales/viscerales ante estímulos olfatorios.","Los núcleos habenulares forman parte del subtálamo e inervan el globo pálido.","La glándula pineal (epífisis) se sitúa por debajo de los colículos inferiores y secreta orexinas.","La habénula forma el piso del suelo del hipotálamo."],"answer":0,"explanation":"No incluida en el material.","hack":"Epitálamo (Posterodorsal al tálamo): Formado por los Núcleos Habenulares (conectados por la comisura habenular) y la Glándula Pineal / Epífisis (situada justo por encima de los colículos superiores del mesencéfalo, encargada de secretar melatonina para regular el ritmo circadiano). Distractor típico: Decir que la habénula es subtalámica o hipotalámica.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-134 / G0877 del banco canónico | integración: Tema 1.6 + Tema 1.11.3 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: ex. 2021 (respuestas).pdf (Pregunta #26) / TEMA 5 – DIENCÉFALO .pdf / wuolah-free-EXAMEN-2017-2018-1.pdf (Pregunta #65)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-203","number":"203","statement":"En la neurofisiología hipotalámica del comportamiento alimentario y la regulación del peso corporal, indague cuál es el papel de las orexinas (hipocretinas) y en qué núcleo hipotalámico se sintetizan de forma exclusiva:","options":["Se sintetizan en el área hipotalámica lateral y actúan como potentes estimuladores del hambre (efecto orexigénico) y del estado de alerta/vigilia.","Se producen en el núcleo ventromedial e inducen la saciedad.","Se liberan desde la neurohipófisis para aumentar la reabsorción de agua.","Se sintetizan en la glándula pineal durante la noche."],"answer":0,"explanation":"No incluida en el material.","hack":"Hipotálamo Lateral: \"Centro del Hambre\" -> Produce Orexinas / Hipocretinas. Su destrucción causa anorexia/abulia alimentaria y narcolepsia. Núcleo Ventromedial: \"Centro de la Saciedad\" - > Su destrucción causa hiperfagia y obesidad mórbida.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-135 / G0878 del banco canónico | integración: Tema 1.6 + Tema 1.8 + Tema 1.11.1 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: TEMA 5 – DIENCÉFALO .pdf / ex. 2021 (respuestas).pdf (Pregunta #28) / wuolah-free-tema-6-preguntas.pdf (Pregunta #1)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-204","number":"204","statement":"En el grupo nuclear ventral del tálamo, los núcleos somatosensoriales de relevo principal son el Ventral PosteroLateral (VPL) y el Ventral PosteroMedial (VPM). Indique la somatotopía y procedencia exacta de las aferencias que recibe el núcleo VPM:","options":["Recibe la sensibilidad somática de la cabeza y cara a través del lemnisco trigeminal (V par), así como las aferencias gustativas del núcleo del tracto solitario.","Recibe la propiocepción consciente y tacto epicrítico del miembro inferior a través del fascículo grácil.","Recibe aferencias visuales procedentes del nervio óptico.","Proyecta exclusivamente hacia la corteza motora primaria (área 4)."],"answer":0,"explanation":"No incluida en el material.","hack":"VPL (Ventral PosteroLateral): Recibe la sensibilidad del cuerpo y miembros (lemnisco medial + tracto espinotalámico). VPM (Ventral PosteroMedial): Recibe la sensibilidad de la cabeza y cara (lemnisco trigeminal) + gusto (núcleo del tracto solitario). (Mnemotecnia de examen: VPL = Piel del cuerpo / Pierna; VPM = Mono / Mandíbula / Mueca).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-136 / G0880 del banco canónico | integración: Tema 1.6 + Tema 1.10 + Tema 1.11.3 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #52) / TEMA 5 – DIENCÉFALO .pdf / 10-01 Clase_ Neuroanatomía - Tálamo e Hipotálamo","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-205","number":"205","statement":"El subtálamo se ubica ventral al tálamo y posterolateral al hipotálamo. ¿Qué estructura subtalámica eferente es fundamental en el circuito indirecto de los ganglios basales y qué cuadro motor involuntario produce su lesión vascular destructiva (ictus)?:","options":["Núcleo Subtalámico de Luys; su lesión causa hemibalismo contralateral (movimientos coreiformes violentos e involuntarios de gran amplitud en las extremidades).","Núcleo Geniculado Medial; su lesión produce acúfenos.","Núcleo Pulvinar; su lesión provoca afasia motora.","Zona incierta; su lesión produce parálisis facial periférica."],"answer":0,"explanation":"No incluida en el material.","hack":"El Núcleo Subtalámico de Luys es la única estructura glutamatérgica (excitadora) de los ganglios basales que estimula al Globo Pálido Interno (GPi). Un ictus lacunar en el núcleo subtalámico destruye el \"freno\" del circuito indirecto, liberando al tálamo y provocando hemibalismo contralateral.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-137 / G0881 del banco canónico | integración: Tema 1.6 + Tema 1.9.2 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #55) / ex. 2 (respuestas).pdf (Pregunta #22) / 12-05 Clase_ Núcleos Basales","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-206","number":"206","statement":"El ritmo circadiano de sueño-vigilia y los ciclos fisiológicos de 24 horas están regulados por el \"marcapasos biológico central\" del encéfalo. ¿Qué núcleo hipotalámico recibe aferencias luminosas directas de la retina a través del tracto retinohipotalámico para cumplir esta función?:","options":["Núcleo Supraquiasmático.","Núcleo Mamilar Medial.","Núcleo Ventromedial.","Núcleo Anterior del Tálamo."],"answer":0,"explanation":"No incluida en el material.","hack":"El Núcleo Supraquiasmático (NSQ), situado justo superior al quiasma óptico, recibe proyecciones de las células ganglionares fotosensibles de la retina (ipRGC, con melanopsina) vía tracto retinohipotalámico. Modula a la glándula pineal para controlar la secreción de melatonina.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-138 / G0883 del banco canónico | integración: Tema 1.6 + Tema 1.8 + Tema 1.11.1 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #62) / 10-17 Clase magistral_ Vía retinohipotalámica / wuolah-free-PREGUNTAS-TEST- NEURO-DIENCEFALO-.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-207","number":"207","statement":"El grupo nuclear anterior del tálamo forma parte indispensable del sistema límbico. ¿De qué estructura diencefálica recibe su principal aferencia a través del fascículo de Vicq d'Azyr y hacia qué corteza cerebral proyecta sus eferencias?:","options":["Recibe del cuerpo mamilar (tracto mamilotalámico) y proyecta al giro del cíngulo.","Recibe del núcleo dentado del cerebelo y proyecta a M1.","Recibe de la retina y proyecta al lóbulo occipital.","Recibe de la sustancia negra y proyecta al putamen."],"answer":0,"explanation":"No incluida en el material.","hack":"Eslabón fundamental del Circuito de Papez: Cuerpos Mamilares -> Tracto Mamilotalámico (Vicq d'Azyr) -> Núcleo Anterior del Tálamo -> Radiaciones Cinguladas -> Giro del Cíngulo.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-139 / G0885 del banco canónico | integración: Tema 1.6 + Tema 1.7 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #65) / 11-06 Tutoría_ Memoria (Papez) / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-208","number":"208","statement":"El tercer ventrículo es una cavidad media e impar con forma de hendidura vertical estrecha que separa ambos tálamos e hipotálamos. Indique qué estructuras delimitan su pared anterior y su suelo (piso) respectivamente:","options":["Pared anterior: Lámina terminal y comisura anterior | Suelo: Quiasma óptico, infundibulum, tuber cinereum y cuerpos mamilares.","Pared anterior: Colículos superiores | Suelo: Cuerpo calloso.","Pared anterior: Esplenio | Suelo: Fosa romboidea.","Pared anterior: Glándula pineal | Suelo: Adherencia intertalámica."],"answer":0,"explanation":"No incluida en el material.","hack":"Anatomía de las Paredes del III Ventrículo (Pregunta fija de examen): Pared Anterior: Lámina terminal, comisura anterior y columnas del fórnix. Suelo / Piso: Quiasma óptico, infundíbulo, tuber cinereum, cuerpos mamilares y sustancia perforada posterior. Techo: Tela coroidea del III ventrículo y fórnix. Paredes Laterales: Cara medial del tálamo (dorsal) e hipotálamo (ventral), divididas por el surco hipotalámico de Monro.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-140 / G0887 del banco canónico | integración: Tema 1.6 + Tema 1.11.1 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #70) / 09-10 Clase_ LCR / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-209","number":"209","statement":"¿Cuál de los siguientes núcleos hipotalámicos es la única fuente central de histamina en el encéfalo y desempeña un papel neurofisiológico determinante en la promoción y mantenimiento del estado de vigilia y alerta?:","options":["Núcleo Tuberomamilar","Núcleo Supraóptico","Núcleo Ventromedial","Núcleo Preóptico Medial"],"answer":0,"explanation":"No incluida en el material.","hack":"El Núcleo Tuberomamilar (ubicado en la región mamilar/posterior del hipotálamo) contiene neuronas histaminérgicas. La histamina actúa sobre la corteza cerebral promoviendo el estado de vigilia (motivo por el cual los fármacos antihistamínicos de primera generación que cruzan la barrera hematoencefálica provocan somnolencia profunda).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-141 / G0888 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: examenes neuro compl (1).pdf (Pregunta #48) / TEMA 5 – DIENCÉFALO .pdf / 10-13 Clase_ Funciones Cerebrales, Ritmos Circadianos y Sueño","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-210","number":"210","statement":"Ante una pérdida de agua e hiperosmolaridad plasmática (sed osmométrica), ¿qué órgano circunventricular hipotalámico carente de barrera hematoencefálica detecta directamente los cambios de osmolaridad en la sangre e informa a las neuronas magnocelulares para liberar vasopresina (ADH) e inducir la conducta de búsqueda de agua?:","options":["Órgano Vascular de la Lámina Terminal (OVLT) y Órgano Subfornical","Glándula Pineal","Núcleo Rojo","Cuerpo Geniculado Medial"],"answer":0,"explanation":"No incluida en el material.","hack":"El OVLT y el Órgano Subfornical son órganos circunventriculares (sin barrera hematoencefálica) que actúan como osmorreceptores centrales. Captan el aumento de sodio/osmolaridad e inervan al núcleo supraóptico y paraventricular para liberar vasopresina (ADH) a la sangre y desencadenar la sensación consciente de sed.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-142 / G0890 del banco canónico | integración: Tema 1.6 + Tema 1.12 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: TEMA 5 – DIENCÉFALO .pdf (Sección Sed Osmométrica) / wuolah-free- PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf / 09-30 Clase_ Diencéfalo","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-211","number":"211","statement":"Dentro del grupo nuclear ventral del tálamo, ¿qué núcleos actúan como estaciones de relevo motor recibiendo aferencias del globo pálido (ganglios basales) y del núcleo dentado (cerebelo) para proyectar hacia la corteza motora primaria y premotora?:","options":["Núcleos Ventral Anterior (VA) y Ventral Lateral (VL)","Núcleo Ventral PosteroLateral (VPL)","Núcleos Intralaminares","Núcleo Geniculado Lateral (CGL)"],"answer":0,"explanation":"No incluida en el material.","hack":"VA y VL: Núcleos MOTORES del tálamo (reciben de ganglios basales y cerebelo). VPL y VPM: Núcleos SENSITIVOS del tálamo (reciben lemnisco medial, espinotalámico y trigeminal).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-143 / G0891 del banco canónico | integración: Tema 1.6 + Tema 1.9.1 + Tema 1.9.2 + Tema 1.9.3 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: ex. 2021 (respuestas).pdf (Pregunta #27) / TEMA 5 – DIENCÉFALO .pdf / 10-15 Clase_ Ganglios Basales","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-212","number":"212","statement":"Indique la relación anatómica y funcional CORRECTA sobre la trayectoria del fórnix (trígono cerebral) en relación con el diencéfalo:","options":["Formación hipocampal → Fórnix → Cuerpos mamilares del hipotálamo","Área septal → Estría medular → Amígdala","Cuerpos mamilares → Tracto mamilotalámico → Pulvinar","Núcleo arqueado → Tractos tuberohipofisarios → Habénula"],"answer":0,"explanation":"No incluida en el material.","hack":"El fórnix nace en las fimbrias del hipocampo, bordea superiormente al tálamo y sus columnas anteriores descienden en la pared del III ventrículo para sumergirse y terminar en los cuerpos mamilares del hipotálamo. De ahí, el circuito continúa hacia el tálamo por el tracto mamilotalámico (Vicq d'Azyr)1517.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-144 / G0894 del banco canónico | integración: Tema 1.6 + Tema 1.7 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: perguntas neuro julio exame.docx (Pregunta #30) / TEMA 5 – DIENCÉFALO .pdf / 10-06 Clase_ Neuroanatomía del Hipotálamo","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-213","number":"213","statement":"El polo anterior del tálamo presenta una prominencia estrecha denominada tubérculo anterior del tálamo. ¿Con qué estructura anatómica limita directamente este extremo anterior para formar el borde posterior del agujero interventricular (de Monro)?:","options":["Agujero Interventricular (de Monro) / Columnas del Fórnix","Colículo Inferior Mesencefálico","Glándula Pineal","Núcleo Rojo"],"answer":0,"explanation":"No incluida en el material.","hack":"El agujero interventricular (de Monro), que comunica los ventrículos laterales con el tercer ventrículo, está delimitado anteriormente por la columna del fórnix y posteriormente por el polo anterior del tálamo.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-145 / G0895 del banco canónico | integración: Tema 1.6 + Tema 1.7 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: 09-30 Clase_ Diencéfalo / TEMA 5 – DIENCÉFALO .pdf / wuolah-free- EXAMEN-2017-2018-1 orc.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-214","number":"214","statement":"Respecto a los límites y relaciones ventriculares del tálamo y del tercer ventrículo, ¿cuál de las siguientes relaciones anatómicas es CORRECTA?:","options":["El tálamo forma la mayor parte de la pared lateral del tercer ventrículo, separando la cavidad ventricular de la cápsula interna.","El tálamo se ubica en el piso del cuarto ventrículo.","La lámina medular interna separa al tálamo de la corteza de la ínsula.","El tálamo se sitúa ventral respecto al quiasma óptico."],"answer":0,"explanation":"No incluida en el material.","hack":"Anatomía de las Caras del Tálamo: La cara medial del tálamo forma la pared lateral del tercer ventrículo (unidos por la adherencia intertalámica). La cara lateral limita directamente con el brazo posterior de la cápsula interna, que lo separa del núcleo lenticular.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-146 / G0896 del banco canónico | integración: Tema 1.6 + Tema 1.7 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: wuolah-free-PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf / 09-30 Clase_ Diencéfalo / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-215","number":"215","statement":"¿Qué tracto de sustancia blanca eferente hipotalámico comunica directamente los cuerpos mamilares con la formación reticular del tronco del encéfalo para coordinar respuestas vegetativas y somáticas?:","options":["Fascículo mamilotegmental (o tracto mamilotegmentario)","Tracto mamilotalámico (de Vicq d'Azyr)","Fórnix","Estría medular del tálamo"],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Distracción de Eferencias Mamilares: Los cuerpos mamilares emiten dos haces principales que se bifurcan desde el mismo tronco: Tracto Mamilotalámico (Vicq d'Azyr): asciende hacia el núcleo anterior del tálamo (Circuito de Papez / memoria). Tracto Mamilotegmental: desciende hacia la formación reticular del tegmento mesencefálico y pontino (coordinación autonómica).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-147 / G0897 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: 10-06 Clase_ Neuroanatomía del Hipotálamo / TEMA 5 – DIENCÉFALO .pdf / ex. 2021 (respuestas).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-216","number":"216","statement":"Respecto a la neurofisiología hipotalámica y las respuestas autonómicas, ¿qué división del sistema nervioso autónomo es activada preferentemente por la estimulación del hipotálamo anterior y posterior respectivamente?:","options":["Hipotálamo anterior = Parasimpático | Hipotálamo posterior = Simpático","Hipotálamo anterior = Simpático | Hipotálamo posterior = Parasimpático","Ambos estimulan exclusivamente el sistema entérico","El hipotálamo no tiene ninguna influencia sobre el sistema nervioso autónomo"],"answer":0,"explanation":"No incluida en el material.","hack":"Hipotálamo Anterior / Preóptico: Integra respuestas parasimpáticas (disipación de calor, bradicardia, contracción de vejiga, aumento de peristaltismo). Hipotálamo Posterior y Lateral: Integra respuestas simpáticas (generación y conservación de calor, tiritona, taquicardia, midriasis, vasoconstricción).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-148 / G0900 del banco canónico | integración: Tema 1.6 + Tema 1.12 | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: TEMA 5 – DIENCÉFALO .pdf / 09-30 Clase_ Diencéfalo / wuolah-free- Examen-Neuro-recu-junio-2023 orc.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-217","number":"217","statement":"Señala cuál de las siguientes afirmaciones sobre los tractos de conexión del hipotálamo es FALSA:","options":["Los cuerpos mamilares proyectan hacia el núcleo anterior del tálamo mediante el tracto mamilotalámico.","La formación hipocampal envía axones hacia los cuerpos mamilares a través del fórnix (trígono).","El núcleo mamilar se conecta directamente con el núcleo anterior del tálamo a través del fórnix.","El fascículo longitudinal dorsal comunica el hipotálamo con núcleos vegetativos del tronco del encéfalo."],"answer":2,"explanation":"É a afirmação FALSA. A professora enfatiza explicitamente em aula que o fórnix traz axônios do hipocampo para os corpos mamilares, enquanto a conexão dos corpos mamilares com o tálamo anterior é feita pelo trato mamilotalámico, e não pelo fórnix).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-149 / G0905 del banco canónico | integración: Tema 1.6 + Tema 1.7 | referencias indicadas: 10-06 Clase_ Neuroanatomía del Hipotálamo / Nervioso T21-T22-20251006_163846 (Desafio Oral da Professora Aitana)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-218","number":"218","statement":"Indica la afirmación INCORRECTA sobre las modalidades aferentes de los nervios craneales:","options":["La sensibilidad somática general del epitelio corneal es recogida por ramas del nervio oftálmico.","El ganglio geniculado alberga los somas de neuronas que recogen sensibilidad gustativa.","La información somatosensitiva de la lengua es recogida, en parte, por el nervio trigémino.","La faringe es inervada únicamente por ramas del nervio glosofaríngeo."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-150 / G0983 del banco canónico | integración: Tema 1.5.2 + Tema 1.6 | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-219","number":"219","statement":"Indica la respuesta INCORRECTA sobre el tálamo:","options":["Lámina medular interna - Contiene el núcleo centromediano.","Núcleo pulvinar - Localizado en la parte posterior del tálamo.","Núcleo ventral anterior - Núcleo motor que recibe aferencias de los ganglios basales y proyecta a la corteza motora.","Núcleo geniculado lateral - Recibe información auditiva del colículo inferior y proyecta a la corteza auditiva primaria."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-151 / G0993 del banco canónico | integración: Tema 1.6 + Tema 1.7 | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-220","number":"220","statement":"Indica la relación CORRECTA sobre los siguientes tractos:","options":["Formación hipocampal -> Fórnix -> Cuerpos mamilares.","Área septal -> Estría medular -> Amígdala.","Cuerpos mamilares -> Tracto mamilotalámico -> Pulvinar.","Núcleo arqueado -> Tractos tuberohipofisarios -> Habénula."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-152 / G1002 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-221","number":"221","statement":"Con relación al ciclo sueño-vigilia es CIERTO que:","options":["La información lumínica es captada por las células ganglionares W de la retina, cuyos axones llegan hasta el núcleo supraquiasmático del hipotálamo.","La información lumínica induce la síntesis diurna de melatonina por la vía hipotálamopineal.","La actividad colinérgica del tronco encefálico durante la vigilia activa las neuronas GABAérgicas del núcleo reticular del tálamo, lo que inhibe a los núcleos talámicos de relevo sensorial.","La parálisis física durante el sueño REM es consecuencia de la activación de las motoneuronas inferiores de la médula espinal."],"answer":0,"explanation":"NotebookLM - Justificación/Mapa de las Mentiras: Mecanismo Neurológico (Técnica Feynman): Tu cerebro necesita saber si es de día o de noche para calibrar su reloj interno. Para ello, utiliza a unos \"vigilantes solares\" exclusivos en la retina llamados células ganglionares W (intrínsecamente fotosensibles con melanopsina). Estas células ignoran las formas y colores; solo leen la luz ambiental y envían un cable directo (tracto retinohipotalámico) al marcapasos central del cerebro: el núcleo supraquiasmático del hipotálamo. Prueba Teórica Verbatim: \"Información lumínica -> Células ganglionares de la retina (células W) -> Tracto retinohipotalámico -> Núcleo supraquiasmático\". EL MAPA DE LAS MENTIRAS (DISECCIÓN DE DISTRACTORES) Alternativa B: La información lumínica induce la síntesis diurna de melatonina por la vía hipotálamopineal. Por qué es falsa y Hack detectado: Hack 03 (Guerra de Opuestos). La fisiología circadiana dicta que la luz actúa como un FRENADO, no como un acelerador. La luz INHIBE la síntesis de melatonina. Es la \"hormona vampiro\", requiere que llegue la oscuridad para que la glándula pineal la vierta al torrente sanguíneo. Sintetizar melatonina \"diurna\" por estímulo lumínico es biológicamente falso. Corrección: La información lumínica inhibe la síntesis de melatonina. Prueba de Refutación: \"La luz inhibe la producción de melatonina\". Alternativa C: La actividad colinérgica del tronco encefálico durante la vigilia activa las neuronas GABAérgicas del núcleo reticular del tálamo, lo que inhibe a los núcleos talámicos de relevo sensorial. Por qué es falsa y Hack detectado: Cambio de Topografía Temporal (Cronología). El mecanismo anatómico de bloqueos talamocorticales descrito en la opción es estrictamente brillante, PERO el examinador miente en el momento de activación. Este \"escudo\" colinérgico que bloquea las sensaciones se activa DURANTE LA NOCHE (fase de sueño), precisamente para que los estímulos no te despierten, no \"durante la vigilia\". Corrección: Debe decir \"durante el sueño\" en lugar de \"durante la vigilia\". Prueba de Refutación: \"Aumenta esta actividad de las neuronas colinérgicas del tronco del encéfalo por la noche. Activa por lo tanto a este núcleo reticular del tálamo... y por lo tanto el resto de núcleos del tálamo de relevo sensorial están superinhibidos\". Alternativa D: La parálisis física durante el sueño REM es consecuencia de la activación de las motoneuronas inferiores de la médula espinal. Por qué es falsa y Hack detectado: Hack 03 (Guerra de opuestos). La parálisis (atonía) que nos protege de representar físicamente los sueños en la fase REM se logra mediante un candado neuroquímico letal: el tronco encefálico envía un descenso inhibitorio que hiperpolariza (apaga) las motoneuronas alfa de la médula espinal. Si hubiese \"activación\" (excitación), el paciente caminaría, saltaría y golpearía dormido. Corrección: Es consecuencia de la INHIBICIÓN de las motoneuronas inferiores. Prueba de Refutación: \"Aumento de la actividad en las neuronas colinérgicas de la formación reticular pontina -> Inhibición de las motoneuronas inferiores de la médula espinal -> Parálisis física durante el sueño REM\".","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-153 / G1016 del banco canónico | integración: Tema 1.6 + Tema 1.8 + Tema 1.11.1 | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf; tema 1.8 e outros cru notebooklm.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-222","number":"222","statement":"Ordena la secuencia de acontecimientos que tiene lugar en la vía directa de los ganglios basales: 1 - Desinhibición de las proyecciones tálamo-corticales / 2 - Activación del estriado / 3 - Inhibición del globo pálido interno / 4 - Activación cortical","options":["1-2-3-4.","4-3-2-1.","1-3-2-4.","4-2-3-1."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-154 / G1042 del banco canónico | integración: Tema 1.6 + Tema 1.9.2 | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-223","number":"223","statement":"Sobre las conexiones del hipotálamo, es CORRECTO:","options":["Fórnix - Principal eferencia de la amígdala que conecta con los cuerpos mamilares hipotalámicos.","Tracto mamilotalámico - Conecta los cuerpos mamilares con el núcleo anterior del tálamo, componente del circuito de Papez.","Fascículo longitudinal dorsal - Comunica el hipotálamo con la habénula.","Fascículo mamilotegmental - Conecta el hipotálamo con los colículos mesencefálicos."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-155 / G1134 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-224","number":"224","statement":"Con respecto a los neurotransmisores del SNA es FALSO que:","options":["La acetilcolina es el principal neurotransmisor en los ganglios simpáticos y parasimpáticos.","Los efectores del parasimpático presentan receptores para acetilcolina.","Todas las neuronas postganglionares simpáticas liberan noradrenalina.","En el SNA se liberan neurotransmisores diferentes de la noradrenalina y la acetilcolina, como el ATP y el óxido nítrico."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-156 / G1138 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.6 + Tema 1.8 + Tema 1.9.1 + Tema 1.9.3 + Tema 1.10 + Tema 1.11.1 + Tema 1.12 | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-225","number":"225","statement":"En relación al flujo de información por el lóbulo terminal determinante en la génesis de la memoria declarativa, el orden correcto sería:","options":["Áreas de asociación cortical -> Tálamo -> Hipocampo -> Hipotálamo -> Áreas de asociación cortical.","Áreas de asociación cortical -> Hipocampo -> Hipotálamo -> Tálamo -> Áreas de asociación cortical.","Áreas de asociación cortical -> Hipotálamo -> Hipocampo -> Áreas de asociación cortical -> Tálamo.","Áreas de asociación cortical -> Tálamo -> Hipotálamo -> Áreas de asociación cortical."],"answer":1,"explanation":"NotebookLM - Justificación/Mapa de las Mentiras: Mecanismo Neurológico (Técnica Feynman): Para guardar un recuerdo (como qué cenaste ayer), el cerebro usa un circuito cerrado llamado Circuito de Papez. Piensa en ello como una fábrica de procesamiento: la materia prima (lo que ves y oyes) llega desde la Corteza al procesador principal (el Hipocampo). Una vez pre-procesado, se envía por un cable (fórnix) al centro de control autonómico (Hipotálamo - cuerpos mamilares). Este lo remite a la central de envíos (Tálamo anterior), que finalmente devuelve el paquete terminado y etiquetado a la Corteza para su almacenamiento definitivo. Cualquier desviación de este circuito arruina la formación del recuerdo. Prueba Teórica Verbatim: \"Asociación cortical lleva la información hasta el hipocampo... a través de esa corteza entorrenal se produce ese circuito intrahipocámpico... y después desde el hipocampo... van las conexiones a través del fórnix con el hipotálamo... a núcleo anterior del tálamo a través del tracto mamilotalámico y luego del tálamo... a las regiones corticales\". EL MAPA DE LAS MENTIRAS (DISECCIÓN DE DISTRACTORES) Alternativa a): Áreas de asociación cortical -> Tálamo -> Hipocampo -> Hipotálamo -> Áreas de asociación cortical. Por qué es falsa y Hack detectado: Hack 15 (Vectores y Rodovías). El examinador invierte el orden de las estaciones introduciendo el Tálamo ANTES del Hipocampo. En el procesamiento de la memoria declarativa, el hipocampo es el primer gran receptor de las cortezas de asociación; el tálamo opera como la vía de salida final hacia la corteza, no como la de entrada inicial. Corrección: El vector Tálamo debe ir justo después del Hipotálamo. Prueba de Refutación: \"la corteza entorrinal, la principal vía aferente [al hipocampo]... de asociación cortical se comunica con la corteza entorrinal\". Alternativa c): Áreas de asociación cortical -> Hipotálamo -> Hipocampo -> Áreas de asociación cortical -> Tálamo. Por qué es falsa y Hack detectado: Caos estructural masivo (Fusión maliciosa de vías). Coloca al hipotálamo recibiendo información cruda de la corteza para enviarla al hipocampo. Fisiológicamente es un absurdo; el fórnix lleva información DEL hipocampo AL hipotálamo (cuerpos mamilares), jamás al revés en la vía principal de consolidación. Corrección: El Hipocampo siempre precede al Hipotálamo en la dirección del flujo mnésico. Prueba de Refutación: \"axones de la formación hipocampal y se unen para formar el fornix... iría del hipocampo al hipotálamo\". Alternativa d): Áreas de asociación cortical -> Tálamo -> Hipotálamo -> Áreas de asociación cortical. Por qué es falsa y Hack detectado: Supresión de parada obligatoria (Hack 04). El examinador elimina por completo al Hipocampo de la ecuación. Sin hipocampo, es biológicamente imposible consolidar nuevas memorias declarativas (lo que generaría amnesia anterógrada). El circuito carece de su motor principal. Corrección: Es imperativo incluir al Hipocampo como la primera estación profunda tras las áreas de asociación. Prueba de Refutación: \"¿Qué estructuras anatómicas estarían más destacadas en la consolidación de la memoria declarativa? La corteza, hipocampo, el tálamo, el núcleo mamilar, todo lo que sería ese hipocampo y el circuito de Papez\".","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-157 / G1145 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.8 | archivos: tema 1.8 e outros cru notebooklm.pdf | referencias indicadas: tema 1.8 e outros cru notebooklm.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-226","number":"226","statement":"Señale la afirmación incorrecta:","options":["El sincronizador (Zeitgeber) principal es el ciclo luz solar/oscuridad natural","Las ondas β son ondas de alta amplitud y baja frecuencia","Las células que expresan los genes c son características del núcleo supraquiasmático","Los axones de la vía retinohipotalámica proceden de las células ganglionares intrínsecamente fotosensibles"],"answer":1,"explanation":"NotebookLM - Justificación/Mapa de las Mentiras: Mecanismo Neurológico (Técnica Feynman): Las ondas Beta (β) representan al cerebro en estado de \"alerta máxima y concentración\" (vigilia activa). En este estado, miles de neuronas están procesando información distinta al mismo tiempo (desincronización). Al no disparar juntas, sus corrientes eléctricas se anulan parcialmente entre sí, generando un trazado muy \"bajito\" (baja amplitud) pero extremadamente \"rápido\" (alta frecuencia, >14 Hz). El examinador usa el Hack 03 (Guerra de Opuestos) para invertir deliberadamente las propiedades físicas de la onda, describiendo exactamente lo contrario: las ondas lentas y profundas (Delta) características del coma o el sueño profundo. Prueba Teórica Verbatim: \"Incorrecta la B: las ondas beta son de baja amplitud y alta frecuencia, no de alta amplitud y baja frecuencia\" (Extraído literalmente de las notas de corrección del Tema 1.8). EL MAPA DE LAS MENTIRAS (DISECCIÓN DE DISTRACTORES) Alternativa a): El sincronizador (Zeitgeber) principal es el ciclo luz solar/oscuridad natural. Por qué es falsa y Hack detectado: Falsa como opción a marcar porque es un axioma fisiológico 100% VERDADERO. El ciclo ambiental de luz y oscuridad es el \"relojero\" principal que calibra el ritmo biológico de 24 horas del cerebro. Hack de distractor sano. Corrección: No requiere corrección, es exacta. Prueba de Refutación: \"el sincronizador (Zeitgeber) principal es el ciclo luz solar/oscuridad natural\" (Axioma consolidado en las baterías de preguntas repetidas de ritmos circadianos). Alternativa c): Las células que expresan los genes c son características del núcleo supraquiasmático. Por qué es falsa y Hack detectado: Falsa como opción a marcar porque neuroanatómicamente es VERDADERA. El núcleo supraquiasmático del hipotálamo es el marcapasos maestro del cuerpo, y utiliza proteínas intracelulares llamadas \"genes reloj\" (c genes) para sostener su oscilación rítmica endógena. Corrección: No requiere corrección. Prueba de Refutación: \"Las células que expresan los genes c son características del núcleo supraquiasmático\" (Afirmación ratificada como correcta en los históricos oficiales de la profesora). Alternativa d): Los axones de la vía retinohipotalámica proceden de las células ganglionares intrínsecamente fotosensibles. Por qué es falsa y Hack detectado: Falsa como opción a marcar porque describe una excepción biológica VERDADERA (Hack 04). Aunque la regla general dice que solo los conos y bastones detectan luz, existe una ruta especial (vía retinohipotalámica) donde una subpoblación de células ganglionares con melanopsina son \"intrínsecamente fotosensibles\". Ellas \"ven\" la luminosidad ambiental y le avisan directamente al hipotálamo para frenar la melatonina, sin usar los fotorreceptores clásicos. Corrección: No requiere corrección, la fisiología de la vía es impecable. Prueba de Refutación: \"Los axones de la vía retinohipotalámica proceden de las células ganglionares intrínsecamente fotosensibles\" (Literal extraído y validado por la cátedra en el examen de 2021).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-158 / G1150 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.8 | archivos: tema 1.8 e outros cru notebooklm.pdf | referencias indicadas: tema 1.8 e outros cru notebooklm.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-227","number":"227","statement":"En relación a los ciclos de sueño/vigilia, señale la relación CORRECTA:","options":["Fase NO REM -> inhibición activa y total por parte del tronco del encéfalo de la actividad de las motoneuronas inferiores de la médula espinal.","Complejo K -> onda de entre 8-14 Hz que caracteriza a los estadios 3 y 4 del sueño NO REM.","Fase REM -> se caracteriza por la elevada actividad del sistema difuso noradrenérgico y la baja o nula actividad de los sistemas difusos serotoninérgicos y acetilcolinérgico.","Glándula pineal -> recibe fibras postganglionares simpáticas procedentes del ganglio cervical superior."],"answer":3,"explanation":"NotebookLM - Justificación/Mapa de las Mentiras: Mecanismo Neurológico (Técnica Feynman): La glándula pineal es la encargada de liberar melatonina (la hormona que te da sueño) cuando oscurece. Aunque solemos asociar el sueño con el estado de \"descanso\" parasimpático, la orden neurológica para que esta glándula trabaje llega a través de una autopista del Sistema Nervioso SIMPÁTICO. El marcapasos del cerebro (núcleo supraquiasmático) manda la señal por la médula, sale hacia el ganglio cervical superior en el cuello, y de ahí suben las fibras simpáticas hasta la glándula pineal. Es una excepción contraintuitiva fundamental. Prueba Teórica Verbatim: \"glándula pineal -> recibe fibras postganglionares simpáticas del ganglio cervical superior\". EL MAPA DE LAS MENTIRAS (DISECCIÓN DE DISTRACTORES) Alternativa a.: Fase NO REM -> inhibición activa y total por parte del tronco del encéfalo de la actividad de las motoneuronas inferiores de la médula espinal. Por qué es falsa y Hack detectado: Hack 18 (Conceptos Contraintuitivos) y Hack 15 (Cambio de Topografía Temporal). El examinador traslada el mecanismo de parálisis de una fase a otra. La inhibición letal de las motoneuronas (atonía muscular profunda para evitar que actúes tus sueños) ocurre EXCLUSIVAMENTE en la Fase REM. En el sueño NO-REM aún conservas tono muscular e incluso puedes moverte involuntariamente. Corrección: La inhibición activa y total de las motoneuronas inferiores ocurre en la fase REM. Prueba de Refutación: \"Fase REM - Inhibición activa por parte del tronco del encéfalo de la actividad de la motoneurona inferior\". Alternativa b.: Complejo K -> onda de entre 8-14 Hz que caracteriza a los estadios 3 y 4 del sueño NO REM. Por qué es falsa y Hack detectado: Fusión Maliciosa Numérica y de Vías (Hack 24). El examinador choca tres realidades distintas: 1) El complejo K y los husos del sueño (ondas 12-14 Hz) son los \"guardianes\" exclusivos del estadio 2 del sueño NO-REM, no del 3 y 4. 2) Los estadios 3 y 4 se caracterizan por las ondas lentas Delta (<4 Hz). Corrección: Complejo K y husos del sueño caracterizan al estadio 2 del sueño NO-REM. Prueba de Refutación: \"estadío dos tiene unas ondas que son un poco indefinidas... usos de sueño [husos] y complejos K característicos de los estadios dos del sueño NO REM\". Alternativa c.: Fase REM -> se caracteriza por la elevada actividad del sistema difuso noradrenérgico y la baja o nula actividad de los sistemas difusos serotoninérgicos y acetilcolinérgico. Por qué es falsa y Hack detectado: Hack 03 (Guerra de Opuestos). El examinador invierte completamente la neuroquímica cerebral del sueño REM. Durante el REM, el cerebro necesita encender sus pantallas visuales para \"alucinar\" los sueños. Para ello, el sistema Acetilcolinérgico (colinérgico) está ALTAMENTE ACTIVO (dispara la vigilia onírica). Por el contrario, la noradrenalina y serotonina están apagadas. Corrección: La fase REM presenta elevada actividad acetilcolinérgica y nula actividad noradrenérgica/serotoninérgica. Prueba de Refutación: \"Fase REM - se caracteriza por... la baja o nula actividad de los sistemas serotoninérgicos [y noradrenérgicos]\".","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-159 / G1153 del banco canónico | integración: Tema 1.6 + Tema 1.8 + Tema 1.12 | archivos: tema 1.8 e outros cru notebooklm.pdf | referencias indicadas: tema 1.8 e outros cru notebooklm.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-228","number":"228","statement":"Señale la afirmación CORRECTA en relación al ciclo vigilia/sueño:","options":["La unión de la adenosina a sus receptores en las neuronas de los núcleos moduladores difusos aumenta la actividad de estas neuronas.","El tronco del encéfalo potencia las órdenes motoras procedentes de la corteza motora primaria durante la fase REM.","Durante la fase REM del sueño hay una elevada actividad del sistema difuso noradrenérgico.","La luz inhibe la producción de melatonina."],"answer":3,"explanation":"Mecanismo Neurológico (Técnica Feynman): El ciclo circadiano funciona con un interruptor solar directo. Cuando tus células retinianas especiales ven la luz del día, envían un \"freno\" eléctrico al hipotálamo, que a su vez bloquea la glándula pineal. Sin luz (oscuridad), el freno se suelta y la glándula pineal comienza a inundar tu cerebro con Melatonina, la \"hormona vampiro\" que te induce el sueño. Prueba Teórica Verbatim: \"La luz inhibe la producción de melatonina\". NotebookLM - Justificación/Mapa de las Mentiras: EL MAPA DE LAS MENTIRAS (DISECCIÓN DE DISTRACTORES) Alternativa a): La unión de la adenosina a sus receptores en las neuronas de los núcleos moduladores difusos aumenta la actividad de estas neuronas. Por qué es falsa y Hack detectado: Hack 03 (Guerra de Opuestos). La adenosina es la molécula del \"cansancio acumulado\". Se acumula durante el día y se une a los núcleos del tronco encefálico para INHIBIRLOS, apagando los sistemas de alerta (colinérgico, noradrenérgico) y obligándote a dormir. No \"aumenta\" su actividad, la suprime. Corrección: La unión de adenosina INHIBE/DISMINUYE la actividad de las neuronas de los núcleos difusos de alerta. Prueba de Refutación: (Axioma teórico del departamento): \"La cafeína es un antagonista de los receptores de adenosina; al bloquearla, previene la inhibición y nos mantiene alerta\". Alternativa b): El tronco del encéfalo potencia las órdenes motoras procedentes de la corteza motora primaria durante la fase REM. Por qué es falsa y Hack detectado: Hack 24 (Vectores Fisiológicos Invertidos). ¡Peligro de suicidio onírico! En la fase REM tu cerebro genera órdenes motoras reales (correr, pelear), pero el tronco encefálico interviene drásticamente para INHIBIR (paralizar) a las motoneuronas de la médula espinal. Si las \"potenciara\", actuarías físicamente tus sueños. Corrección: El tronco del encéfalo INHIBE las órdenes motoras durante la fase REM. Prueba de Refutación: \"Fase REM - Inhibición activa por parte del tronco del encéfalo de la actividad de la motoneurona inferior\". Alternativa c): Durante la fase REM del sueño hay una elevada actividad del sistema difuso noradrenérgico. Por qué es falsa y Hack detectado: Hack de Sustitución Neuroquímica. Durante el sueño REM (la \"vigilia onírica\"), el cerebro apaga casi por completo los sistemas noradrenérgico y serotoninérgico. El único sistema que dispara con elevada actividad para encender la pantalla visual de los sueños es el ACETILCOLINÉRGICO. Corrección: Durante la fase REM hay una baja o nula actividad del sistema noradrenérgico. Prueba de Refutación: \"Fase REM - se caracteriza por... la baja o nula actividad de los sistemas difusos serotoninérgicos y noradrenérgicos\".","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-160 / G1166 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: tema 1.8 e outros cru notebooklm.pdf | referencias indicadas: tema 1.8 e outros cru notebooklm.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-229","number":"229","statement":"Señale la afirmación INCORRECTA:","options":["Gracias a la expresión de genes reloj, el núcleo supraquiasmático actúan como un \"marcapasos\" interno capaz de regular ciertos ritmos biológicos.","Evidencias experimentales indican que un aumento de serotonina aumenta la agresividad.","El giro angular se comunica con el área de Wernicke. Dicha comunicación es importante en el procesamiento funcional del lenguaje.","Los axones de la vía retinohipotalámica proceden de las células ganglionares intrínsecamente fotosensibles."],"answer":1,"explanation":"NotebookLM - Justificación/Mapa de las Mentiras: Mecanismo Neurológico (Técnica Feynman): La serotonina es el \"chupete\" neuroquímico del cerebro; su función en el sistema límbico es calmar la ira y promover el autocontrol. La relación biológica entre este neurotransmisor y la violencia es estrictamente una balanza invertida: si la serotonina sube, la agresividad baja drásticamente. El examinador utiliza el Hack 03 (Guerra de Opuestos) para engañar al estudiante haciéndole creer que una mayor cantidad de químico excitador generará una respuesta conductual más fuerte. Prueba Teórica Verbatim: \"serotonina se relacionaba con la agresividad de forma... inversamente proporcional. Serotonina y agresividad. invers[amente proporcional]\". EL MAPA DE LAS MENTIRAS (DISECCIÓN DE DISTRACTORES) Alternativa a.: Gracias a la expresión de genes reloj, el núcleo supraquiasmático actúan como un \"marcapasos\" interno capaz de regular ciertos ritmos biológicos. Por qué es falsa y Hack detectado: Falsa como opción a marcar porque el enunciado pide la INCORRECTA, y esta es un axioma fisiológico 100% VERDADERO. El núcleo supraquiasmático es el reloj biológico central. Distractor sano. Corrección: No requiere corrección. Prueba de Refutación: \"Las células que expresan los genes c son características del núcleo supraquiasmático\" (Afirmación ratificada en los historiales del banco). Alternativa c.: El giro angular se comunica con el área de Wernicke. Dicha comunicación es importante en el procesamiento funcional del lenguaje. Por qué es falsa y Hack detectado: Falsa como opción a marcar porque es neuroanatómicamente EXACTA. El giro angular toma lo que ves escrito y lo envía a Wernicke para que el cerebro lo comprenda fonológicamente. Corrección: No requiere corrección. Prueba de Refutación: \"desde la corteza visual primaria... suele ser un relevo intermedio en este giro angular... hasta llegar al área de Wernicke\". Alternativa d.: Los axones de la vía retinohipotalámica proceden de las células ganglionares intrínsecamente fotosensibles. Por qué es falsa y Hack detectado: Falsa como opción a marcar porque describe una excepción biológica VERDADERA (Hack 04). Una subpoblación de células ganglionares con melanopsina (células W) captan luz por sí mismas sin usar conos ni bastones, enviando el cable directo al hipotálamo para avisar que es de día. Corrección: No requiere corrección. Prueba de Refutación: \"Información lumínica -> Células ganglionares de la retina (células W) -> Tracto retinohipotalámico -> Núcleo supraquiasmático\".","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-161 / G1169 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.8 | archivos: tema 1.8 e outros cru notebooklm.pdf | referencias indicadas: tema 1.8 e outros cru notebooklm.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-230","number":"230","statement":"En relación a los ritmos cerebrales, indique la afirmación CORRECTA:","options":["En las neuronas de los sistemas moduladores difusos, la unión de la adenosina a su receptor provoca la excitación de la neurona.","En la producción de melatonina en oscuridad se produce un aumento de la síntesis de proteínas, en concreto del enzima triptófano hidroxilasa.","Cuando hay luz, el núcleo supraquiasmático ejerce sinapsis gabaérgicas sobre el núcleo paraventricular.","El pinealocito (célula de la glándula pineal) recibe una importante inervación parasimpática."],"answer":2,"explanation":"NotebookLM - Justificación/Mapa de las Mentiras: Mecanismo Neurológico (Técnica Feynman): Para mantenerte despierto durante el día, tu reloj maestro (el núcleo supraquiasmático) debe \"frenar\" a la glándula pineal para que no segregue melatonina (la hormona que te da sueño). ¿Cómo lo hace? Mandando GABA (el neurotransmisor inhibidor universal) hacia la siguiente estación de relevo, el núcleo paraventricular. Al inhibir este núcleo, se corta la cadena de mando simpática, y la glándula pineal se queda apagada. Prueba Teórica Verbatim: \"La luz inhibe la producción de melatonina\" (el mecanismo intracortical detallado en las diapositivas de ritmos circadianos avala este vector inhibitorio descendente). EL MAPA DE LAS MENTIRAS (DISECCIÓN DE DISTRACTORES) Alternativa a.: En las neuronas de los sistemas moduladores difusos, la unión de la adenosina a su receptor provoca la excitación de la neurona. Por qué es falsa y Hack detectado: Hack 03 (Guerra de Opuestos). La adenosina es la molécula del \"cansancio químico\" que se acumula en tu cerebro a medida que pasan las horas. Al unirse a su receptor, INHIBE (apaga) a las neuronas del tronco encefálico para obligarte a dormir. Nunca las excita. (Por eso la cafeína, al bloquear este receptor, te mantiene despierto). Corrección: La unión de la adenosina a su receptor provoca la INHIBICIÓN de la neurona. Prueba de Refutación: (Axioma teórico derivado del apunte 1.8 de neuroquímica del sueño). Alternativa b.: En la producción de melatonina en oscuridad se produce un aumento de la síntesis de proteínas, en concreto del enzima triptófano hidroxilasa. Por qué es falsa y Hack detectado: Hack de Sustitución Enzimática. Aunque la melatonina es pariente de la serotonina (derivada del triptófano), la enzima que dispara su síntesis nocturna masiva en la glándula pineal es la N-acetiltransferasa (NAT), no la triptófano hidroxilasa. Corrección: En la oscuridad se produce un aumento de la enzima N- acetiltransferasa (NAT). Prueba de Refutación: Las fuentes actuales no contienen la justificación teórica para esta alternativa microscópica, pero se penaliza en los históricos como distractor bioquímico. Alternativa d.: El pinealocito (célula de la glándula pineal) recibe una importante inervación parasimpática. Por qué es falsa y Hack detectado: Hack 24 (Vectores Clínicos Invertidos). Aunque asociamos el sueño al relax y al sistema parasimpático, la orden para encender la glándula pineal y fabricar melatonina desciende por la médula y sube a través del Ganglio Cervical Superior, usando un cable 100% SIMPÁTICO. Corrección: El pinealocito recibe inervación SIMPÁTICA (del ganglio cervical superior). Prueba de Refutación: \"glándula pineal -> recibe fibras postganglionares simpáticas procedentes del ganglio cervical superior\".","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-162 / G1171 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: tema 1.8 e outros cru notebooklm.pdf | referencias indicadas: tema 1.8 e outros cru notebooklm.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-231","number":"231","statement":"Seleccione la relación CORRECTA sobre el sistema límbico:","options":["Estría terminal -> discurre inferolateralmente con respecto al tálamo.","Cuerpo amigdalino -> recibe aferencias de estructuras como el hipotálamo, el bulbo olfatorio o el troncoencéfalo.","Giro dentado -> presenta 3 capas (molecular, piramidal y polimorfa) y recibe aferencias desde la corteza entorrinal y el subículo.","Núcleo accumbens -> localizado en el lóbulo occipital, es una estructura del circuito de la recompensa que se comunica con la corteza prefrontal a través del fascículo longitudinal superior."],"answer":1,"explanation":"NotebookLM - Justificación/Mapa de las Mentiras: Mecanismo Neurológico (Técnica Feynman): La amígdala es la alarma de incendios del cerebro. Para saber si hay peligro, necesita que los \"sensores\" del edificio le envíen información constante. Por eso recibe cables (aferencias) directos desde el bulbo olfatorio (puedes asustarte al oler humo o gas), del hipotálamo y troncoencéfalo (para registrar el estado visceral, como el ritmo cardíaco acelerado), procesando estas señales crudas para disparar la respuesta de miedo. Prueba Teórica Verbatim: Las fuentes actuales no contienen la justificación teórica para esta alternativa en la transcripción literal, pero en el material oficial de la clase 10-08 se asume esta extensa red aferente límbica para el procesamiento del miedo primitivo. EL MAPA DE LAS MENTIRAS (DISECCIÓN DE DISTRACTORES) Alternativa a): Estría terminal -> discurre inferolateralmente con respecto al tálamo. Por qué es falsa y Hack detectado: Hack de Coordenadas Cruzadas. La estría terminal (el gran cable de salida de la amígdala) discurre alojada en el surco terminal, el cual se ubica en la posición SUPERIOR (dorsal) y medial entre el núcleo caudado y el tálamo, no inferolateral. Corrección: La estría terminal discurre superiormente con respecto al tálamo. Prueba de Refutación: Las fuentes actuales no contienen la justificación teórica para esta alternativa exacta, pero estructuralmente rodea el tálamo dorsalmente. Alternativa c): Giro dentado -> presenta 3 capas (molecular, piramidal y polimorfa) y recibe aferencias desde la corteza entorrinal y el subículo. Por qué es falsa y Hack detectado: Sustitución Histológica Maliciosa. El examinador toma una verdad (son 3 capas por ser paleocorteza) y altera una sola palabra intermedia. El giro dentado se llama así porque contiene células GRANULARES, no piramidales (las piramidales son exclusivas del hipocampo propio CA1-CA3). Corrección: Presenta capas molecular, GRANULOSA y polimorfa. Prueba de Refutación: \"Los axones de las células granulares del giro dentado (fibras musgosas) sinaptan con las células piramidales CA3\" (Demostrando que el giro dentado es territorio granular, no piramidal). Alternativa d): Núcleo accumbens -> localizado en el lóbulo occipital, es una estructura del circuito de la recompensa que se comunica con la corteza prefrontal a través del fascículo longitudinal superior. Por qué es falsa y Hack detectado: Desplazamiento Anatómico Masivo (Hack 15). El núcleo accumbens es el centro neurálgico del placer y la motivación. Pertenece a los ganglios basales (estriado ventral) y se encuentra hundido en la base del lóbulo FRONTAL, justo debajo de la cabeza del núcleo caudado. Trasladarlo al lóbulo occipital (el polo de la visión en la nuca) es un absurdo anatómico. Corrección: El núcleo accumbens está localizado en la base del lóbulo frontal (prosencéfalo basal). Prueba de Refutación: \"Núcleo accumbens... es una estructura del circuito de recompensa que se comunica con la corteza prefrontal\" (Reside frontalmente para esta comunicación corta).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-163 / G1173 del banco canónico | integración: Tema 1.6 + Tema 1.8 + Tema 1.11.3 | archivos: tema 1.8 e outros cru notebooklm.pdf | referencias indicadas: tema 1.8 e outros cru notebooklm.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-232","number":"232","statement":"Las neuronas del núcleo anterior del tálamo:","options":["Mandan axones a los núcleos (ganglios) basales.","Mandan axones al área prefrontal de la corteza.","Mandan axones a la circunvolución del cíngulo.","Mandan axones a la corteza motora primaria."],"answer":2,"explanation":"NotebookLM - Justificación/Mapa de las Mentiras: Mecanismo Neurológico (Técnica Feynman): Para guardar permanentemente el recuerdo de tu primer beso, tu cerebro usa el Circuito de Papez, una cinta transportadora cerrada. El hipocampo se lo envía al hipotálamo (cuerpos mamilares); el hipotálamo se lo envía al núcleo anterior del tálamo. ¿Y qué hace este núcleo talámico? Su única misión en este circuito es lanzar la información hacia arriba, entregando el paquete mnésico a la circunvolución del cíngulo (Corteza Cingulada), para que el recuerdo emocional cobre consciencia y pueda archivarse. Prueba Teórica Verbatim: \"van las conexiones a través del fórnix con el hipotálamo... a núcleo anterior del tálamo a través del tracto mamilotalámico y luego del tálamo... a las regiones corticales [cíngulo]\". EL MAPA DE LAS MENTIRAS (DISECCIÓN DE DISTRACTORES) Alternativa a): Mandan axones a los núcleos (ganglios) basales. Por qué es falsa y Hack detectado: Hack de Vectores Motor-Sensitivo. Los ganglios basales operan al revés: ellos envían información al tálamo (núcleos ventrales) para que el tálamo la rebote a la corteza motora. El núcleo anterior del tálamo es puramente límbico/memoria, no se ensucia con los circuitos automáticos del movimiento. Corrección: El tálamo motor (VA/VL) recibe de los ganglios basales y proyecta a la corteza, no al revés en la vía principal. Prueba de Refutación: \"En la vía directa, la dopamina liberada... actúa sobre receptores ubicados en neoestriado... para activar el tálamo\". Alternativa b): Mandan axones al área prefrontal de la corteza. Por qué es falsa y Hack detectado: Fusión de Vías Límbicas. Existe un núcleo del tálamo que SÍ proyecta masivamente al lóbulo prefrontal para regular la conducta, pero es el Núcleo Mediodorsal, no el anterior. El núcleo anterior del tálamo es esclavo topográfico exclusivo del giro cingulado dentro de Papez. Corrección: El núcleo mediodorsal del tálamo es el que manda axones masivos al prefrontal. Prueba de Refutación: (Concepto derivado de la cartografía talámica del Tema 1.6, donde el núcleo anterior se asocia 100% al sistema límbico mamilar-cingulado). Alternativa d): Mandan axones a la corteza motora primaria. Por qué es falsa y Hack detectado: Fusión Maliciosa Funcional. El examinador utiliza los núcleos talámicos de relevo motor (Ventral Anterior y Ventral Lateral), que son los que devuelven la señal del cerebelo y ganglios basales a la corteza motora primaria. El núcleo anterior no participa en absoluto en levantar un brazo. Corrección: Los núcleos Ventral Lateral y Ventral Anterior (VL/VA) del tálamo mandan axones a la corteza motora primaria. Prueba de Refutación: \"Las neuronas de Purkinje sinaptan, fundamentalmente, sobre los núcleos ventral anterior (VA) y ventral lateral (VL) del tálamo [para influir en el córtex motor]\".","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-164 / G1178 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: tema 1.8 e outros cru notebooklm.pdf | referencias indicadas: tema 1.8 e outros cru notebooklm.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-233","number":"233","statement":"Indique la relación CORRECTA sobre el diencéfalo:","options":["Núcleo reticular del tálamo -> inhibidor (con GABA) de las neuronas de relevo talámico, especialmente evidente durante el sueño.","Núcleo paraventricular del hipotálamo -> participa en la regulación de la sed pero no está implicado en la regulación del balance energético corporal.","Habénula -> estructura hipotalámica relacionada con el sentido del olfato y del gusto.","Órgano subfornicial -> órgano circunventricular cuya principal función es regular la temperatura corporal."],"answer":0,"explanation":"NotebookLM - Justificación/Mapa de las Mentiras: Mecanismo Neurológico (Técnica Feynman): Para poder dormirte (entrar en fase NO-REM 2), tu cerebro necesita bajar las persianas y dejar de sentir las sábanas o escuchar ruidos de fondo. El Tálamo es la \"puerta de entrada\" de todos los sentidos. El Núcleo Reticular es una capa de neuronas que envuelve al tálamo como un escudo. Cuando llega la noche, este escudo se activa y dispara ráfagas de GABA (el neurotransmisor inhibidor que apaga sistemas). Al llenar de GABA a los demás núcleos del tálamo, la puerta de los sentidos se bloquea, generando los famosos \"husos del sueño\" en el EEG y permitiendo que te quedes profundamente dormido. Prueba Teórica Verbatim: \"Activa por lo tanto a este núcleo reticular del tálamo... y por lo tanto el resto de núcleos del tálamo de relevo sensorial están superinhibidos [para bloquear la vigilia y consolidar el sueño]\". EL MAPA DE LAS MENTIRAS (DISECCIÓN DE DISTRACTORES) Alternativa b.: Núcleo paraventricular del hipotálamo -> participa en la regulación de la sed pero no está implicado en la regulación del balance energético corporal. Por qué es falsa y Hack detectado: Hack 05 (Negación Absoluta \"no está implicado\"). El núcleo paraventricular es un nodo maestro del hipotálamo. No solo regula el agua (vía ADH/Vasopresina), sino que regula masivamente el balance energético a través del eje tiroideo (TRH) y del estrés (CRH/Cortisol), alterando tu metabolismo celular. Corrección: Sí está íntimamente implicado en el balance energético y metabólico. Prueba de Refutación: \"El núcleo paraventricular no funciona (está inhibido) cuando los niveles de leptina son muy elevados\" (Esta afirmación distractor de otro año demuestra que el paraventricular ES un blanco directo de la leptina y por ende regula la energía y saciedad). Alternativa c.: Habénula -> estructura hipotalámica relacionada con el sentido del olfato y del gusto. Por qué es falsa y Hack detectado: Hack de Coordenadas Estructurales. La habénula (núcleos habenulares) NO pertenece al hipotálamo en absoluto. Es la estructura sagrada del EPITÁLAMO (junto con la glándula pineal), conectada a través de la estría medular. Corrección: La habénula es una estructura EPITALÁMICA. Prueba de Refutación: \"Núcleos habenulares -> son parte del epitálamo\" (Gabarito oficial consolidado de la cátedra para el Tema 1.6). Alternativa d.: Órgano subfornicial -> órgano circunventricular cuya principal función es regular la temperatura corporal. Por qué es falsa y Hack detectado: Hack de Fusión Fisiológica. El órgano subfornicial es un radar libre de barrera hematoencefálica, pero su trabajo es \"probar\" la sangre para medir la OSMOLARIDAD (la concentración de sal) y desatar la conducta de la SED, no la temperatura. La temperatura se regula en el núcleo anterior/preóptico del hipotálamo. Corrección: El órgano subfornicial regula el balance hídrico y la sed. Prueba de Refutación: \"En el mecanismo regulador de la sed osmométrica, el órgano vasculoso de la lámina terminal (OVLT) y el órgano subfornicial...\" (Ambos son los radares de la sed volumétrica/osmométrica).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-165 / G1195 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: tema 1.8 e outros cru notebooklm.pdf | referencias indicadas: tema 1.8 e outros cru notebooklm.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-234","number":"234","statement":"Seleccione la respuesta CORRECTA:","options":["La corteza entorrinal y el hipocampo se comunican entre sí a través de un conjunto de fibras denominado fórnix (o trígono).","El giro precentral alberga la corteza somatosensitiva.","Las neuronas piramidales de mayor tamaño se encuentran en la capa granulosa interna de la neocorteza.","La cápsula interna separa el tálamo del núcleo lenticular."],"answer":3,"explanation":"NotebookLM - Justificación/Mapa de las Mentiras: Mecanismo Neurológico (Técnica Feynman): Imagina el centro del cerebro como una carretera con dos grandes edificios a los lados. La cápsula interna es una supercarretera de sustancia blanca en forma de \"V\". Su brazo posterior funciona como una frontera física irrompible: de un lado de la carretera está el Tálamo (más hacia el centro) y del otro lado está el Núcleo Lenticular (globo pálido + putamen, hacia afuera). Prueba Teórica Verbatim: \"la cápsula interna... es una sustancia blanca que, como veis, separa los ganglios basales [núcleo lenticular] del tálamo\". EL MAPA DE LAS MENTIRAS (DISECCIÓN DE DISTRACTORES) Alternativa a.: La corteza entorrinal y el hipocampo se comunican entre sí a través de un conjunto de fibras denominado fórnix (o trígono). Por qué es falsa y Hack detectado: Hack 15 (Vectores y Puertas Invertidas). La entrada de la memoria desde la corteza entorrinal hacia el hipocampo se realiza por la VÍA PERFORANTE. El fórnix es la puerta de SALIDA masiva del hipocampo hacia el hipotálamo, no su cable de comunicación de entrada con la entorrinal. Corrección: Se comunican a través de la vía perforante. El fórnix comunica el hipocampo con los núcleos mamilares. Prueba de Refutación: \"La principal aferencia es la vía perforante que se proyecta desde la corteza entorrinal... La principal eferencia es el fórnix\". Alternativa b.: El giro precentral alberga la corteza somatosensitiva. Por qué es falsa y Hack detectado: Hack 03 (Guerra de Opuestos Frontal-Parietal). El \"surco central\" (de Rolando) divide tu cerebro en dos mundos. Todo lo que está por DELANTE (giro precentral) es el lóbulo frontal y es estrictamente MOTOR. Todo lo que está por DETRÁS (giro postcentral) es el lóbulo parietal y es estrictamente SENSITIVO. Corrección: El giro precentral alberga la corteza MOTORA primaria. Prueba de Refutación: \"Corteza somatosensorial primaria -> el pie está representado en la cara medial del giro post-central\" y \"El área 4 de Brodmann [motora] se localiza en la circunvolución precentral\". Alternativa c.: Las neuronas piramidales de mayor tamaño se encuentran en la capa granulosa interna de la neocorteza. Por qué es falsa y Hack detectado: Desplazamiento Histológico (Sustitución de Piso). Las neuronas piramidales gigantes (Células de Betz), encargadas de enviar axones hasta la médula, residen exclusivamente en la Capa V (Piramidal Interna). La Capa IV (Granulosa Interna) está llena de células granulares pequeñas para RECIBIR sensibilidad del tálamo, no emite axones motores masivos. Corrección: Se encuentran en la capa PIRAMIDAL INTERNA (Capa V). Prueba de Refutación: \"En el área 4 de Brodmann abundan las neuronas piramidales gigantes (o de Betz) en la capa V\".","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-166 / G1203 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.8 | archivos: tema 1.8 e outros cru notebooklm.pdf | referencias indicadas: tema 1.8 e outros cru notebooklm.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-235","number":"235","statement":"Señale la afirmación INCORRECTA:","options":["El sincronizador (zeitgeber) principal es el ciclo luz solar/oscuridad natural.","Las ondas beta son ondas de alta amplitud y baja frecuencia.","Las células que expresan los genes c son características del núcleo supraquiasmático.","Los axones de la vía retinohipotalámica proceden de las células ganglionares intrínsecamente fotosensibles."],"answer":1,"explanation":"NotebookLM - Justificación/Mapa de las Mentiras: Mecanismo Neurológico (Técnica Feynman): El ritmo eléctrico del cerebro es un espejo de su trabajo. Cuando estás en \"Vigilia Activa\" estudiando para un examen (ondas Beta), miles de circuitos corticales distintos disparan a destiempo resolviendo problemas. Esto genera una interferencia eléctrica (\"asincronía\") que dibuja ondas muy pequeñas (BAJA AMPLITUD), pero rapidísimas (ALTA FRECUENCIA, 15-30 Hz). El examinador usa el Hack 03 (Guerra de Opuestos Cruzados), invirtiendo por completo las propiedades físicas de la onda para crear el distractor letal. Las ondas de \"alta amplitud y baja frecuencia\" son en realidad las ondas Delta del sueño profundo (las neuronas laten juntas lentamente). Prueba Teórica Verbatim: \"Ondas beta (15-30 Hz) -> Aparecen cuando el sistema nervioso se activa... Las ondas beta son de baja amplitud y alta frecuencia\". EL MAPA DE LAS MENTIRAS (DISECCIÓN DE DISTRACTORES) Alternativa a.: El sincronizador (zeitgeber) principal es el ciclo luz solar/oscuridad natural. Por qué es falsa y Hack detectado: Falsa como opción a marcar porque el enunciado pide la INCORRECTA, y esta es un axioma biofísico 100% VERDADERO. La rotación de la tierra (luz/oscuridad) es el \"dador de tiempo\" supremo que ajusta nuestro reloj interno. Corrección: No requiere corrección. Prueba de Refutación: (Concepto validado en la apertura de Ritmos Circadianos: la luz ambiental resetea el ciclo de 24h mediante el tracto retinohipotalámico). Alternativa c.: Las células que expresan los genes c son características del núcleo supraquiasmático. Por qué es falsa y Hack detectado: Falsa como opción a marcar porque es CIERTA. Estas células fabrican y degradan proteínas (\"genes c /per\") en un bucle temporal exacto de casi 24 horas, funcionando como el engranaje del reloj. Corrección: No requiere corrección. Prueba de Refutación: \"Las células que expresan los genes c son características del núcleo supraquiasmático\". Alternativa d.: Los axones de la vía retinohipotalámica proceden de las células ganglionares intrínsecamente fotosensibles. Por qué es falsa y Hack detectado: Falsa como opción a marcar porque es CIERTA (Hack de Excepción Absoluta). Normalmente las células ganglionares no \"ven\" la luz, solo transmiten. Pero una subpoblación rebelde (Células W con melanopsina) sí \"ven\" la luminosidad ambiental y mandan el cable directo al hipotálamo sin pasar por conos ni bastones. Corrección: No requiere corrección. Prueba de Refutación: \"Información lumínica -> Células ganglionares de la retina (células W) -> Tracto retinohipotalámico\".","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-167 / G1205 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.8 | archivos: tema 1.8 e outros cru notebooklm.pdf | referencias indicadas: tema 1.8 e outros cru notebooklm.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-236","number":"236","statement":"¿Cuál de las siguientes afirmaciones sobre la estructura laminar de las áreas corticales (neocórtex) es CORRECTA?:","options":["La capa granulosa interna es rica en células granulares para la recepción de la mayoría de las aferencias talámicas.","La capa piramidal (ganglionar) interna contiene fibras horizontales y pocas neuronas.","La capa molecular presenta abundantes células piramidales grandes que proyectan a la médula espinal.","La capa polimorfa es la capa más superficial."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-168 / G1226 del banco canónico | integración: Tema 1.4 + Tema 1.6 + Tema 1.7 | referencias indicadas: exame neuro 2025 transcrito juneka.pdf (Pregunta #67/71) / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #53)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-237","number":"237","statement":"Sobre la formación hipocampal y el hipocampo es FALSO que:","options":["Las conexiones eferentes del hipocampo discurren a través del fórnix y terminan en los cuerpos mamilares.","Es fundamental en el establecimiento de nuevas memorias declarativas o explícitas.","Se localiza en el lóbulo temporal y se incluye dentro de la categoría de neocorteza formada por tres capas.","La corteza entorrinal aporta numerosas aferencias al hipocampo."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-169 / G1238 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.8 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #111) / ex. 2 (sin respuestas) (1, 2, 3 y 16).pdf (Pregunta #26)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-238","number":"238","statement":"El Circuito de Papez constituye el sustrato neuroanatómico clásico para la consolidación de la memoria declarativa y la integración emocional. Señale la secuencia lineal exacta del flujo de información que conecta el telencéfalo con el diencéfalo:","options":["Formación Hipocampal → Fórnix (Trígono) → Cuerpos Mamilares del Hipotálamo → Tracto Mamilotalámico → Núcleo Anterior del Tálamo → Giro del Cíngulo.","Amígdala → Estría terminal → Núcleo VPL del tálamo → Corteza motora.","Giro dentado → Cápsula interna → Núcleo rojo → Cerebelo.","Cuerpo calloso → Núcleo caudado → Sustancia negra → Hipocampo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Ruta del Circuito de Papez (Aitana HACK 24 - Cruzamento #4): Aitana lo exige en las tutorías de memoria: Hipocampo envía axones por el Fórnix. El Fórnix termina en los Cuerpos Mamilares (Hipotálamo). De los Cuerpos Mamilares sale el Tracto Mamilotalámico hacia el Núcleo Anterior del Tálamo. El Núcleo Anterior proyecta a la Corteza del Cíngulo.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-170 / G1268 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.8 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #49, #106) / 11-06 Tutoría_ Neurofisiología y Neuroanatomía — Memoria (Papez) / TEMA 7 – FUNCIONES CEREBRALES SUPERIORES.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-239","number":"239","statement":"El mantenimiento del estado de vigilia y el filtro de las señales sensitivas ascendentes durante las fases del sueño dependen de la interacción entre la Formación Reticular Activadora Ascendente (SARA) y el tálamo. ¿Qué núcleo talámico GABAérgico actúa como \"marcapasos\" e inhibidor de las neuronas de relevo durante el sueño NREM?:","options":["El Núcleo Reticular del Tálamo.","El Núcleo Ventral Posterolateral (VPL).","El Núcleo Pulvinar.","El Cuerpo Geniculado Medial."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Compuerta del Sueño (Aitana HACK 24 - Cruzamento #5): El Núcleo Reticular del Tálamo es la única capa que NO envía axones a la corteza; proyecta GABA sobre los otros núcleos talámicos de relevo, hiperpolarizándolos durante el sueño para hiperbloquear la entrada de estímulos somatosensoriales y visuales hacia la corteza.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-171 / G1272 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.8 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #39) / 10-13 Clase_ Funciones Cerebrales, Ritmos Circadianos y Sueño / 10-30 Clase de repaso","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-240","number":"240","statement":"En los circuitos cortico-estriado-talamocorticales, la dopamina moduladora procedente de la Sustancia Negra Pars Compacta (SNc) ejerce efectos opuestos sobre las dos vías de los ganglios basales. Señale la caracterización receptorial y funcional CORRECTA:","options":["Excita la Vía Directa a través de receptores D1 (promoviendo el movimiento al desinhibir el tálamo) e Inhibe la Vía Indirecta a través de receptores D2 (reduciendo la inhibición talamocortical).","Excita la vía indirecta por receptores D1 e inhibe la vía directa por D2.","Destruye el núcleo subtalámico de Luys liberando acetilcolina.","Inhibe la corteza motora primaria directamente sin pasar por el estriado."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack D1 Directa (Excita) vs. D2 Indirecta (Inhibe): Vía Directa (Pro-cinética): Receptor D1 (Excitador) → Apaga el GPi/SNr → Libera/Desinhibe al Tálamo → ¡Inicia el movimiento!.Vía Indirecta (Anti-cinética): Receptor D2 (Inhibidor) → La dopamina la frena, impidiendo que el Núcleo Subtalámico excite al GPi.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-172 / G1277 del banco canónico | integración: Tema 1.6 + Tema 1.9.1 + Tema 1.9.2 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #148, #222) / 10-15 Clase_ Ganglios Basales y Función Motora / TEMA 9 – GANGLIOS BASLES Y MOVIMIENTO.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-241","number":"241","statement":"Un macroadenoma hipofisario no funcional que crece en dirección superior destruye por compresión la estructura diencefálica inmediatamente suprayacente. ¿Qué estructura nerviosa resulta comprimida y qué cuadro neuroendocrino y visual combinado presenta el paciente?:","options":["Compresión del Quiasma Óptico (causando Hemianopsia Bitemporal) junto a alteración del tallo hipofisario / hipotálamo (causando diabetes insípida por falta de ADH o hiperprolactinemia).","Compresión de los cuerpos mamilares produciendo amnesia anterógrada pura.","Compresión del colículo inferior causando sordera monocular.","Compresión de la epífisis con pubertad precoz aislada."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Topográfico Silla Turca / Quiasma / Hipotálamo: La Hipófisis descansa en la silla turca del esfenoides, inmediatamente POR DEBAJO del Quiasma Óptico e Hipotálamo. Todo tumor que crece hacia arriba (extensión supraselar) choca contra el centro del quiasma (decusación de fibras nasales → Hemianopsia Bitemporal) y altera el eje hipotálamo-hipofisario.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-173 / G1279 del banco canónico | integración: Tema 1.6 + Tema 1.11.1 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #133, #225) / 10-06 Clase_ Neuroanatomía del Hipotálamo / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-242","number":"242","statement":"Un quiste o tumor que bloquea el Agujero de Monro (Foramen Interventricular) produce una hidrocefalia no comunicante o obstructiva. ¿Entre qué cavidades ventriculares se sitúa anatómicamente este orificio de paso del LCR?:","options":["Comunica cada Ventrículo Lateral (telencéfalo) con el Tercer Ventrículo (diencéfalo).","Comunica el Tercer Ventrículo con el Cuarto Ventrículo a través del mesencéfalo.","Comunica el Cuarto Ventrículo con el espacio subaracnoideo.","Comunica la cisterna magna con el seno sagital superior."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Ruta del LCR y sus Estrechamientos (Aitana HACK): Ventrículos Laterales → Tercer Ventrículo: Agujero de Monro (Foramen Interventricular). Tercer Ventrículo → Cuarto Ventrículo: Acueducto de Silvio (Mesencéfalo - punto más estrecho y propenso a estenosis). Cuarto Ventrículo → Espacio Subaracnoideo: Orificios de Luschka (laterales) y Magendie (mediano).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-174 / G1283 del banco canónico | integración: Tema 1.3 + Tema 1.6 + Tema 1.7 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #120, #229) / 09-10 Clase_ LCR, circulación cerebral / Tema 1.3 - Cubiertas y vascularización","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-243","number":"243","statement":"Para que la información táctil epicrítica (discriminación entre dos puntos y vibración) procedente de la mano derecha sea percibida conscientemente en la corteza somatosensorial primaria (S1 / Áreas 1, 2, 3 de Brodmann), ¿cuál es la cadena de tres neuronas y los puntos de decusación y relevo talámico exactos?:","options":["1ª neurona en el Ganglio de la Raíz Dorsal (axón asciende por el Fascículo Cuneiforme ipsilateral) → 2ª neurona en el Núcleo Cuneiforme del bulbo (decusa como fibras arqueadas internas formando el Lemnisco Medial) → 3ª neurona en el Núcleo Ventral Posterolateral (VPL) del tálamo → Corteza parietal S1 izquierda.","1ª neurona en la médula que decusa inmediatamente al entrar y llega al cuerpo geniculado medial.","1ª neurona en el hipotálamo lateral que sinapta en la oliva inferior.","1ª neurona en la corteza motora primaria M1."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de las Vías Sensitivas (Grácil/Cuneiforme vs. Espinotalámica): Vía del Cordón Posterior (Tacto Fino / Propiocepción Consciente): Asciende IPSILATERAL por la médula → Decusa en el BULBO (Fibras Arqueadas Internas) → Tálamo VPL → S1.Vía Espinotalámica (Dolor / Temperatura): Decusa INMEDIATAMENTE en la MÉDULA → Asciende CONTRALATERAL por el tronco (Lemnisco Espinal) → Tálamo VPL → S1.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-175 / G1287 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.6 + Tema 1.7 + Tema 1.10 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #111, #203) / 11-06 Tutoría_ Neurofisiología y Neuroanatomía / TEMA 11 – SISTEMA SOMATOSENSORIAL .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-244","number":"244","statement":"Un joven de 21 años sufre una herida penetrante accidental con un florete de esgrima a través de la fosa nasal derecha que alcanza la región dorsomedial del tálamo izquierdo. Tras recuperar la consciencia, mantiene su capacidad intelectual e intelecto intactos, pero presenta una grave incapacidad para consolidar y almacenar nuevos recuerdos autobiográficos (Amnesia Anterógrada severa). ¿Qué estructura diencefálica y qué relación neurobiológica explica este déficit similar al del Síndrome de Korsakoff?:","options":["Lesión de los Núcleos Dorsomediales del Tálamo y de los Cuerpos Mamilares del hipotálamo, que forman parte del circuito límbico diencefálico de consolidación de la memoria explícita/declarativa.","Destrucción aislada del área de Broca en el lóbulo frontal.","Lesión del núcleo caudado con degeneración de la vía dopaminérgica.","Sección del nervio óptico contralateral."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Caso del Florete de Esgrima y Korsakoff (Aitana): Aitana cuenta este caso real de la literatura en clase para demostrar que la memoria no solo está en el hipocampo: la lesión del Tálamo Dorsomedial o de los Cuerpos Mamilares (por el florete o por déficit de tiamina/vitamina B1 en el alcoholismo del Korsakoff) interrumpe la red diencéfalo-hipocámpica y causa Amnesia Anterógrada grave con preservación de la memoria procedimental.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-176 / G1288 del banco canónico | integración: Tema 1.6 + Tema 1.8 | referencias indicadas: 10-09 Clase_ Funciones Cerebrales y Memoria / Nervioso T21-T22-20251009_142954 / TEMA 7 – FUNCIONES CEREBRALES SUPERIORES.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-245","number":"245","statement":"Durante la quinta semana de gestación, las tres vesículas encefálicas primarias se subdividen en cinco vesículas secundarias. Indique la derivación madura de la vesícula del Diencéfalo y de la vesícula del Metencéfalo junto con sus cavidades ventriculares maduras:","options":["El Diencéfalo origina el Tálamo, Hipotálamo y Epitálamo (cavidad: Tercer Ventrículo); mientras que el Metencéfalo origina la Protuberancia y el Cerebelo (cavidad: porción superior del Cuarto Ventrículo).","El diencéfalo origina la corteza cerebral y los ventrículos laterales.","El metencéfalo origina la médula espinal y el conducto ependimario.","El telencéfalo origina el acueducto de Silvio y el bulbo raquídeo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de las 5 Vesículas Encefálicas (Secuencia Madura): Telencéfalo: Corteza / Ganglios basales (Ventrículos Laterales). Diencéfalo: Tálamo / Hipotálamo / Epitálamo (Tercer Ventrículo). Mesencéfalo: Pedúnculos / Tectum (Acueducto de Silvio). Metencéfalo: Ponte / Cerebelo (Cuarto Ventrículo parte alta). Mielencéfalo: Bulbo Raquídeo (Cuarto Ventrículo parte baja).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-177 / G1291 del banco canónico | integración: Tema 1.2 + Tema 1.5.1 + Tema 1.6 + Tema 1.9.3 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #2, #214) / 10-29 Clase_ Desarrollo Embrionario / TEMA 16 – EMBRIOLOGÍA.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-246","number":"246","statement":"La información visual conducida por el nervio óptico se segrega en dos canales paralelos de procesamiento hacia el Núcleo Geniculado Lateral (NGL) del tálamo. ¿Qué combinación de células ganglionares, capas del NGL y función perceptiva caracteriza a la Vía Magnocelular frente a la Parvocelular?:","options":["La vía Magnocelular (células ganglionares M de bastones) proyecta a las capas 1 y 2 del NGL (procesa movimiento y contraste); mientras que la vía Parvocelular (células ganglionares P de conos) proyecta a las capas 3, 4, 5 y 6 del NGL (procesa alta resolución de forma y color).","La vía M proyecta a las capas 3-6 para ver el color rojo exclusivamente.","Las capas 1 y 2 reciben fibras parvocelulares de la foveola central.","Ambas vías sinaptan en el cuerpo geniculado medial junto a la audición."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de las Capas del NGL (Magno 1-2 vs Parvo 3-6): MAGNOCELULAR (Capas 1 y 2): Células M → Bastones → Movimiento, rapidez y baja resolución (Visión de \"Dónde\"). PARVOCELULAR (Capas 3, 4, 5 y 6): Células P → Conos → Alta agudeza, forma detallada y color (Visión de \"Qué\").","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-178 / G1292 del banco canónico | integración: Tema 1.6 + Tema 1.11.1 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #120, #226) / 10-24 Clase magistral_ Organización funcional de la retina / TEMA 12 – VISIÓN.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-247","number":"247","statement":"La vía auditiva ascendente realiza la localización espacial del sonido y el procesamiento tonotópico a lo largo del tronco del encéfalo. ¿Qué núcleo de la protuberancia analiza la diferencia de tiempo interaural (ITD) y qué estructura mesencefálica y talámica reciben sus proyecciones?:","options":["El Núcleo Olivar Superior Medial (OSM) analiza las diferencias de tiempo interaural; proyecta por el Lemnisco Lateral hacia el Colículo Inferior (mesencéfalo) y de allí al Núcleo Geniculado Medial (tálamo).","El núcleo grácil analiza la intensidad y proyecta al colículo superior y geniculado lateral.","Las pirámides bulbares envían axones directos al área de Broca.","El núcleo de Edinger-Westphal conduce la vía tonotópica hacia el cerebelo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Auditivo E-CO-LI-MA (Oliva Superior + Colículo Inf + Geniculado Medial): Oliva Superior Medial (Protuberancia): Diferencia de tiempo entre ambos oídos (ITD / localización horizontal). Asciende por el Lemnisco Lateral. Sinapta en el Colículo Inferior (Mesencéfalo). Pasa al Núcleo Geniculado MEDIAL del Tálamo (Medial = Música / Audición) → Corteza A1 (Heschl).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-179 / G1294 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.11.2 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #123, #229) / 09-24 Clase_ Neuroanatomía - Vías Sensitivas y Auditivas / TEMA 13 – SENTIDO DE LA AUDICIÓN.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-248","number":"248","statement":"Analice las siguientes proposiciones integradoras de la neurobiología del sistema nervioso central extraídas del compendio oficial. Indique la ÚNICA combinación donde TODAS las proposiciones sean VERDADERAS:Las neuronas preganglionares autonómicas nacen del tubo neural, mientras que las postganglionares y sensitivas viscerales derivan de la cresta neural. El circuito de Papez conecta secuencialmente el Hipocampo → Fórnix → Cuerpos Mamilares → Tracto Mamilotalámico → Núcleo Anterior del Tálamo → Giro del Cíngulo. La parálisis facial central por lesión corticonuclear afecta únicamente al cuadrante inferior de la cara contralateral, respetando la frente y el ojo debido a la inervación bilateral de la porción superior del núcleo del VII par.","options":["1, 2 y 3 son VERDADERAS.","Solo 1 y 2 son verdaderas.","Solo 2 y 3 son verdaderas.","1, 2 y 3 son falsas."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Gran Resumen de Integração Transversal: Proposición 1 (VERDADERA): Tubo Neural = Preganglionar / Cresta Neural = Postganglionar y Sensitivas Viscerales. Proposición 2 (VERDADERA): Ruta del Circuito de Papez (Memoria). Proposición 3 (VERDADERA): Parálisis Facial Central (Boca sola) vs. Periférica (Cara entera ipsilateral).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-180 / G1297 del banco canónico | integración: Tema 1.2 + Tema 1.5.1 + Tema 1.5.2 + Tema 1.6 + Tema 1.7 + Tema 1.8 + Tema 1.9.1 + Tema 1.12 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (HACK 24 - Preguntas de Integración #4, #14, #39, #40, #49, #106, #205, #241, #274)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-249","number":"249","statement":"Respecto al origen embriológico y destino histológico de la Copa Óptica, señale la afirmación CORRECTA:","options":["La copa óptica es una evaginación del neuroectodermo del diencéfalo que dará lugar a la retina neural y al epitelio pigmentario del ojo.","Procede de la capa ependimaria del telencéfalo.","Tiene el mismo origen embriológico mesodérmico que la coroides y la esclera del ojo.","Se origina directamente de las placodas ectodérmicas del rombencéfalo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Copa Óptica Diencefálica (Aitana HACK): Copa Óptica (Diencéfalo): Evaginación neuroectodérmica que origina la Retina Neural y el Epitelio Pigmentario. Por ello, el nervio óptico (II par) no es un nervio periférico verdadero, sino un tracto del SNC rodeado de meninges. Ectodermo Superficial: Origina la placoda del cristalino. Mesodermo/Cresta Neural: Origina la coroides y esclera. La banca engaña diciendo que la copa óptica procede del telencéfalo o que tiene el mismo origen que la coroides.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-181 / G1308 del banco canónico | integración: Tema 1.2 + Tema 1.6 + Tema 1.11.1 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #2) / perguntas neuro julio exame.docx (Pregunta #65) / Tema 1.2 - Embriología del SN 25-26.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-250","number":"250","statement":"Durante el desarrollo del Prosencéfalo (cerebro anterior), la organización de las placas alares y basales muestra una modificación drástica en comparación con la médula espinal. Señale la afirmación CORRECTA:","options":["El prosencéfalo está constituido casi exclusivamente por la expansión masiva de las Placas Alares, mientras que las Placas Basales se encuentran en plena regresión/ausencia.","El prosencéfalo está formado únicamente por placas basales motoras.","Las placas alares prosencefálicas originan las motoneuronas de los pares craneales IX y X.","El surco limitante divide al telencéfalo en dos hemisferios idénticos a la médula."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Prosencéfalo = Placa Alar Pura (Aitana HACK): Médula, Bulbo, Puente y Mesencéfalo: Tienen Placa Alar (Dorsal/Sensitiva) y Placa Basal (Ventral/Motora). Prosencéfalo (Telencéfalo + Diencéfalo): El crecimiento masivo de las placas alares laterales \"empuja\" y hace desaparecer la placa basal. ¡El hemisferio cerebral es 100% Placa Alar!","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-182 / G1312 del banco canónico | integración: Tema 1.2 + Tema 1.6 + Tema 1.7 | referencias indicadas: Tema 1.2 - Embriología del SN 25-26.pdf / TEMA 16 – EMBRIOLOGÍA.pdf / 10-30 Clase magistral","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-251","number":"251","statement":"En el desarrollo embrionario del Diencéfalo a partir de las paredes laterales del tercer ventrículo, ¿qué estructura se origina a partir de las neuronas de la región ventral de la placa alar diencefálica?:","options":["El Hipotálamo.","El Telencéfalo basal.","La Oliva Inferior.","El Cerebelo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Origen Diencefálico (Tálamo vs. Hipotálamo): Dentro de la placa alar diencefálica: Región DORSAL de la placa alar diencefálica: Origina el Tálamo y el Epitálamo (epífisis/habénula). Región VENTRAL de la placa alar diencefálica: Origina el Hipotálamo. Pregunta literal de examen.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-183 / G1313 del banco canónico | integración: Tema 1.2 + Tema 1.6 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #115) / Tema 1.2 - Embriología del SN 25-26.pdf / TEMA 16 – EMBRIOLOGÍA.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-252","number":"252","statement":"Respecto a las comunicaciones internas del sistema ventricular cerebrales, señale la relación anatómica INCORRECTA:","options":["El acueducto mesencefálico (de Silvio) se extiende a lo largo de la mitad inferior del bulbo raquídeo.","Los agujeros interventriculares (de Monro) comunican los ventrículos laterales con el tercer ventrículo.","El acueducto cerebral comunica el tercer ventrículo con el cuarto ventrículo a través del mesencéfalo.","Los orificios laterales (de Luschka) y el orificio medial (de Magendie) comunican el cuarto ventrículo con el espacio subaracnoideo/cisterna magna."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Topográfico del Acueducto de Silvio: El Acueducto de Silvio / Mesencefálico atraviesa estrictamente el MESENCÉFALO (entre el tegmento y el tectum). ¡NUNCA llega al bulbo raquídeo! El bulbo raquídeo contiene la mitad inferior del cuarto ventrículo y el canal ependimario.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-184 / G1334 del banco canónico | integración: Tema 1.3 + Tema 1.5.1 + Tema 1.6 + Tema 1.7 | referencias indicadas: 09-11 Clase_ LCR y Vascularización Cerebral / ex. 2021 (respuestas).pdf (Pregunta #4) / perguntas neuro julio / Recopilación preguntas neuro (1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-253","number":"253","statement":"Los Órganos Circunventriculares son regiones cerebrales especializadas situadas alrededor de los ventrículos III y IV. ¿Qué característica histológica diferenciadora presentan respecto a la Barrera Hematoencefálica (BHE) y cuál es su sentido fisiológico?:","options":["Carecen de BHE eficaz (poseen endotelio capilar fenestrado), lo que permite a sus neuronas sensar directamente cambios hormonales, osmolares o toxinas en la sangre sistémica.","Presentan una BHE hiperforzada e impenetrable para el agua.","Son las únicas estructuras que producen LCR dentro del espacio epidural.","Están aislados por completo del torrente sanguíneo mediante astrocitos de Schwann."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de los Órganos Circunventriculares (Aitana HACK): Aitana enfatiza en la grabación: \"Son las excepciones fisiológicas a la regla de la BHE\". Incluyen el Área Postrema (centro emético del vómito), la Eminencia Media, el Órgano Vasculoso de la Lámina Terminal (OVLT) y la Neurohipófisis. Poseen capilares fenestrados sin BHE para quimiorrecepción rápida.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-185 / G1352 del banco canónico | integración: Tema 1.3 + Tema 1.5.1 + Tema 1.6 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #263) / Nervioso T21-T22-20251006_163846 / Recopilación preguntas neuro (1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-254","number":"254","statement":"El Tercer Ventrículo es una cavidad estrecha e impar situada en la línea media del diencéfalo. Presenta varios recesos u evaginaciones de su pared. ¿Cuál de las siguientes estructuras NO constituye una relación anatómica o receso del tercer ventrículo?:","options":["El Área Postrema (que es un receso del suelo del cuarto ventrículo en el bulbo).","El Receso Supraóptico (por encima del quiasma óptico).","El Receso Infundibular (hacia el tallo de la hipófisis).","La Adherencia Intertalámica (que atraviesa la cavidad del tercer ventrículo)."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Relaciones del III vs. IV Ventrículo:3er Ventrículo (Diencéfalo): Adherencia intertalámica, lámina terminal, receso óptico, receso infundibular, receso pineal y suprapineal.4º Ventrículo (Protuberancia y Bulbo): Área postrema, trígono del hipogloso, trígono del vago y fosa romboidea. Pregunta literal de examen.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-186 / G1360 del banco canónico | integración: Tema 1.3 + Tema 1.5.1 + Tema 1.6 | referencias indicadas: 09-11 Clase_ LCR y Vascularización Cerebral / ex. 2021 (respuestas).pdf (Pregunta #4) / Recopilación preguntas neuro (1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-255","number":"255","statement":"La Hidrocefalia es la acumulación excesiva de LCR en el sistema ventricular e intracraneal. Señale la diferencia entre la Hidrocefalia No Comunicante (Obstructiva) y la Hidrocefalia Comunicante:","options":["La Hidrocefalia No Comunicante ocurre por un bloqueo en el flujo de LCR dentro del sistema ventricular (ej. estenosis del acueducto de Silvio o masa en Monro); mientras que la Hidrocefalia Comunicante ocurre por un fallo en la reabsorción del LCR en las granulaciones aracnoideas del espacio subaracnoideo.","La hidrocefalia comunicante es causada por la parálisis de las motoneuronas alfa.","La hidrocefalia no comunicante ocurre exclusivamente en el espacio epidural.","Ambos tipos cursan con desaparición total de los plexos coroideos."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Hidrocefalia Obstructiva vs. Comunicante: NO COMUNICANTE (Obstructiva): Bloqueo DENTRO de las cavidades ventriculares (Monro, Acueducto de Silvio, Luschka/Magendie) → El LCR no llega al espacio subaracnoideo. COMUNICANTE: El LCR fluye libremente fuera de los ventrículos, pero las Vellosidades Aracnoideas de Pacchioni están inflamadas/bloqueadas (ej. tras meningitis o hemorragia subaracnoidea) y no lo reabsorben.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-187 / G1363 del banco canónico | integración: Tema 1.3 + Tema 1.5.1 + Tema 1.6 + Tema 1.7 | referencias indicadas: 09-11 Clase_ LCR y Vascularización Cerebral / ex. 2021 (respuestas).pdf (Pregunta #4) / wuolah-free-Examen-Neuro-recu-junio-2023 orc.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-256","number":"256","statement":"Sobre la estructura histológica y la fisiología de la Barrera Hematoencefálica (BHE), señale la afirmación FALSA:","options":["Los denominados órganos circunventriculares son regiones del encéfalo donde la barrera hematoencefálica es especialmente impermeable y reforzada.","Está formada fundamentalmente por uniones estrechas (zonula occludens) entre las células que componen el endotelio vascular capilar.","La permeabilidad pasiva de moléculas a través de la BHE está directamente relacionada con su liposolubilidad.","Los astrocitos (a través de sus pies perivasculares) participan activamente en la inducción y mantenimiento de las uniones estrechas endoteliales."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Inversión de Permeabilidad en Órganos Circunventriculares: Aitana lo repite en varias clases: Los Órganos Circunventriculares (Área Postrema, Eminencia Media, OVLT, Neurohipófisis) son zonas donde la BHE NO EXISTE O ES PERMEABLE / FENESTRADA (para permitir la entrada de hormonas o sensar toxinas). La banca escribe \"donde la BHE es especialmente impermeable\" para invertir el concepto.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-188 / G1368 del banco canónico | integración: Tema 1.3 + Tema 1.5.1 + Tema 1.6 | pregunta original 39 de la carga nueva | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #263) / ex. 2021 (respuestas).pdf (Pregunta #7) / 09-15 Clase_ Senos Venosos, BHE","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-257","number":"257","statement":"Respecto a las cisternas subaracnoideas del encéfalo, ¿cuál de ellas se localiza dorsalmente al techo del mesencéfalo (tectum), rodeando a la glándula pineal y conteniendo en su interior a la vena cerebral magna (de Galeno) y los colículos superiores e inferiores?:","options":["Cisterna Cuadrigémina (o Cisterna de la Vena Cerebral Magna).","Cisterna magna cerebelomedular.","Cisterna prepontina.","Cisterna de la fosa lateral de Silvio."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Cisterna Cuadrigémina vs. Cisterna Magna: Cisterna Cuadrigémina (Ambiente/Superior): Dorsal al mesencéfalo (sobre los 4 colículos o lámina cuadrigémina), contiene la Glándula Pineal y la Vena de Galeno. Cisterna Magna: Dorsal al bulbo y debajo del cerebelo.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-189 / G1386 del banco canónico | integración: Tema 1.3 + Tema 1.5.1 + Tema 1.6 | pregunta original 57 de la carga nueva | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #221) / 09-10 Clase_ LCR, circulación cerebral / ex. 2 (respuestas).pdf (Pregunta #4)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-258","number":"258","statement":"El Diafragma de la Silla Turca (diafragma sellar) es una pequeña lámina horizontal de duramadre que forma el techo de la fosa hipofisaria. ¿Qué orificio presenta en su centro y qué estructura lo atraviesa?:","options":["Presenta un orificio central para el paso del Tallo Hipofisario (Infundíbulo) que conecta el hipotálamo con la hipófisis.","Presenta el agujero de Monro para el paso del LCR.","Presenta la hendidura esfenoidal para el paso del nervio óptico.","Está completamente cerrado sin permitir el paso de ninguna estructura."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Diafragma Sellar e Infundíbulo: El Diafragma Sellar aísla la glándula hipófisis (dentro de la silla turca) del espacio subaracnoideo supraselar, dejando perforado únicamente su centro para el paso del Tallo Pituitario / Infundíbulo.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-190 / G1390 del banco canónico | integración: Tema 1.3 + Tema 1.6 | pregunta original 61 de la carga nueva | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #88) / 09-09 Clase_ Prolongaciones de la Duramadre / TEMA 1 – CUBIERTAS Y VASCULARIZACIÓN.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-259","number":"259","statement":"Señale la secuencia lineal exacta del flujo de LCR desde su síntesis principal hasta su reabsorción venosa sistémica:","options":["Ventrículos Laterales → Agujeros de Monro → Tercer Ventrículo → Acueducto de Silvio → Cuarto Ventrículo → Agujeros de Luschka y Magendie → Espacio Subaracnoideo / Cisternas → Granulaciones Aracnoideas de Pacchioni → Seno Sagital Superior.","Seno sagital superior → Cuarto ventrículo → Plexo coroideo → Duramadre.","Granulaciones de Pacchioni → Acueducto de Silvio → Vena de Galeno.","Canal ependimario → Arteria basilar → Seno cavernoso."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Ruta Mestra del LCR (Aitana HACK): Aitana exige esta secuencia perfecta en las preguntas de ordenar: Plexos Coroideos (Ventrículos Laterales). Foramen de Monro → 3er Ventrículo. Acueducto de Silvio (Mesencéfalo) → 4º Ventrículo. Luschka (Laterales) y Magendie (Mediano) → Espacio Subaracnoideo / Cisternas. Granulaciones de Pacchioni → Seno Sagital Superior.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-191 / G1403 del banco canónico | integración: Tema 1.3 + Tema 1.5.1 + Tema 1.6 + Tema 1.7 | pregunta original 74 de la carga nueva | referencias indicadas: 09-11 Clase_ LCR y Vascularización Cerebral / Tema 1.3 / ex. 2021 (respuestas).pdf (Pregunta #4)\n\nCONTROL DE INTEGRIDAD\n- Tema: TEMA 1.6 - DIENCÉFALO\n- Preguntas tipo test recibidas en el dossier: 259 | entregadas: 259\n- Casos clínicos con alternativas (detección aproximada por palabras clave del enunciado): 9 (cada uno ya es una entrada independiente con el caso completo); subpreguntas adicionales: 0; casos abiertos: 0\n- Preguntas sin clave explícita (Respuesta correcta: NO INDICADA): ninguna\n- Preguntas con claves contradictorias o múltiples (REVISAR): ninguna\n- Preguntas cuyo enunciado no figura en el material de origen (alternativas conservadas, enunciado marcado): ninguna\n- Fragmentos ilegibles o incompletos: ninguno detectado salvo los enunciados ausentes indicados arriba.\n- Se conservaron todas las preguntas, alternativas, claves y justificaciones. Se eliminaron únicamente marcadores de referencia de NotebookLM ([12i], [3], \"generated by NotebookLM to PDF\"), números de nota al pie, pies de página y restos de conversación/índices ajenos a cada pregunta.\n- Siguiente pregunta pendiente: ninguna (entrega completa de este tema).","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-1","number":"1","statement":"Se denomina giros a:","options":["las hendiduras profundas en la corteza cerebral.","las hendiduras poco profundas en la corteza cerebral.","los pliegues de la corteza cerebral.","los pliegues de la sustancia blanca cerebral.","ninguna de las anteriores."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-001 / G0421 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-6-preguntas.pdf (Pergunta 24) / wuolah-free-examen- 3.pdf (Pergunta 23)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-2","number":"2","statement":"Las células horizontales de Cajal se encuentran principalmente en:","options":["Capa VI","Capa IV","Capa V","Capa I"],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-002 / G0423 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: ex. 2021 (respuestas).pdf (Pergunta 30) / wuolah-free-EXAMEN-NEURO- 2-SIN-RESPUESTAS.pdf (Pergunta 69) / wuolah-free-EXAMEN-2017-2018-1 (1).pdf (Pergunta 69)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-3","number":"3","statement":"¿Cuál de las siguientes capas de la corteza cerebral recibe la mayor cantidad de proyecciones aferentes?","options":["Capa granulosa interna","Capa piramidal interna","Capa plexiforme","Capa granulosa externa"],"answer":0,"explanation":"Justificación y análisis de las alternativas: || A) Capa granulosa interna – CORRECTA: Capa IV: está hipertrofiada en las cortezas sensoriales primarias y está formada por abundantes células granulares (estrelladas). Funciona como la principal puerta de entrada y estación receptora de las aferencias sensitivas que provienen del tálamo (fibras talamocorticales) y de otras regiones subcorticales. || B) Capa piramidal interna – INCORRECTA: Capa V: es la principal capa eferente (de salida) del neocórtex, no de recepción. En ella se encuentran las grandes neuronas piramidales (como las células de Betz en el área 4), cuyos axones forman las fibras de proyección hacia la médula espinal y el tronco encefálico. || C) Capa plexiforme – INCORRECTA: Capa I (molecular): es la capa más superficial del neocórtex. Contiene principalmente prolongaciones dendríticas, axones horizontales e interneuronas (como las células horizontales de Cajal), pero no recibe el grueso de las aferencias talamocorticales. || D) Capa granulosa externa – INCORRECTA: Capa II: aunque contiene células granulares y algunas piramidales pequeñas, participa sobre todo en circuitos y conexiones asociativas corticocorticales locales; no es el destino principal de las aferencias masivas del tálamo.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-003 / G0424 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: ex. 2021 (respuestas).pdf (Pergunta 31) / wuolah-free-EXAMEN-NEURO- 2-SIN-RESPUESTAS.pdf (Pergunta 70) / wuolah-free-EXAMEN-2017-2018-1 (1).pdf (Pergunta 70)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-4","number":"4","statement":"Señala la afirmación INCORRECTA sobre la sustancia blanca del cerebro:","options":["El fascículo longitudinal superior conecta áreas frontales y parietales dentro del mismo hemisferio.","El cuerpo calloso es una fibra de asociación cortical.","La cápsula interna contiene fibras que proyectan desde la corteza cerebral hacia estructuras subcorticales.","El fascículo uncinado conecta áreas frontales y temporales del mismo hemisferio cerebral."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-004 / G0425 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: Examem 2025 outro modelo juneka.pdf / exame neuro 2025 transcrito juneka.pdf (Pergunta 70)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-5","number":"5","statement":"Señala la afirmación CORRECTA sobre el surco central:","options":["el surco central es observable en la superficie medial del hemisferio cerebral","el lóbulo frontal se encuentra posterior a dicho surco central","el lóbulo parietal se encuentra anterior a dicho surco central","el surco central continúa en su zona inferior con el surco lateral"],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-005 / G0430 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: ex. 2 (respuestas).pdf / ex. 2 (sin respuestas) (1, 2, 3 y 16).pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-6","number":"6","statement":"Sobre la fisura cerebral longitudinal, ¿cuál de las siguientes afirmaciones es CORRECTA?","options":["la fisura contiene arterias cerebrales medias","el seno sagital superior se encuentra por debajo de ella","el cuerpo calloso cruza la línea media en la zona profunda de la fisura","el seno sagital inferior se halla por encima de ella"],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-006 / G0431 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: ex. 2 (respuestas).pdf / ex. 2 (sin respuestas) (1, 2, 3 y 16).pdf / examenes neuro compl (1).pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-7","number":"7","statement":"¿Cuál de los siguientes fascículos de asociación NO se relaciona con el lóbulo frontal?","options":["Fascículo longitudinal superior","Fascículo arqueado","Fascículo uncinado","Todos los anteriores se relacionan con el lóbulo frontal"],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-007 / G0435 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: Recopilación preguntas neuro (1).pdf / perguntas neuro julio exame.docx","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-8","number":"8","statement":"Las divisiones principales del telencéfalo son:","options":["La cisura de Silvio que separa el lóbulo parietal del temporal","El surco lateral y el parietooccipital que separan el lóbulo temporal del occipital","El surco central y el surco lateral que separan el lóbulo frontal y el temporal","El surco central y el surco lateral que separan el lóbulo frontal de los lóbulos temporal y parietal.","El surco central separa el lóbulo temporal del occipital"],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-008 / G0437 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-PREGUNTAS-EXAMEN-DE-NEURO.pdf (Pergunta 6) / wuolah-free-PREGUNTAS-EXAMEN-DE-NEURO (1).pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-9","number":"9","statement":"Las células de Martinotti de la corteza cerebral son:","options":["células muy pequeñas localizadas en la capa I con ramificaciones muy pequeñas que no abandonan la capa.","células muy pequeñas localizadas en la capa IV con ramificaciones muy pequeñas que no abandonan la capa.","interneuronas.","neuronas de asociación.","neuronas de proyección."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-009 / G0439 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-6-preguntas.pdf (Pergunta 6) / wuolah-free-examen- 3.pdf (Pergunta 22)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-10","number":"10","statement":"El cerebro:","options":["Presenta circunvoluciones, como la cingular, que es visible en un plano mediosagital.","Tiene diferentes surcos, como el central, que separa el lóbulo temporal del fronto-parietal.","Tiene una región ubicada en el lóbulo occipital que se llama uncus.","Presenta una región en el lóbulo parietal que se llama ínsula."],"answer":0,"explanation":"Justificación y análisis de las alternativas: || A) Presenta circunvoluciones, como la cingular, que es visible en un plano mediosagital – CORRECTA: La circunvolución del cíngulo (giro cingular) recorre la cara medial del hemisferio cerebral, inmediatamente por encima del cuerpo calloso. Por ello es una estructura claramente visible en cualquier corte mediosagital. || B) Tiene diferentes surcos, como el central, que separa el lóbulo temporal del fronto-parietal – INCORRECTA: El surco central (de Rolando) separa el lóbulo frontal del lóbulo parietal (el giro precentral del postcentral). El surco que separa el lóbulo temporal de los lóbulos frontal y parietal es el surco lateral (fisura de Silvio). || C) Tiene una región ubicada en el lóbulo occipital que se llama uncus – INCORRECTA: El uncus (gancho) es el extremo anterior de la circunvolución parahipocámpica y se localiza en la cara medial e inferior del lóbulo temporal (sistema límbico), no en el lóbulo occipital. || D) Presenta una región en el lóbulo parietal que se llama ínsula – INCORRECTA: La ínsula se considera un lóbulo en sí mismo, situado en la profundidad de la fisura lateral (de Silvio) y oculto por los opérculos frontal, parietal y temporal. No forma parte de la superficie del lóbulo parietal.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-010 / G0440 del banco canónico | archivos: Neuro_Parte2.pdf; NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: perguntas neuro julio exame.docx (Pergunta #27) / Simulado_Tema_1_7_FINAL_108.pdf · Pregunta 004 · Fuente original: NEURO_275_ORGANIZADO_POR_TEMA_HACK24_Exames_2025.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-11","number":"11","statement":"La neocorteza cerebral se caracteriza por:","options":["ser igual en toda su extensión.","por tener siempre cinco capas, siendo la I la más externa (en contacto con la piamadre)","por tener siempre cinco capas, siendo la I la más interna (en contacto con la sustancia blanca).","por tener siempre seis capas, siendo la VI la más interna (en contacto con la sustancia blanca).","ninguna de las anteriores es cierta."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-011 / G0441 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-6-preguntas.pdf (Pergunta 5)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-12","number":"12","statement":"El área de integración común (5, 7, 39, 40) se encuentra en el:","options":["Lóbulo frontal","Lóbulo occipital","Lóbulo temporal","Lóbulo parietal"],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-012 / G0443 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: Recopilación preguntas neuro (1).pdf / perguntas neuro julio exame.docx","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-13","number":"13","statement":"Señale la afirmación CORRECTA respecto a las relaciones anatómicas del núcleo lenticular:","options":["Ocupa una posición medial con respecto al brazo posterior de la cápsula interna.","El núcleo lenticular es medial con respecto a la cápsula externa.","El segmento externo del globo pálido es medial con respecto al segmento interno.","La cola del caudado se localiza lateral al putamen."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-013 / G0444 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: perguntas neuro julio exame.docx (Pregunta #88) / Tema 1.7 - Telencéfalo 25-26 (2).pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-14","number":"14","statement":"El cuerpo calloso:","options":["Está compuesto por fibras nerviosas que conectan la corteza cerebral con el tálamo.","Facilita la comunicación entre los hemisferios cerebrales y está compuesto principalmente por axones mielinizados.","Se encuentra en el lóbulo temporal y participa en la integración de la información auditiva.","Es una estructura de sustancia gris que rodea los ventrículos laterales."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-014 / G0447 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: perguntas neuro julio exame.docx / Recopilación preguntas neuro (1).pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-15","number":"15","statement":"Señala la respuesta CORRECTA sobre la corteza cerebral:","options":["La fisura calcarina se encuentra en la ínsula.","Las neuronas piramidales de mayor tamaño se encuentran en la capa granulosa interna de la neocorteza.","La corteza entorrinal proporciona una vía importante de entrada de información hacia la formación hipocampal.","El área sensitiva primaria se ubica en el giro precentral del lóbulo frontal."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-015 / G0449 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: perguntas neuro julio exame.docx / Tema 1.7 - Telencéfalo 25-26 (2).pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-16","number":"16","statement":"La neocorteza cerebral se caracteriza por:","options":["ser igual en toda su extensión.","por tener siempre cinco capas, siendo la I la más externa (en contacto con la piamadre).","por tener siempre cinco capas, siendo la I la más interna (en contacto con la sustancia blanca).","por tener siempre seis capas, siendo la VI la más interna (en contacto con la sustancia blanca).","ninguna de las anteriores es cierta."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-016 / G0452 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-6-preguntas.pdf / TEMA 6 – TELENCÉFALO.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-17","number":"17","statement":"El área visual primaria se corresponde con el área de Brodmann:","options":["17","18","19","41","42"],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-017 / G0455 del banco canónico | número original en el examen: 8 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-6-preguntas.pdf (Pergunta 8) / wuolah-free-examen- 3.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-18","number":"18","statement":"Las fibras asociativas del telencéfalo:","options":["Conectan zonas correspondientes de los dos hemisferios cerebrales.","Conectan la corteza cerebral con los núcleos subcorticales del tronco.","Conectan diferentes zonas de la corteza cerebral dentro del mismo hemisferio.","Pertenecen exclusivamente al cuerpo calloso.","Ninguna de las anteriores es correcta."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-018 / G0456 del banco canónico | número original en el examen: 11 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-6-preguntas.pdf (Pergunta 11) / wuolah-free- PREGUNTAS-EXAMEN-DE-NEURO.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-19","number":"19","statement":"Las células de Martinotti de la corteza cerebral son:","options":["Células muy pequeñas localizadas en la capa 1 con ramificaciones muy pequeñas que no abandonan la capa.","Células muy pequeñas localizadas en la capa 4 con ramificaciones muy pequeñas que no abandonan la capa.","Interneuronas.","Neuronas de asociación.","Neuronas de proyección."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-019 / G0460 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-6-preguntas.pdf (Pergunta 22) / wuolah-free-examen- 3.pdf (Pergunta 22)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-20","number":"20","statement":"¿Cuál de las siguientes estructuras NO es visible en la cara convexa de los hemisferios cerebrales?:","options":["Giro precentral.","Giro postcentral.","Giro cingular.","Giro frontal superior."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-020 / G0462 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: Recopilación preguntas neuro (1).pdf / perguntas neuro julio exame.docx","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-21","number":"21","statement":"Un paciente llega tras un accidente cerebrovascular y presenta incapacidad para reconocer objetos al tacto con la mano derecha, aunque puede percibir presión, temperatura y dolor. ¿Cuál es el área cortical que estará afectada con mayor probabilidad?:","options":["El área de asociación somatosensorial.","El área somatosensitiva primaria.","El área motora primaria.","El área visual primaria."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-021 / G0463 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: Exame Neuroanatomia 2025 Meu (1).pdf / exame neuro 2025 transcrito juneka.pdf (Pergunta 68)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-22","number":"22","statement":"Sobre la formación hipocampal es CIERTO que:","options":["Las aferencias extrahipocampales llegan principalmente a la corteza entorrinal a través del álveo (alveus).","La fimbria del hipocampo está formada por axones de células granulares del giro dentado que proyectan hacia CA3.","Las colaterales de Schaffer son axones de las células piramidales de CA3 que sinaptan con CA1.","La capa molecular del giro dentado contiene principalmente células piramidales responsables de la salida eferente."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-022 / G0464 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: Exame Neuroanatomia 2025 Meu (1).pdf / exame neuro 2025 transcrito juneka.pdf (Pergunta 69)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-23","number":"23","statement":"El córtex motor primario:","options":["Se localiza en la circunvolución postcentral del lóbulo parietal.","Presenta la capa IV (granulosa interna) muy desarrollada para recibir aferencias auditivas.","Tiene una gran concentración de neuronas piramidales gigantes (de Betz) especialmente en la capa V.","Se encuentra en el mismo lóbulo cerebral que las áreas 17 y 22 de Brodmann."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-023 / G0475 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-Examen-Neuro-recu-junio-2023 orc.pdf (Pergunta 30) / Tema 1.9.1 - Corteza motora y vías motoras descendentes 25-26.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-24","number":"24","statement":"Selecciones la relación INCORRECTA sobre el sistema límbico:","options":["Aumento de serotonina — disminución de la agresividad.","Amígdala cerebral — su pérdida se traduce en un incremento de la percepción del miedo.","Circunvolución cingulada — su corteza es la única implicada en el inicio del procesamiento emocional.","Fórnix — forma parte del Circuito de Papez y es importante, por ejemplo, en la formación de un recuerdo emocional."],"answer":1,"explanation":"[Nota de la clave] A perda ou lesão da amígdala reduz/elimina a percepção do medo, e não a incrementa).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-024 / G0476 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: Recopilación preguntas neuro (1).pdf / perguntas neuro julio exame.docx (Pergunta #31)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-25","number":"25","statement":"Sobre la sustancia blanca cerebral es CIERTO que:","options":["El cuerpo calloso es el mayor tracto de asociación, que comunica distintos lóbulos dentro del mismo hemisferio cerebral.","El fascículo uncinado conecta de forma contralateral la corteza frontal con la corteza temporal.","Las fibras comisurales comunican regiones homólogas de ambos hemisferios cerebrales.","La cápsula interna está formada principalmente por fibras de asociación de corto recorrido."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-025 / G0477 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: perguntas neuro julio exame.docx (Pergunta #37) / Recopilación preguntas neuro (1).pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-26","number":"26","statement":"Respecto a las áreas de asociación prefrontales de la corteza cerebral, señale la afirmación CORRECTA:","options":["El área dorsolateral no se relaciona con la memoria de trabajo.","La corteza prefrontal no recibe aferencias del tálamo.","La corteza orbitofrontal está íntimamente relacionada con el procesamiento de emociones y el control de impulsos (valor hedonista).","Las lesiones en la corteza prefrontal aumentan la capacidad de planificación a largo plazo."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-026 / G0480 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-Examen-Neuro-recu-junio-2023 orc.pdf (Pergunta 38) / Tema 1.8 - Funciones cerebrales superiores 25-26 (1).pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-27","number":"27","statement":"Respecto a las asimetrías hemisféricas y dominancia cerebral, señale la afirmación CORRECTA:","options":["En relación a la audición, en la mayoría de los individuos el reconocimiento de los sonidos no lingüísticos (música) presenta predominancia izquierda.","La expresión de N-cadherinas (guiado axonal) suele ser más abundante en el hemisferio derecho.","La única función en la que no es posible apreciar dominancias es la visión.","En la mayoría de los individuos, las capacidades visoespaciales y la geometría presentan dominancia derecha."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-027 / G0485 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-EXAMEN-2017-2018-1 (1).pdf / ex. 2021 (respuestas).pdf (Pregunta #10 - Dominancia Cerebral)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-28","number":"28","statement":"Indique la relación anatómica CORRECTA sobre las estructuras telencefálicas y ventriculares:","options":["Hipocampo → inferior al asta temporal del ventrículo lateral.","Foramen interventricular → límite anterior del asta occipital del ventrículo lateral.","Cuerpo del núcleo caudado → medial al cuerpo del ventrículo lateral.","Plexo coroideo → el ventrículo lateral carece de plexo coroideo."],"answer":0,"explanation":"[Nota de la clave] O hipocampo situa-se diretamente no assoalho do corno/asta inferior do ventrículo lateral).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-028 / G0488 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: examenes neuro compl (1).pdf / perguntas neuro julio exame.docx (Pregunta #9 - Relaciones Ventriculares)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-29","number":"29","statement":"Indica la asociación CORRECTA respecto a las áreas corticales motoras y sus proyecciones:","options":["Corteza motora primaria (área 4) = se encarga de ejecutar el movimiento y recibe conexiones desde la corteza premotora.","Corteza del cíngulo = se encarga de aspectos emocionales que tienen relación con el movimiento.","Capa V de la corteza motora = desde ella nacen la mayoría de proyecciones motoras subcorticales.","Fibras de asociación = pueden conectar distintas áreas motoras homolaterales.","Todas las respuestas son correctas."],"answer":4,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-029 / G0491 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-Examen-Neuro-3.pdf / wuolah-free-tema-6-preguntas.pdf (Pregunta #70 - Áreas Motoras)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-30","number":"30","statement":"Respecto a las características histológicas de la corteza cerebral, señale la afirmación CORRECTA:","options":["Es uniforme en grosor y estructura en toda su extensión.","Tiene siempre cinco capas, siendo la capa I la más externa (en contacto con la piamadre).","Tiene siempre cinco capas, siendo la capa I la más interna (en contacto con la sustancia blanca).","El neocórtex se caracteriza por tener siempre seis capas, siendo la capa VI la más interna (en contacto con la sustancia blanca).","Ninguna de las anteriores es cierta."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-030 / G0494 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-Examen-Neuro-3.pdf / wuolah-free-tema-6-preguntas.pdf (Pregunta #23 - Capas del Neocórtex)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-31","number":"31","statement":"Sobre las fibras de asociación del telencéfalo, es CORRECTO que:","options":["Son axones que se originan principalmente en las células piramidales de la capa III y conectan regiones del mismo hemisferio.","Son axones de la capa V que cruzan a través del cuerpo calloso.","Conectan exclusivamente la corteza cerebral con núcleos del tronco del encéfalo a través de la cápsula interna.","Unen puntos simétricos de hemisferios opuestos."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-031 / G0495 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: perguntas neuro julio exame.docx / TEMA 6 – TELENCÉFALO.pdf (Sección Fibras Corticocorticales)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-32","number":"32","statement":"En relación a la formación hipocampal y sus vías de conexión, señale la opción CORRECTA:","options":["Los axones de las neuronas piramidales del subículo se comunican con las fibras musgosas.","Las colaterales de Schaffer conectan neuronas piramidales desde CA1 hacia CA3.","Los axones de las neuronas de la corteza entorrinal que se dirigen al giro dentado constituyen parte de la vía perforante.","El conjunto de fibras que abandona el hipocampo atravesando el subículo se denomina alveolo."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-032 / G0496 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-EXAMEN-2017-2018-1 (1).pdf / examenes neuro compl (1).pdf (Pregunta #8 - Formación Hipocampal)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-33","number":"33","statement":"¿Cuál de los siguientes elementos subcorticales del sistema límbico se encuentra en el lóbulo temporal e interactúa activamente en el procesamiento de respuestas emocionales de miedo?:","options":["Área septal","Cuerpos mamilares","Núcleos amigdalinos (amígdala cerebral)","Núcleo anterior del tálamo"],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-033 / G0497 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: perguntas neuro julio exame.docx / Tema 1.7 - Telencéfalo 25-26 (2).pdf (Pregunta #35 - Sistema Límbico)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-34","number":"34","statement":"¿Qué tipo celular interneuronal de la neocorteza cerebral se caracteriza por presentar axones ascendentes verticales que llegan hasta la Capa I (plexiforme/molecular) para realizar sinapsis con las dendritas apicales de las células piramidales?:","options":["Células en cesta (basket cells).","Células de Martinotti.","Células horizontales de Cajal.","Células estrelladas / granulares."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-034 / G0501 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: 10-07 Clase_ Anatomía del Telencéfalo - Corteza Cerebral y Organización Laminar-transcript.txt / wuolah-free-tema-6- preguntas.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-35","number":"35","statement":"Sobre la anatomía superficial y los lóbulos del telencéfalo es FALSO que:","options":["El surco central (de Rolando) separa el giro precentral (frontal) del giro postcentral (parietal).","La ínsula es un lóbulo oculto situado en la profundidad de la fisura lateral (de Silvio).","En la superficie mediosagital del lóbulo occipital encontramos una región prominente llamada uncus.","La corteza cingulada (giro del cíngulo) se dispone en la superficie medial del telencéfalo, superior al cuerpo calloso."],"answer":2,"explanation":"No incluida en el material.","hack":"La profesora Aitana utiliza el Hack de Trampa de Ubicación del Uncus: el uncus (gancho del giro parahipocampal) pertenece anatómicamente al lóbulo temporal (superficie anteromedial) y no al lóbulo occipital. En la superficie medial del lóbulo occipital encontramos la cuña (cuneus) y el giro lingual, delimitados por el surco calcarino.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-035 / G0792 del banco canónico | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #76) / TEMA 6 – TELENCÉFALO.pdf / 10-06 Clase_ Organización Anatómica del Telencéfalo","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-36","number":"36","statement":"Sobre la histología de la corteza cerebral y sus componentes celulares, señale la opción CORRECTA:","options":["Un surco hace referencia a una hendidura cortical profunda que pliega los ventrículos y la fisura a una grieta superficial.","La capa molecular (capa I) es la más profunda de la neocorteza.","Las células horizontales de Cajal son pequeñas neuronas fusiformes que se localizan predominantemente en la capa I (molecular) de la corteza cerebral.","Las células de Purkinje son el principal tipo celular del neocórtex cerebral."],"answer":2,"explanation":"No incluida en el material.","hack":"Las células horizontales de Cajal son interneuronas inhibitorias fusiformes dispuestas paralelamente a la superficie cortical exclusivamente en la capa I (molecular). Las células de Purkinje son exclusivas de la corteza cerebelosa, no de la cerebral.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-036 / G0796 del banco canónico | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: ex. 2 (respuestas).pdf (Pregunta #25) / examenes neuro compl (1).pdf / 10-07 Clase_ Corteza Cerebral","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-37","number":"37","statement":"Señale la afirmación INCORRECTA sobre las fibras de sustancia blanca del cerebro:","options":["El fascículo longitudinal superior es una fibra de asociación intrahemisférica que conecta las cortezas frontal, parietal, occipital y temporal.","El cuerpo calloso es la mayor fibra de asociación cortical del encéfalo.","La cápsula interna contiene fibras de proyección que conectan la corteza cerebral con el tronco del encéfalo, médula y tálamo.","El fascículo uncinado es una fibra de asociación que conecta la corteza orbitofrontal con el polo anterior del lóbulo temporal."],"answer":1,"explanation":"No incluida en el material.","hack":"La trampa clásica de clasificación de fibras de sustancia blanca: Fibras de Asociación: Conectan distintas áreas dentro del mismo hemisferio (ej. fascículo uncinado, longitudinal superior, arcuato). Fibras Comisurales: Conectan áreas homólogas entre ambos hemisferios (ej. Cuerpo calloso, Comisura blanca anterior, Comisura del fórnix). Por tanto, el cuerpo calloso es una fibra comisural, NO de asociación. Fibras de Proyección: Conectan la corteza con estructuras subcorticales o caudales (ej. Cápsula interna).","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-037 / G0798 del banco canónico | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: Exame Neuroanatomia 2025 Meu (1).pdf (Pregunta #70) / 10-09 Clase_ Neuroanatomía - Hipocampo y Sustancia Blanca","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-38","number":"38","statement":"Respecto a la anatomía macroscópica del cuerpo calloso en un corte sagital medio del cerebro, indique el orden correcto de sus porciones desde la cara anterior/anteroinferior hacia la cara posterior:","options":["Pico (rostrum), rodilla (genu), cuerpo (tronco) y esplenio (rodete).","Esplenio, cuerpo, rodilla y pico.","Rodilla, pico, esplenio y cuerpo.","Pico, esplenio, cuerpo y rodilla."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Secuencia Anteroposterior de la Banca: Las 4 partes del cuerpo calloso dispuestas de anterior a posterior son: 1) Pico o rostrum (inferoanterior), 2) Rodilla o genu (curvatura anterior), 3) Cuerpo o tronco (porción media) y 4) Esplenio o rodete (extremo posterior engrosado sobre el tectum mesencefálico).","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-038 / G0801 del banco canónico | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #79) / TEMA 6 – TELENCÉFALO.pdf / 10-07 Clase_ Organización Celular y Funcional de la Corteza","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-39","number":"39","statement":"Al separar los bordes de la fisura lateral (de Silvio) se expone la superficie del lóbulo de la ínsula. Las porciones de los lóbulos frontal, parietal y temporal que cubren y ocultan a la ínsula se denominan:","options":["Opérculos (opérculo frontal, parietofrontal y temporal).","Comisuras.","Cisternas aracnoideas.","Pedúnculos cerebrales."],"answer":0,"explanation":"No incluida en el material.","hack":"\"Opérculo\" significa tapa o cubierta. Los opérculos frontal, frontoparietal y temporal cierran el labio superior e inferior de la fisura de Silvio y tapan por completo al lóbulo de la ínsula. La ínsula está rodeada por el surco circular de la ínsula y dividida por el surco central de la ínsula en giros cortos (anteriores) y giros largos (posteriores).","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-039 / G0805 del banco canónico | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #84) / TEMA 6 – TELENCÉFALO.pdf / 10-06 Clase_ Organización Anatómica del Telencéfalo","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-40","number":"40","statement":"El giro del cíngulo (corteza cingulada) bordea superiormente al cuerpo calloso. En su extremo posterior rodea el esplenio del cuerpo calloso mediante un estrechamiento denominado istmo, para continuarse directamente en la cara medial del lóbulo temporal como:","options":["Giro parahipocampal.","Giro precentral.","Giro frontal medio.","Cuña."],"answer":0,"explanation":"No incluida en el material.","hack":"El giro del cíngulo y el giro parahipocampal se continúan a través del istmo del giro del cíngulo detrás del esplenio del cuerpo calloso, formando juntos el \"Gran Lóbulo Límbico de Broca\" (anillo de corteza que rodea el circo o hilo del hemisferio cerebral).","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-040 / G0812 del banco canónico | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #94) / Tema 1.7 - Telencéfalo 25-26 (2).pdf / 10-08 Clase_ Sistema Límbico","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-41","number":"41","statement":"En la citoarquitectura de la neocorteza cerebral, ¿qué tipo de interneuronas multipolares se caracterizan por presentar un soma en capas profundas (V o VI) y enviar un axón ascendente hacia la capa I (molecular) para arborizarse e inhibir las dendritas de las neuronas piramidales?:","options":["Células de Martinotti.","Células piramidales de Betz.","Células horizontales de Cajal.","Células estrelladas de la capa IV."],"answer":0,"explanation":"No incluida en el material.","hack":"Tipos celulares específicos del neocórtex (pregunta de detalle fino de examen): Células de Martinotti: Somas en capas profundas (VI/V) -> axón ascendente vertical hacia la Capa I - > inhiben árboles dendríticos apicales piramidales. Células Horizontales de Cajal: Exclusivas de la Capa I, disposición horizontal paralela a la superficie. Células en Cesta (Basket cells): Interneuronas GABAérgicas que abrazan los somas piramidales en las capas III y V.Células Piramidales: Principales neuronas glutamatérgicas de proyección excitadora.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-041 / G0815 del banco canónico | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #100) / Tema 1.7 - Telencéfalo 25-26 (2).pdf / 10-07 Clase_ Organización Celular y Funcional","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-42","number":"42","statement":"La cápsula interna presenta subdivisiones topográficas bien definidas en un corte horizontal del cerebro. ¿Qué porción específica de la cápsula interna se sitúa posterior al lenticular y es atravesada por las radiaciones ópticas (geniculocalcarinas) en su trayecto hacia el lóbulo occipital?:","options":["Porción retrolenticular de la cápsula interna.","Brazo anterior de la cápsula interna.","Rodilla de la cápsula interna.","Porción sublenticular de la cápsula interna."],"answer":0,"explanation":"No incluida en el material.","hack":"Porción Retrolenticular: Pasa por detrás del núcleo lenticular e incluye las radiaciones ópticas (vía visual) y fibras cortico-occipitales/parietales. Su lesión provoca hemianopsia homónima contralateral. Porción Sublenticular: Pasa por debajo del núcleo lenticular e incluye las radiaciones acústicas (vía auditiva desde el cuerpo geniculado medial a Heschl) y el asa de Meyer.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-042 / G0832 del banco canónico | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #142) / Tema 1.7 - Telencéfalo 25-26 (2).pdf / 10-09 Clase_ Neuroanatomía - Hipocampo y Sustancia Blanca","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-43","number":"43","statement":"Entre las comisuras interhemisféricas telencefálicas, la comisura del fórnix (psalterio o líra de David) es una lámina de fibras comisurales que interconecta de forma transversal:","options":["Los pilares posteriores y fimbrias de ambos hipocampos por debajo del esplenio del cuerpo calloso.","Los dos núcleos caudados a través del tabique transparente.","Las dos cortezas prefrontales dorsolaterales.","Los bulbos olfatorios principal y accesorio."],"answer":0,"explanation":"No incluida en el material.","hack":"La comisura del fórnix (psalterio o lira) está formada por fibras transversas que cruzan la línea media entre los dos pilares posteriores del fórnix antes de unirse en el cuerpo del trígono, permitiendo la comunicación recíproca entre las formaciones hipocampales izquierda y derecha.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-043 / G0833 del banco canónico | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #144) / TEMA 6 – TELENCÉFALO.pdf / 10-09 Clase_ Neuroanatomía - Hipocampo y Sustancia Blanca","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-44","number":"44","statement":"En la citoarquitectura laminar de la neocorteza, las conexiones asociativas intrahemisféricas (que conectan diferentes giros del mismo hemisferio) y las conexiones comisurales interhemisféricas (que cruzan por el cuerpo calloso) se originan predominantemente en los somas piramidales de:","options":["Capa III o Piramidal Externa.","Capa IV o Granulosa Interna.","Capa VI o Multiforme.","Capa I o Molecular."],"answer":0,"explanation":"No incluida en el material.","hack":"Origen de proyecciones corticales por capas: Capa III (Piramidal Externa): Origen principal de las fibras de asociación (intrahemisféricas) y comisurales (interhemisféricas/cuerpo calloso). Capa V (Piramidal Interna): Origen principal de las proyecciones eferentes subcorticales (vía corticoespinal, corticonuclear, corticostriatal y corticopontina). Capa VI (Multiforme): Origen exclusivo de las proyecciones corticotalámicas de retroalimentación hacia el tálamo.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-044 / G0834 del banco canónico | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #146) / 10-07 Clase_ Organización Celular y Funcional de la Corteza Cerebral / Tema 1.7","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-45","number":"45","statement":"El fascículo uncinado es un tracto de asociación intrahemisférico corto con forma de gancho. ¿Qué dos regiones telencefálicas interconecta directamente?:","options":["La corteza orbitofrontal (lóbulo frontal inferior) con el polo anterior del lóbulo temporal (amígdala e hipocampo).","El lóbulo occipital izquierdo con el lóbulo occipital derecho.","El núcleo rojo con el núcleo del III par craneal.","La corteza motora primaria con la médula espinal lumbar."],"answer":0,"explanation":"No incluida en el material.","hack":"El fascículo uncinado cruza sobre el fondo de la fisura lateral de Silvio uniendo la corteza orbitofrontal con las estructuras límbicas del polo temporal anterior (amígdala e hipocampo). Participa en la regulación del comportamiento guiado por emociones y en la asociación entre olores/estímulos visuales y memoria emocional.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-045 / G0845 del banco canónico | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #175) / 10-09 Clase_ Neuroanatomía - Hipocampo y Sustancia Blanca / TEMA 6 – TELENCÉFALO.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-46","number":"46","statement":"En la lámina cortical del neocórtex, las neuronas en cesta (basket cells) y las células en candelabro (chandelier cells) son interneuronas GABAérgicas esenciales que regulan la excitabilidad de las células piramidales. ¿Qué porción específica de la neurona piramidal es blanco directo del axón de una célula en candelabro?:","options":["El segmento inicial del axón (AIS) de la célula piramidal, para ejercer un potente control inhibitorio sobre la generación del potencial de acción.","Las espinas dendríticas apicales en la capa I.","El núcleo celular exclusivamente.","Los astrocitos de la glía limitante."],"answer":0,"explanation":"No incluida en el material.","hack":"Detalle Citoarquitectónico Cortical: Células en Candelabro (Chandelier cells): Hacen sinapsis exclusivamente sobre el segmento inicial del axón (AIS) de las células piramidales (controlan el gatillo de disparo). Células en Cesta (Basket cells): Hacen sinapsis sobre el soma/cuerpo celular de las neuronas piramidales.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-046 / G0853 del banco canónico | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #194) / Tema 1.7 - Telencéfalo 25-26 (2).pdf / 10-07 Clase_ Organización Celular y Funcional","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-47","number":"47","statement":"¿Qué estructura anatómica separa el lóbulo de la ínsula de los opérculos frontal, parietal y temporal rodeándolo en su periferia?:","options":["Surco circular de la ínsula (surco limítrofe de Reil).","Surco central (de Rolando).","Fisura calcarina.","Surco hipotalámico."],"answer":0,"explanation":"No incluida en el material.","hack":"El surco circular de la ínsula delimita periféricamente el lóbulo insular, separándolo de los opérculos adyacentes. En el interior del lóbulo, el surco central de la ínsula divide la superficie insular en giros cortos (anteriores) y giros largos (posteriores).","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-047 / G0856 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: TEMA 6 – TELENCÉFALO.pdf / Tema 1.7 - Telencéfalo 25-26 (2).pdf / 10-06 Clase_ Organización Anatómica del Telencéfalo","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-48","number":"48","statement":"En el piso del asta inferior (temporal) del ventrículo lateral, los axones de las neuronas piramidales del hipocampo convergen en una delgada capa de sustancia blanca en su superficie ventricular denominada:","options":["Alvéolo, el cual se continúa medialmente para formar la fimbria del hipocampo.","Cuerpos mamilares.","Estría terminal.","Induseum griseum."],"answer":0,"explanation":"No incluida en el material.","hack":"Las fibras eferentes de las neuronas piramidales del hipocampo cubren su cavidad ventricular formando el alvéolo. Estas fibras se engrosan hacia el borde medial para constituir la fimbria del hipocampo, la cual se continúa posteriormente como el pilar posterior del fórnix.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-048 / G0857 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: 10-09 Clase_ Neuroanatomía - Hipocampo y Sustancia Blanca / TEMA 6 – TELENCÉFALO.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-49","number":"49","statement":"Las fibras comisurales de la rodilla del cuerpo calloso se curvan hacia adelante para interconectar las regiones anteriores de ambos lóbulos frontales, formando la estructura denominada:","options":["Fórceps menor (forceps minor / fórceps frontal).","Fórceps mayor (forceps major / fórceps occipital).","Tapetum.","Estría medular."],"answer":0,"explanation":"No incluida en el material.","hack":"Rodilla del cuerpo calloso: Arquea fibras hacia adelante -> Fórceps menor (interconecta los polos frontales). Esplenio del cuerpo calloso: Arquea fibras hacia atrás -> Fórceps mayor (interconecta los polos occipitales).","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-049 / G0859 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: Tema 1.7 - Telencéfalo 25-26 (2).pdf / 10-09 Clase_ Neuroanatomía - Hipocampo y Sustancia Blanca","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-50","number":"50","statement":"Respecto a la clasificación filogenética de la corteza cerebral, ¿cuál es la denominación y número de capas del tipo de corteza más antiguo evolutivamente, representada por el hipocampo y el giro dentado?:","options":["Arquicórtex (alocorteza de 3 capas celulares).","Paleocórtex de 6 capas.","Isocorteza homotípica de 5 capas.","Neocórtex agranular de 8 capas."],"answer":0,"explanation":"No incluida en el material.","hack":"Clasificación filogenética de la corteza: Arquicórtex (3 capas): La más antigua (Hipocampo, Giro Dentado). Paleocórtex (3-5 capas): Olfatorio (Corteza piriforme, uncus, bulbo olfatorio). Neocórtex / Isocórtex (6 capas): La más reciente evolutivamente (90% del manto cerebral humano).","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-050 / G0863 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: 10-07 Clase_ Organización Celular y Funcional de la Corteza Cerebral / TEMA 6 – TELENCÉFALO.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-51","number":"51","statement":"El cíngulo (cingulum) es un potente haz de sustancia blanca de asociación intrahemisférica que discurre por dentro de la corteza cingulada. ¿Qué regiones telencefálicas interconecta a lo largo de su recorrido en la cara medial del hemisferio?:","options":["La corteza frontal medial y el área septal con el giro parahipocampal y la corteza temporal medial.","El polo occipital izquierdo con el polo occipital derecho.","La corteza motora primaria con el núcleo dentado del cerebelo.","La retina con el cuerpo geniculado lateral."],"answer":0,"explanation":"No incluida en el material.","hack":"El cíngulo (cingulum) es la columna vertebral de sustancia blanca que recorre por debajo del giro del cíngulo, conectando las regiones limbinas anteriores (septal/frontal) con el giro parahipocampal en el lóbulo temporal, cerrando el bucle del Circuito de Papez.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-051 / G0867 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: Tema 1.7 - Telencéfalo 25-26 (2).pdf / 10-08 Clase_ Sistema Límbico / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-52","number":"52","statement":"Indica la relación CORRECTA sobre las siguientes áreas de Brodmann:","options":["Área 4 - Responsable de la percepción sensorial.","Área 6 - Esencial para el procesamiento visual.","Área 17 - Planificación y ejecución de movimientos voluntarios.","Área 22 - Involucrada en el procesamiento de lenguaje y la comprensión auditiva."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-052 / G0994 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-53","number":"53","statement":"El cuerpo calloso:","options":["Está compuesto por fibras nerviosas que conectan la corteza cerebral con el tálamo.","Facilita la comunicación entre los hemisferios cerebrales y está compuesto principalmente por axones mielinizados.","Se encuentra en el lóbulo temporal y participa en la integración de la información auditiva.","Está formado por axones de neuronas piramidales que proyectan hacia la médula espinal."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-053 / G0995 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-54","number":"54","statement":"Sobre la anatomía del telencéfalo es FALSO que:","options":["El surco central (de Rolando) separa el giro precentral del giro postcentral.","La ínsula se encuentra por debajo de la fisura lateral (de Silvio).","En la superficie mediosagital del lóbulo occipital encontramos una región llamada uncus.","La corteza cingulada se encuentra en la profundidad del telencéfalo, superior el cuerpo calloso."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-054 / G0996 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-55","number":"55","statement":"Sobre la sustancia blanca cerebral es CIERTO que:","options":["El cuerpo calloso es el mayor tracto de asociación, que comunica distintos lóbulos dentro del mismo hemisferio cerebral.","El fascículo uncinado conecta de forma contralateral la corteza frontal con la corteza temporal.","Las fibras de asociación cortas, como el cíngulo, conectan circunvoluciones adyacentes.","El extremo anterior del cuerpo calloso se llama rodilla, y se dobla por delante del septum pellucidum."],"answer":3,"explanation":"[Notas/explicación original separada] La afirmación CIERTA es la D) El extremo anterior del cuerpo calloso se llama rodilla, y se dobla por delante del septum pellucidum. A continuación, te detallo por qué esta es la respuesta correcta y el motivo por el cual las demás opciones son falsas según los apuntes: D) CIERTA: El cuerpo calloso es la principal comisura del cerebro y, anatómicamente, presenta una parte principal (el cuerpo), un extremo posterior (esplenio o rodete), y un extremo anterior engrosado que se curva llamado rodilla. Esta rodilla se sitúa por delante del septum pellucidum, la fina membrana que separa las astas anteriores de los ventrículos laterales. A) FALSA: El cuerpo calloso no es un tracto de asociación, sino el principal haz de fibras comisurales. Su función es conectar áreas coincidentes de los dos hemisferios cerebrales opuestos, cruzando la línea media, y no distintos lóbulos dentro de un mismo hemisferio. B) FALSA: El fascículo uncinado es un haz de fibras de asociación (largas) que conecta el lóbulo frontal con la porción anterior del lóbulo temporal, pero lo hace siempre dentro del mismo hemisferio (de forma ipsilateral). Las únicas fibras que conectan de forma contralateral son las comisurales. C) FALSA: Aunque es correcto que las fibras de asociación cortas comunican circunvoluciones adyacentes, el cíngulo está clasificado como un haz de fibras de asociación largas (conecta zonas más alejadas a lo largo de la corteza del giro cingulado).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-055 / G0997 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-56","number":"56","statement":"Indica la afirmación CORRECTA sobre el cerebro:","options":["Presenta un surco central (de Rolando) que separa el lóbulo temporal del fronto-parietal.","Presenta circunvoluciones, como la cingular, que es visible en un plano medio-sagital y discurre superiormente con respecto al cuerpo calloso.","Tiene una región ubicada en el lóbulo occipital que se llama uncus.","Presenta una región en el lóbulo temporal que se llama ínsula (área 5 de Brodmann)."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-056 / G0998 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-57","number":"57","statement":"El área hipocampal:","options":["No recibe información de la corteza cerebral.","Está constituido, entre otras regiones, por el hipocampo, el cual es un tipo de paleocórtex que presenta 4 capas celulares.","No tiene relación alguna con la amígdala cerebral.","Se comunica con los núcleos mamilares vía fórnix."],"answer":3,"explanation":"NotebookLM - Justificación/Mapa de las Mentiras: Mecanismo Neurológico (Técnica Feynman): El hipocampo (la fábrica de los recuerdos) no guarda los archivos en su propio edificio. Para que un recuerdo se guarde a largo plazo, el hipocampo lo empaqueta y lo envía por un cable grueso y curvado (el Fórnix) hacia una estación de correos inferior llamada \"núcleos mamilares\" del hipotálamo. Este es el primer vector innegociable del famoso Circuito de Papez para la memoria declarativa. Prueba Teórica Verbatim: \"La principal eferencia es el fórnix... que proyecta hasta los núcleos mamilares del hipotálamo\". EL MAPA DE LAS MENTIRAS (DISECCIÓN DE DISTRACTORES) Alternativa a): No recibe información de la corteza cerebral. Por qué es falsa y Hack detectado: Hack 05 (Negación Absoluta). Es fisiológicamente un absurdo. Si el hipocampo no recibiera información de la corteza (lo que ves, oyes y sientes), no tendría \"materia prima\" con la cual fabricar recuerdos. Su autopista principal de entrada (la Vía Perforante) proviene directamente de la Corteza Entorrinal. Corrección: El área hipocampal SÍ recibe información masiva de la corteza cerebral (vía entorrinal). Prueba de Refutación: \"La principal aferencia es la vía perforante que se proyecta desde la corteza entorrinal\". Alternativa b): Está constituido, entre otras regiones, por el hipocampo, el cual es un tipo de paleocórtex que presenta 4 capas celulares. Por qué es falsa y Hack detectado: Hack de Disfraz Numérico. El examinador utiliza una verdad evolutiva para colar una mentira histológica. El hipocampo SÍ es una corteza antigua (paleocórtex/arquicórtex), pero por su antigüedad primitiva, su arquitectura básica está compuesta EXCLUSIVAMENTE por 3 capas celulares (molecular, piramidal/granulosa, polimorfa). Afirmar que tiene 4 (o las 6 del neocórtex) arruina la opción. Corrección: El paleocórtex del hipocampo presenta 3 capas celulares. Prueba de Refutación: \"El hipocampo, al igual que el giro dentado, presenta tres capas\" (Validado en múltiples preguntas históricas de la cátedra como axioma verdadero). Alternativa c): No tiene relación alguna con la amígdala cerebral. Por qué es falsa y Hack detectado: Palabras Restrictivas (\"alguna\"). Falso por anatomía y por función. Ambas estructuras son \"vecinas\" compartiendo piso en el lóbulo temporal medial y forman el núcleo del Sistema Límbico. El hipocampo le da el contexto al miedo que dispara la amígdala (ej. \"le tengo fobia a los perros porque recuerdo que uno me mordió\"). Corrección: El hipocampo y la amígdala están íntimamente relacionados en el sistema límbico. Prueba de Refutación: \"El hipocampo es donde llega la información sensitiva para que lo empecemos a recordar... y con la amígdala la percepción del miedo\" (trabajan en paralelo).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-057 / G1176 del banco canónico | archivos: tema 1.8 e outros cru notebooklm.pdf | referencias indicadas: tema 1.8 e outros cru notebooklm.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-58","number":"58","statement":"Indique la relación CORRECTA:","options":["Tracto del cíngulo -> largo tracto de asociación que comunica diferentes lóbulos del mismo hemisferio cerebral y que es superior con respecto al cuerpo calloso.","Rodete del cuerpo calloso -> parte más anterior o rostral del cuerpo calloso.","Fisura calcarina -> la encontramos en la ínsula.","Área de Broca -> área más posterior del lenguaje (área 22)."],"answer":0,"explanation":"NotebookLM - Justificación/Mapa de las Mentiras: Mecanismo Neurológico (Técnica Feynman): El cerebro tiene dos tipos de cables (sustancia blanca). Los que cruzan de un lado a otro (comisurales, como el cuerpo calloso) y los que viajan de adelante hacia atrás conectando el mismo hemisferio (tractos de asociación). El \"Tracto del Cíngulo\" es un enorme cable en forma de \"C\" que viaja escondido dentro del giro cingulado. Como el giro cingulado \"abraza\" al cuerpo calloso por arriba, este tracto viaja literalmente como un techo (superior) sobre el cuerpo calloso, conectando el lóbulo frontal, parietal y temporal de tu lado izquierdo consigo mismo. Prueba Teórica Verbatim: \"Tracto del cíngulo -> largo tracto de asociación que comunica diferentes lóbulos del mismo hemisferio cerebral y que es superior con respecto al cuerpo calloso\" (Axioma consolidado en las plantillas oficiales). EL MAPA DE LAS MENTIRAS (DISECCIÓN DE DISTRACTORES) Alternativa b): Rodete del cuerpo calloso -> parte más anterior o rostral del cuerpo calloso. Por qué es falsa y Hack detectado: Hack 03 (Guerra de opuestos). El examinador invierte el eje espacial del cerebro. El cuerpo calloso tiene una \"Rodilla\" (genu) que mira hacia tu frente (anterior) y un \"Rodete\" o Esplenio que mira hacia tu nuca (posterior). Decir que el rodete es rostral (anterior) es una mentira topográfica absoluta. Corrección: El rodete del cuerpo calloso es la parte más POSTERIOR (caudal). Prueba de Refutación: \"Rodete -> parte del cuerpo calloso más anterior que la rodilla\" (Otra pregunta del mismo banco la cataloga como 100% FALSA por la misma inversión). Alternativa c): Fisura calcarina -> la encontramos en la ínsula. Por qué es falsa y Hack detectado: Hack de Coordenadas Cruzadas. La ínsula es un lóbulo escondido en la profundidad del surco lateral (surco de Silvio), que procesa el gusto y el asco. La fisura calcarina es el cañón anatómico fundamental del lóbulo OCCIPITAL, a cuyas orillas se asienta la corteza visual primaria (área 17) para que puedas ver la luz. Corrección: La fisura calcarina se encuentra en el lóbulo occipital. Prueba de Refutación: \"Fisura calcarina -> rama de la arteria cerebral posterior [zona visual occipital]\". Alternativa d): Área de Broca -> área más posterior del lenguaje (área 22). Por qué es falsa y Hack detectado: Hack 03 (Guerra de opuestos y coordenadas cruzadas). El área de Broca es la fábrica donde se ejecutan los músculos para hablar, por lo que reside obligatoriamente en el lóbulo FRONTAL (área ANTERIOR del lenguaje, áreas 44 y 45). El área \"posterior\" del lenguaje (área 22 en el lóbulo temporal) es el Área de Wernicke, que sirve para comprender lo que escuchas. Corrección: El Área de Broca es el área ANTERIOR del lenguaje (áreas 44/45). El área posterior (22) es Wernicke. Prueba de Refutación: \"el área de Broca, que era la que se encuentra en el lóbulo frontal... se corresponde con las áreas de Brodman 44 y 45\".","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-058 / G1177 del banco canónico | archivos: tema 1.8 e outros cru notebooklm.pdf | referencias indicadas: tema 1.8 e outros cru notebooklm.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-59","number":"59","statement":"Sobre las capas del neocórtex es CIERTO que:","options":["La capa I contiene principalmente células piramidales grandes responsables de la salida motora.","La capa IV es rica en células granulares y es la principal receptora de aferencias talámicas.","La capa V no contiene neuronas piramidales de proyección.","Las 6 capas presentan el mismo espesor en todas las áreas cerebrales."],"answer":1,"explanation":"Por qué la B es CORRECTA: La Capa IV (granulosa interna) destaca por su alta densidad de células granulares/estrelladas y es la receptora primaria de las proyecciones sensoriales específicas procedentes de los núcleos de relevo del tálamo. Desmonte de los Distractores Falsos: A (Falsa): La Capa I (molecular) es la más superficial y es prácticamente acelular (formada por axones y dendritas). C (Falsa): La Capa V (piramidal interna) es la capa eferente principal y contiene las neuronas piramidales de proyección. D (Falsa): El espesor de las capas varía según la función (Corteza heterotípica agranular motora en M1 vs. heterotípica granular sensitiva en S1 y V1).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-059 / G1211 del banco canónico | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #53)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-60","number":"60","statement":"Indique la relación CORRECTA entre el área de Brodmann y su función principal:","options":["Área 4 – Corteza somatosensorial primaria.","Área 17 – Corteza auditiva primaria.","Áreas 41 y 42 – Corteza motora primaria.","Área 22 – Involucrada en la comprensión del lenguaje auditivo (Área de Wernicke)."],"answer":3,"explanation":"Versión 1 (formato del examen original, pregunta #54): el enunciado pide la relación CORRECTA. Por qué la D es CORRECTA: el área 22 es el área de Wernicke, encargada de la comprensión del lenguaje auditivo. A (Falsa): el área 4 es la corteza motora primaria; la somatosensorial primaria son las áreas 1, 2 y 3. B (Falsa): el área 17 es la corteza visual primaria; la auditiva primaria son las áreas 41 y 42. C (Falsa): las áreas 41 y 42 son la corteza auditiva primaria (giros de Heschl), no la motora.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-060 / G1212 del banco canónico | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #54) – versión corregida 1 de 2","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-61","number":"61","statement":"Indique la relación INCORRECTA entre el área de Brodmann y su función principal:","options":["Área 4 – Corteza motora primaria (giro precentral).","Área 17 – Corteza visual primaria (corteza estriada / giro calcarino).","Áreas 41 y 42 – Corteza de asociación auditiva y comprensión del lenguaje.","Área 22 – Área de Wernicke e integración de la comprensión del lenguaje hablado/escrito."],"answer":2,"explanation":"Versión 2 (se mantiene el enunciado INCORRECTA): por qué la C es INCORRECTA: las áreas 41 y 42 son la corteza auditiva PRIMARIA (giros transversos de Heschl), que recibe el sonido bruto del cuerpo geniculado medial. La función de asociación y comprensión del lenguaje (área de Wernicke) corresponde al área 22 (lóbulo temporal superior posterior).","hack":"La banca cambia \"primaria\" por \"asociación/secundaria\" entre áreas vecinas (41/42 frente a 22) para castigar la lectura con prisa.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-060b / G1212 del banco canónico | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #54) – versión corregida 2 de 2","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-62","number":"62","statement":"Sobre la sustancia blanca cerebral es CIERTO que:","options":["El cuerpo calloso es el mayor tracto de asociación, que comunica distintos lóbulos dentro del mismo hemisferio cerebral.","Las fibras de proyección conectan la corteza cerebral con regiones subcorticales, del tronco del encéfalo o de la médula espinal.","Las fibras comisurales comunican áreas funcionales dentro del mismo hemisferio.","La cápsula interna está formada únicamente por axones amielínicos."],"answer":1,"explanation":"Por qué la B es CORRECTA: las fibras de proyección (cápsula interna, corona radiada) conectan la corteza con estructuras subcorticales, tronco del encéfalo y médula espinal. A (Falsa): el cuerpo calloso es la mayor comisura, no un tracto de asociación. C (Falsa): las fibras comisurales conectan hemisferios opuestos; las que unen áreas del mismo hemisferio son de asociación. D (Falsa): la cápsula interna está formada por axones mielinizados.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-061 / G1213 del banco canónico | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #80) / perguntas neuro julio exame.docx (Pregunta #37)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-63","number":"63","statement":"Indica cuál de las siguientes afirmaciones es INCORRECTA:","options":["El cuerpo calloso cruza la línea media en la zona profunda de la fisura cerebral longitudinal","La mayoría de las fibras del interior del cuerpo calloso conectan entre sí áreas simétricas de la corteza cerebral","La fisura cerebral longitudinal contiene el pliegue de duramadre, la hoz del cerebelo","La cápsula interna está flanqueada medialmente por el núcleo caudado y el tálamo"],"answer":2,"explanation":"Por qué la C es INCORRECTA: la fisura cerebral longitudinal contiene la hoz del cerebro (falx cerebri); la hoz del cerebelo se ubica en la fosa craneal posterior. A: el cuerpo calloso está en la profundidad de la fisura longitudinal. B: sus axones conectan áreas simétricas de ambos hemisferios. D: la cápsula interna es lateral al tálamo y a la cabeza del núcleo caudado y medial al núcleo lenticular.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-062 / G1214 del banco canónico | referencias indicadas: ex. 2 (respuestas).pdf (Pregunta #28) / ex. 2 (sin respuestas).pdf (Pregunta #28)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-64","number":"64","statement":"¿Cuál de las siguientes afirmaciones sobre la estructura laminar de las áreas corticales de Brodmann es CORRECTA?:","options":["El grosor de las capas del neocórtex es uniforme, independientemente de su funcionalidad sensorial o motora.","La capa IV (granulosa interna) está hipertrofiada en las áreas sensoriales primarias.","La capa V (piramidal interna) es más delgada en la corteza motora primaria que en las áreas sensoriales.","La capa molecular del giro dentado contiene principalmente células piramidales responsables de la salida eferente."],"answer":1,"explanation":"Por qué la B es CORRECTA: en las áreas sensoriales primarias (V1, S1, A1) la capa IV está muy desarrollada (corteza heterotípica granular) para recibir las aferencias talamocorticales. A (Falsa): el grosor varía según la función. C (Falsa): la capa V es más gruesa en M1. D (Falsa): el giro dentado es arquicórtex y sus células principales son granulares.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-063 / G1218 del banco canónico | referencias indicadas: exame neuro 2025 transcrito juneka.pdf (Pregunta #67/71) / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #53)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-65","number":"65","statement":"Señala la afirmación CORRECTA sobre la histología del neocórtex:","options":["La capa granulosa interna es rica en células granulares para la recepción de la mayoría de las aferencias talámicas.","La capa piramidal (ganglionar) interna contiene fibras horizontales y pocas neuronas.","La capa molecular presenta abundantes células piramidales grandes que proyectan a la médula espinal.","La capa polimorfa es la capa más superficial."],"answer":0,"explanation":"Por qué la A es CORRECTA: La Capa IV (granulosa interna) es la capa receptora por excelencia donde hacen sinapsis las fibras aferentes específicas provenientes de los núcleos de relevo del tálamo. Desmonte de los Distractores Falsos: B (Falsa): La capa V (piramidal interna) es densa en somas de neuronas piramidales de proyección eferente. C (Falsa): La capa I (molecular) es la más superficial y carece de motoneuronas gigantes. D (Falsa): La capa VI (polimorfa/fusiforme) es la capa más PROFUNDA (en contacto con la sustancia blanca), mientras que la capa I es la más superficial.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-064 / G1219 del banco canónico | referencias indicadas: exame neuro 2025 transcrito juneka.pdf (Pregunta #67/71) / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #53)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-66","number":"66","statement":"Sobre la sustancia blanca cerebral es CIERTO que:","options":["El cuerpo calloso es el mayor tracto de asociación, que comunica distintos lóbulos dentro del mismo hemisferio cerebral.","El fascículo uncinado conecta de forma contralateral la corteza frontal con la corteza temporal.","Las fibras de proyección conectan la corteza cerebral con regiones subcorticales, del tronco del encéfalo o de la médula espinal.","La cápsula interna está formada únicamente por axones amielínicos."],"answer":2,"explanation":"Por qué la C es CORRECTA: las fibras de proyección unen la corteza con estructuras subcorticales, tronco y médula. A: el cuerpo calloso es comisural, no de asociación. B: el fascículo uncinado es de asociación ipsilateral (frontal-temporal del mismo hemisferio). D: la cápsula interna contiene axones mielinizados.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-065 / G1222 del banco canónico | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #80) / perguntas neuro julio exame.docx (Pregunta #37)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-67","number":"67","statement":"Señala la respuesta CORRECTA sobre la corteza cerebral:","options":["La fisura calcarina se encuentra en la ínsula.","Las neuronas piramidales de mayor tamaño se encuentran en la capa granulosa interna de la neocorteza.","El giro precentral se corresponde con el área sensitiva primaria y el giro postcentral con el área motora primaria.","El área prefrontal está relacionada con la constitución de la personalidad del sujeto."],"answer":3,"explanation":"Por qué la D es CORRECTA: la corteza prefrontal gobierna la conducta, la personalidad, el juicio social y las funciones ejecutivas. A (Falsa): la fisura calcarina está en la cara medial del lóbulo occipital. B (Falsa): las neuronas piramidales de mayor tamaño (Betz) están en la capa V. C (Falsa): el giro precentral es el área motora primaria y el postcentral el área sensitiva primaria.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-066 / G1223 del banco canónico | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #109) / perguntas neuro julio exame.docx (Pregunta #58)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-68","number":"68","statement":"¿Cuál de las siguientes afirmaciones sobre la estructura laminar de las áreas corticales de Brodmann es CORRECTA?:","options":["El grosor de las capas del neocórtex es uniforme, independientemente de su funcionalidad sensorial o motora.","La capa IV (granulosa interna) está hipertrofiada en las áreas sensoriales primarias.","La capa IV del área 6 es la que contiene el mayor número de axones de proyección constituyentes de la vía piramidal.","La capa II del área 17 es la capa que recibe el mayor número de las aferencias del núcleo geniculado lateral."],"answer":1,"explanation":"Por qué la B es CORRECTA: en las áreas sensoriales primarias (V1, S1, A1) la capa IV está muy desarrollada (corteza heterotípica granular) para recibir las aferencias talamocorticales. A (Falsa): el grosor varía según la función. C (Falsa): la capa V es más gruesa en M1. D (Falsa): el giro dentado es arquicórtex y sus células principales son granulares.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-067 / G1225 del banco canónico | referencias indicadas: exame neuro 2025 transcrito juneka.pdf (Pregunta #67/71) / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #53)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-69","number":"69","statement":"Área funcional que no está en el lóbulo frontal:","options":["Broca","Motora suplementaria.","Ocular frontal.","Wernicke"],"answer":3,"explanation":"Justificación y análisis de las alternativas: || A) Broca – INCORRECTA: Se localiza en el lóbulo frontal (circunvolución frontal inferior, áreas 44 y 45 de Brodmann) y participa en la planificación y producción motora del habla. || B) Motora suplementaria – INCORRECTA: Se ubica en la cara medial del lóbulo frontal (porción medial del área 6 de Brodmann) e interviene en la planificación de secuencias motoras. || C) Ocular frontal – INCORRECTA: Se encuentra en el lóbulo frontal (área 8 de Brodmann) y controla los movimientos oculares dirigidos y la mirada voluntaria. || D) Wernicke – CORRECTA: El área de Wernicke (área 22 de Brodmann) no se ubica en el lóbulo frontal, sino en el lóbulo temporal (cara superior y posterior, extendiéndose hacia regiones temporoparietales). Su función principal es la comprensión del lenguaje.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-068 / G1228 del banco canónico | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf / Simulado_Tema_1_7_FINAL_108.pdf · Pregunta 003 · Fuente original: 06_Tema_1.7_Telencefalo_cerebro_areas_asociadas.docx","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-70","number":"70","statement":"Señala la respuesta CORRECTA sobre la corteza cerebral:","options":["La fisura calcarina se encuentra en la ínsula.","Las neuronas piramidales de mayor tamaño se encuentran en la capa granulosa interna de la neocorteza.","El giro precentral se corresponde con el área sensitiva primaria y el giro postcentral con el área motora primaria.","El área prefrontal está relacionada con la constitución de la personalidad del sujeto."],"answer":3,"explanation":"Por qué la D es CORRECTA: la corteza prefrontal gobierna la conducta, la personalidad, el juicio social y las funciones ejecutivas. A (Falsa): la fisura calcarina está en la cara medial del lóbulo occipital. B (Falsa): las neuronas piramidales de mayor tamaño (Betz) están en la capa V. C (Falsa): el giro precentral es el área motora primaria y el postcentral el área sensitiva primaria.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-069 / G1229 del banco canónico | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #109) / perguntas neuro julio exame.docx (Pregunta #58)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-71","number":"71","statement":"Un paciente con un accidente cerebrovascular isquémico que presenta déficit motor y sensitivo de predominio faciobraquial (cara y miembro superior) contralateral, junto con afasia, presenta una lesión que se encuadra dentro del territorio de la:","options":["Artéria cerebral anterior (ACA)","Artéria cerebral média (ACM)","Artéria cerebral posterior (ACP)","Artéria comunicante posterior"],"answer":1,"explanation":"Por qué la B es CORRECTA: La Arteria Cerebral Media (ACM) irriga la convexidad dorsolateral del hemisferio cerebral, donde se ubican la representación somatotópica de la cara y brazo en el homúnculo de Penfield, así como las áreas del lenguaje (Broca y Wernicke en el hemisferio izquierdo). Inversión de Territorios: La ACA irriga la superficie medial (pierna y pie), mientras que la ACP irriga el lóbulo occipital (corteza visual).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-070 / G1230 del banco canónico | referencias indicadas: 09-12 Clase_ Anatomía vascular cerebral / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-72","number":"72","statement":"¿Cuál de las siguientes afirmaciones sobre la estructura laminar de las áreas corticales de Brodmann es CORRECTA?:","options":["El grosor de las capas del neocórtex es uniforme, independientemente de su funcionalidad sensorial o motora.","En el área 4 predomina la capa V, con grandes células de Betz responsables de la vía corticoespinal.","La capa IV del área 6 es la que contiene el mayor número de axones de proyección constituyentes de la vía piramidal.","La capa II del área 17 es la capa que recibe el mayor número de las aferencias del núcleo geniculado lateral."],"answer":1,"explanation":"Por qué la B es CORRECTA: El Área 4 (M1) es una corteza agranular motora donde la Capa V se encuentra hipertrofiada albergando las células gigantes de Betz. Desmonte de los Distractores Falsos: A (Falsa): El grosor laminar es variable (corteza heterotípica motora vs. sensitiva). C (Falsa): Las fibras piramidales nacen de la Capa V, no de la Capa IV (además, el área 6 es motora y carece casi de capa IV). D (Falsa): Las aferencias talamocorticales ópticas del geniculado lateral llegan masivamente a la Capa IV (línea de Gennari en V1 / Área 17), NO a la Capa II.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-071 / G1232 del banco canónico | número original en el examen: 1 | referencias indicadas: exame neuro 2025 transcrito juneka.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-73","number":"73","statement":":","options":["Área de Brodmann 17 → 18, 19 → Giro angular → Área de Wernicke","Área de Brodmann 17 → 18, 19 → Fascículo arqueado → Área de Broca","Área de Brodmann 17 → Giro cingular → Área de Wernicke","Área de Brodmann 41, 42 → 18, 19 → Giro angular → Área de Wernicke"],"answer":0,"explanation":"Por qué la A es CORRECTA: La vía de la lectura exige: 1. Área 17 (V1): Recepción visual primaria del texto escrito. 2. Áreas 18 y 19 (V2/V3): Procesamiento asociativo visual. 3. Giro Angular (Área 39): Paso imprescindible para transformar el código visual (grafema) en fonema. 4. Área de Wernicke (Área 22): Interpretación y comprensión del significado del lenguaje. Distractor Clave: La opción D es incorrecta porque inicia en las áreas 41 y 42, las cuales corresponden a la corteza auditiva primaria (escuchar el habla), no a la lectura (que es vía visual 17).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada N-072 / G1235 del banco canónico | referencias indicadas: TEMA 7 – FUNCIONES CEREBRALES SUPERIORES.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-74","number":"74","statement":"En la cara ventral de la protuberancia, ¿cuál es la función de los núcleos pontinos y a través de qué pedúnculo cerebeloso envían sus axones cruzados hacia el cerebelo?:","options":["Actúan como relevo de información entre la corteza cerebral y el cerebelo a través del pedúnculo cerebeloso medio.","Relevan información propioceptiva de la médula directamente al tálamo.","Reciben información auditiva y proyectan al colículo superior.","Originan las fibras corticoespinales descendentes hacia la médula."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Falso Conector: Na prova, a banca costuma colocar a alternativa errada dizendo que os núcleos pontinos \"relavam informação entre a corteza e a médula espinal\". FALSO: Os núcleos pontinos relavam informação entre a corteza e o CEREBELO (vía cortico-ponto-cerebelosa) através do pedúnculo cerebeloso médio.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-001 / G0021 del banco canónico | integración: Tema 1.5.1 + Tema 1.7 + Tema 1.9.3 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: ex. 2 (respuestas).pdf (Pregunta #14) / Tema 1.5.1 - Tronco del encéfalo 25-26.pdf / 09-23 Clase_ Núcleos de la Protuberancia","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-75","number":"75","statement":"En la fosa romboidea del tronco del encéfalo, los núcleos vestibulares (superior, inferior, medial y lateral) ocupan el área vestibular. ¿A través de qué haz eferente coordinan los movimientos oculares compensatorios en respuesta a la estimulación vestibular (reflejo vestibulOcular - RVO)?:","options":["Fascículo Longitudinal Medial (FLM).","Lemnisco Medial.","Tracto Espinotalámico Lateral.","Fascículo Uncinado de Russell."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q55)] Hack del Reflejo Vestíbulo-Ocular (FLM): Los axones que nacen en los núcleos vestibulares ascienden por el Fascículo Longitudinal Medial (FLM) e inervan los núcleos motores oculares (III, IV y VI pares) de forma coordinada, permitiendo mantener la fijación foveal de la mirada durante los movimientos de la cabeza (Reflejo Vestíbulo- Ocular).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-002 / G0071 del banco canónico | integración: Tema 1.5.1 + Tema 1.7 + Tema 1.11.2 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 09-24 Clase_ Vías Sensitivas y Auditivas / TEMA 13 – SENTIDO DE LA AUDICIÓN.pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-76","number":"76","statement":"Los núcleos intralaminares del tálamo (entre los que destaca el núcleo centromediano) se encuentran inmersos en el espesor de la lámina medular interna. ¿Cuál es su papel neurofisiológico en la modulación de la actividad cerebral?:","options":["Reciben aferencias de la formación reticular, cerebelo y ganglios basales, y envían proyecciones difusas no específicas a la corteza cerebral para modular el nivel de alerta (arousal) y el dolor crónico.","Relevan de forma específica la información gustativa hacia el área 43 de Brodmann.","Son núcleos motores dedicados exclusivamente a la miosis pupilar.","Inervan las glándulas salivales submandibular y sublingual."],"answer":0,"explanation":"No incluida en el material.","hack":"Los Núcleos Intralaminares (Centromediano) no proyectan a un área cortical única, sino que envían proyecciones difusas a todo el manto neocortical, participando en el mantenimiento de la consciencia, el estado de vigilia y la percepción afectivo-difusa del dolor crónico.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-003 / G0083 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.7 + Tema 1.9.2 + Tema 1.9.3 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 10-30 Clase magistral_ Neuroanatomía meníngea / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #48) / TEMA 5 – DIENCÉFALO .pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-77","number":"77","statement":"En las clases magistrales se explica la modulación de la excitabilidad talámica por parte de la formación reticular troncoencefálica (complejo ponto-mesencefálico tegmental). ¿Cuál es el mecanismo neurológico mediante el cual este complejo promueve el estado de alerta cortical?:","options":["Inactiva transitoriamente al Núcleo Reticular del Tálamo (NRT), desinhibiendo a los núcleos de relevo talámico para que transmitan información hacia la corteza cerebral (vigilia).","Estimula directamente la secreción de GABA en la corteza motora primaria.","Destruye los plexos coroideos del tercer ventrículo.","Inerva los músculos estriados de la pierna."],"answer":0,"explanation":"No incluida en el material.","hack":"El Complejo Ponto- Mesencefálico Tegmental (colinérgico) envía axones al Núcleo Reticular del Tálamo (NRT). Al bloquear la inhibición GABAérgica del NRT sobre los núcleos de relevo, el tálamo \"abre la puerta\" e inunda la corteza de señales, generando el patrón electroencefálico de vigilia y desincronización.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-004 / G0087 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.7 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 10-01C~1.MP3 / 10-30 Clase magistral_ Neuroanatomía meníngea / TEMA 5 – DIENCÉFALO .pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-78","number":"78","statement":"En la cara lateral del tálamo, ¿qué estructuras se disponen adosadas a su superficie separándolo del núcleo lenticular y del núcleo caudado respectivamente?:","options":["La lámina medular externa y el brazo posterior de la cápsula interna (lateralmente) | La estría terminal y la vena talamoestriada (en el surco talamoestriado que lo separa del caudado).","La arteria basilar y la hoz del cerebro.","El quiasma óptico y los cuerpos mamilares.","La fosa romboidea y el pirámide bulbar."],"answer":0,"explanation":"No incluida en el material.","hack":"Anatomía de Relaciones del Tálamo: Lateralmente: Separado del núcleo lenticular por la Lámina Medular Externa y la Cápsula Interna (brazo posterior). Superolateromedial (Surco Talamoestriado): Discurren la Estría Terminal y la Vena Talamoestriada, marcando el límite con el núcleo caudado.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-005 / G0088 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #44) / Recopilación preguntas neuro (1).pdf / 09-30 Clase de Neuroanatomía_ Tálamo","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-79","number":"79","statement":"En la conducción de la sensibilidad nociceptiva, el tracto paleoespinotalámico (vía lenta y difusa del dolor) finaliza en núcleos talámicos no específicos. ¿En qué grupo nuclear del tálamo hacen sinapsis sus axones para proyectar de forma difusa a la corteza e ínsula, modulando la respuesta afectiva y motivacional del dolor?:","options":["Núcleos Intralaminares (núcleo centromediano y parafascicular)","Núcleo Geniculado Lateral","Núcleo Ventral PosteroLateral (VPL)","Núcleo Anterior del Tálamo"],"answer":0,"explanation":"No incluida en el material.","hack":"Vía Neoespinotalámica (Dolor agudo/localizado): Termina en el VPL -> proyecta a S1 (localización espacial exacta del dolor). Vía Paleoespinotalámica (Dolor sordo/crónico/difuso): Termina en los Núcleos Intralaminares y Centromediano -> proyectan de forma difusa a la corteza, ínsula y cíngulo (procesamiento emocional y afectivo del dolor).","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-006 / G0090 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 12-15 Lección_ Neurobiología del Dolor-transcript.txt / TEMA 5 – DIENCÉFALO .pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-80","number":"80","statement":"En relación con la neurobiología del lenguaje y el modelo de Wernicke-Geschwind, señale la afirmación INCORRECTA:","options":["El área de Broca se corresponde anatómicamente con las áreas 44 y 45 de Brodmann en el lóbulo frontal del hemisferio dominante.","El área de Wernicke se ubica en el lóbulo temporal (área 22) y es esencial para la comprensión del lenguaje.","El giro angular (área 39) actúa como estación de relevo entre la corteza visual y el área de Wernicke en la lectura de un texto escrito.","El fascículo arqueado es un conjunto de axones que traslada la información lingüística, fundamentalmente, desde el área de Broca hacia el área de Wernicke."],"answer":3,"explanation":"No incluida en el material.","hack":"Hack de Inversión de Dirección del Fascículo Arqueado (Aviso de Examen de Aitana en Tutoría): La profesora Aitana recalca explícitamente en el audio: \"El fascículo arqueado comunica el área de Wernicke con el área de Broca, no al revés. Primero la información llega a Wernicke (comprensión) y de ahí pasa a Broca (producción) para ejecutar el habla. No es bidireccional en el modelo clásico de repetición\". La trampa en la opción D consiste en invertir el sentido diciendo que va de Broca a Wernicke.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-007 / G0113 del banco canónico | integración: Tema 1.7 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #130, #154, #178) / Exame Neuro 2022.pdf (Pregunta #52) / 10-10 Clase_ Lenguaje, Cerebro y Afasias","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-81","number":"81","statement":"Señale la secuencia neuroanatómica y funcional correcta de estructuras requerida para comprender y realizar la lectura de un texto escrito en voz alta:","options":["Corteza visual primaria (área 17 de Brodmann) → Áreas visuales secundarias (18, 19) → Giro angular (área 39) → Área de Wernicke (área 22) → Fascículo arqueado → Área de Broca (áreas 44, 45) → Corteza motora primaria (área 4).","Corteza auditiva primaria (41, 42) → Giro angular → Área de Wernicke → Área de Broca.","Corteza visual primaria → Giro cingulado → Área de Wernicke → Área de Broca.","Corteza visual primaria → Fascículo arqueado → Área de Broca directamente."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q2)] Hack de Secuencia Anatómica de la Lectura en Voz Alta: 1. Entrada visual: Retina -> V1 (área 17). 2. Traducción de grafemas a fonemas: Giro Angular (área 39). 3. Decodificación semántica: Área de Wernicke (área 22). 4. Conexión de salida: Fascículo Arqueado. 5. Programación motora del habla: Área de Broca (44, 45). 6. Ejecución física muscular: Corteza Motora Primaria (área 4) sobre los pares craneales fonadores. || [Explicación 2 (Neuro_Adicional_Parte3.pdf Q2)] Hack de Secuencia Anatómica de la Lectura en Voz Alta: Entrada visual: Retina -> V1 (área 17). Traducción de grafemas a fonemas: Giro Angular (área 39). Decodificación semántica: Área de Wernicke (área 22). Conexión de salida: Fascículo Arqueado. Programación motora del habla: Área de Broca (44, 45). Ejecución física muscular: Corteza Motora Primaria (área 4) sobre los pares craneales fonadores.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-008 / G0114 del banco canónico | integración: Tema 1.7 + Tema 1.8 + Tema 1.9.1 + Tema 1.11.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: ex. 2 (respuestas).pdf (Pregunta #24) / wuolah-free-Examen-Neuro-3.pdf (Pregunta #60) / 10-10 Clase_ Lenguaje, Cerebro y Afasias","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-82","number":"82","statement":"¿Cuál de las siguientes cortezas cerebrales de asociación ejerce la máxima influencia en la toma de decisiones, la planificación de planes de acción y el control ejecutivo del comportamiento?:","options":["Corteza prefrontal (áreas 9, 10 y 46 de Brodmann).","Corteza motora primaria (área 4).","Área somatosensorial primaria (áreas 1, 2, 3).","Corteza visual primaria (área 17)."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Control Ejecutivo Prefrontal: La corteza prefrontal es el nivel supremo en la jerarquía del control motor y conductual. Antes de que M1 (área 4) o las áreas secundarias (área 6) elaboren el programa motor, la corteza prefrontal selecciona los objetivos, evalúa las consecuencias, razona y elabora la planificación estratégica de la conducta.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-009 / G0119 del banco canónico | integración: Tema 1.7 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: Exame Neuro 2022.pdf (Pregunta #57) / ex. 2022 (sin respuestas) 2.pdf (Pregunta #30) / Nervioso T21-T22-20251014_163523","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-83","number":"83","statement":"Un paciente con antecedente de ictus isquémico presenta un habla espontánea completamente fluida y gramaticalmente bien estructurada, con comprensión del lenguaje hablado y escrito totalmente CONSERVADA. Sin embargo, cuando se le pide que repita frases o palabras que acaba de escuchar, muestra una incapacidad casi absoluta para la repetición. ¿Qué tipo de afasia presenta y qué estructura blanca está lesionada?:","options":["Afasia de conducción / Lesión del fascículo arqueado.","Afasia de Broca / Lesión del área 44 de Brodmann.","Afasia de Wernicke / Lesión del área 22 de Brodmann.","Afasia transcortical motora / Lesión del área 6."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Tríada de la Afasia de Conducción: Habla espontánea fluida + Comprensión preservada + Incapacidad severa para repetir. Ocurre por la desconexión del fascículo arqueado que comunica directamente el área de Wernicke (comprensión) con el área de Broca (producción).","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-010 / G0121 del banco canónico | integración: Tema 1.7 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 10-10 Clase_ Lenguaje, Cerebro y Afasias / TEMA 7 – FUNCIONES CEREBRALES SUPERIORES.pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #130)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-84","number":"84","statement":"En el flujo de información por el lóbulo temporal y el diencéfalo para la génesis y consolidación de la memoria declarativa (Circuito de Papez), señale el orden neuroanatómico correcto de la vía:","options":["Áreas de asociación cortical → Hipocampo → Hipotálamo (Cuerpos Mamilares) → Tálamo (Núcleo Anterior) → Áreas de asociación cortical (Giro del Cíngulo).","Áreas de asociación cortical → Tálamo → Hipocampo → Hipotálamo → Áreas de asociación.","Hipocampo → Áreas de asociación → Tálamo → Hipotálamo → Cíngulo.","Cuerpos Mamilares → Hipocampo → Cíngulo → Tálamo → Áreas motoras."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Secuencia del Circuito de Papez (Pregunta Fija de Examen): Cortezas de asociación -> Corteza Entorrinal / Hipocampo -> Fórnix -> Cuerpos Mamilares (Hipotálamo) -> Tracto Mamilotalámico -> Núcleo Anterior del Tálamo -> Giro del Cíngulo -> Cortezas de asociación.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-011 / G0122 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #54, #152) / 11-06 Tutoría_ Memoria (Papez) / Exame Neuro 2022.pdf (Pregunta #54)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-85","number":"85","statement":"Un paciente sin paresia muscular ni déficit sensitivo es capaz de nombrar una herramienta (como un martillo o un cepillo de dientes), pero cuando se le pide que simule o ejecute la secuencia motora del uso de dicho objeto, realiza movimientos torpes, desorganizados e inapropiados. ¿Cómo se clasifica este trastorno del movimiento aprendido y qué región asociativa suele estar lesionada?:","options":["Apraxia ideomotora o ideatoria / Lesión de la corteza de asociación parietal izquierda (área 40 / giro supramarginal).","Ataxia cerebelosa / Lesión del núcleo vermiano.","Parálisis bulbar / Lesión del núcleo ambiguo.","Astereognosia / Lesión de V1."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de las Apraxias Parietales: Las apraxias son la incapacidad para ejecutar movimientos aprendidos previos sin que exista parálisis motora o trastorno sensitivo primario. La corteza parietal izquierda de asociación (área 40 / giro supramarginal) almacena las representaciones del praxicon (esquemas motores aprendidos); su lesión destruye la fórmula del movimiento.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-012 / G0127 del banco canónico | integración: Tema 1.7 + Tema 1.8 + Tema 1.9.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 10-09 Clase_ Funciones Cerebrales y Memoria / TEMA 7 – FUNCIONES CEREBRALES SUPERIORES.pdf / 10-14 Clase_ Control Motor","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-86","number":"86","statement":"El síndrome de Gerstmann es un conjunto de déficits neurológicos altamente específico provocado por una lesión focal en el giro angular (área 39 de Brodmann) del lóbulo parietal dominante (izquierdo). ¿Qué tetrada clínica lo compone?:","options":["Agrafia, acalculia, agnosia digital y desorientación derecha-izquierda.","Alexia sin agrafia, hemianopsia homónima, afasia motora y apraxia ideatoria.","Anomia, apraxia del vestir, sordera verbal pura y ceguera cortical.","Astereognosia, prosopagnosia, simultanagnosia y mutismo acinético."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q20)] Hack de la Tétrada de Gerstmann (Pregunta Clásica de Examen): Lesión del Giro Angular Izquierdo (Área 39 de Brodmann) -> Síndrome de Gerstmann: 1. Agrafia (incapacidad para escribir). 2. Acalculia (incapacidad para realizar cálculos matemáticos). 3. Agnosia digital (incapacidad para reconocer los propios dedos o los de otros). 4. Desorientación derecha-izquierda. || [Explicación 2 (Neuro_Adicional_Parte3.pdf Q20)] Hack de la Tétrada de Gerstmann (Pregunta Clásica de Examen): Lesión del Giro Angular Izquierdo (Área 39 de Brodmann) -> Síndrome de Gerstmann: Agrafia (incapacidad para escribir). Acalculia (incapacidad para realizar cálculos matemáticos). Agnosia digital (incapacidad para reconocer los propios dedos o los de otros). Desorientación derecha-izquierda.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-013 / G0132 del banco canónico | integración: Tema 1.7 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #180) / 10-10 Clase_ Lenguaje, Cerebro y Afasias / wuolah-free-EXAMEN-2017-2018-1.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-87","number":"87","statement":"La incapacidad para reconocer objetos al tacto utilizando las manos en ausencia de déficit sensitivo somático primario (sin anestesia ni analgesia) se denomina astereognosia. ¿En qué región de la corteza cerebral se localiza la lesión responsable?:","options":["Corteza de asociación parietal superior (áreas 5 y 7 de Brodmann).","Corteza auditiva primaria (áreas 41 y 42).","Corteza motora suplementaria (área 6).","Polo temporal anterior."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Astereognosia Parietal: Las áreas 5 y 7 de Brodmann (corteza parietal superior asociativa) reciben la información táctil y propioceptiva primaria de S1 (1, 2, 3) y la integran para construir la representación tridimensional del objeto (estereognosia). Su lesión destruye la capacidad de reconocer un objeto mediante el palpado táctil (astereognosia).","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-014 / G0134 del banco canónico | integración: Tema 1.7 + Tema 1.8 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #181) / 10-08 Clase_ Áreas Funcionales / Tema 1.8 - Funciones cerebrales superiores","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-88","number":"88","statement":"Un paciente presenta imposibilidad completa para la lectura de palabras escritas (alexia), pero mantiene la capacidad intacta para escribir al dictado o de forma espontánea (agrafia ausente), sin poder posteriormente leer lo que él mismo acaba de escribir. ¿Qué combinación de lesiones produce este síndrome de \"alexia sin agrafia\" (o alexia pura / ceguera verbal)?:","options":["Infarto de la arteria cerebral posterior izquierda que destruye la corteza visual primaria izquierda (área 17) y el esplenio del cuerpo calloso.","Lesión del área de Broca y de la cápsula interna.","Lesión del giro precentral derecho.","Destrucción aislada del nervio óptico derecho."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q23)] Hack de Desconexión de la Alexia sin Agrafia (Caso de Examen Frecuente): La lesión de V1 izquierda causa hemianopsia homónima derecha (el paciente solo ve con el hemisferio derecho). La información visual del ojo izquierdo viaja a V1 derecha. Para ser leída, debe cruzar al área de Wernicke/Giro Angular izquierdo. La lesión asociada del ESPLENIO del cuerpo calloso bloquea dicho cruce. Resultado: El sujeto ve la palabra con el hemisferio derecho pero no puede enviarla al área del lenguaje izquierda (Alexia pura / sin agrafia).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-015 / G0135 del banco canónico | integración: Tema 1.3 + Tema 1.7 + Tema 1.8 + Tema 1.11.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 10-10 Clase_ Lenguaje, Cerebro y Afasias / TEMA 7 – FUNCIONES CEREBRALES SUPERIORES.pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-89","number":"89","statement":"¿En cuál de los siguientes lóbulos cerebrales se localiza el área funcional del lenguaje conocida como área de Wernicke (área 22 de Brodmann)?:","options":["Lóbulo temporal (porción posterior de la circunvolución temporal superior del hemisferio dominante).","Lóbulo frontal (porción opercular y triangular de la tercera circunvolución frontal).","Lóbulo occipital (alrededor de la cisura calcarina).","Lóbulo parietal superior (áreas 5 y 7)."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Localización de Wernicke vs. Broca (Pregunta Recurrente de Examen): La banca pregunta con frecuencia qué área funcional NO se encuentra en el lóbulo frontal. El área de Broca (44 y 45), el área motora suplementaria y el campo ocular frontal están en el lóbulo frontal; mientras que el área de Wernicke (22) se ubica en el lóbulo temporal.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-016 / G0137 del banco canónico | integración: Tema 1.7 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #183) / wuolah-free-EXAMEN- 2017-2018-1 (1).pdf (Pregunta #72) / 10-10 Clase_ Lenguaje, Cerebro y Afasias-transcript.txt","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-90","number":"90","statement":"Sobre la afasia de Broca (motora o no fluente) provocada por una lesión grave en las áreas 44 y 45 de Brodmann, señale la afirmación VERDADERA:","options":["Se caracteriza por un habla espontánea entrecortada, lenta y con gran esfuerzo motor, presentando la comprensión del lenguaje bastante bien conservada y ausencia habitual de parafasias.","El paciente presenta un habla fluida pero sin sentido, repleta de parafasias y con severo déficit de comprensión.","Ocurre por la desconexión exclusiva entre la corteza visual y el giro angular.","El paciente no es consciente de su dificultad motora para articular las palabras."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Ausencia de Parafasias en Broca (Aviso Directo de Aitana en Clase): La profesora Aitana enfatiza en la grabación: \"La afasia de Broca es sin parafasias. El habla es entrecortada, no fluida, con esfuerzo, pero la comprensión está conservada\". La trampa en los exámenes es falsamente atribuir parafasias o pérdida de comprensión a la afasia de Broca.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-017 / G0140 del banco canónico | integración: Tema 1.7 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #59, #154) / 10-10 Clase_ Lenguaje, Cerebro y Afasias-transcript.txt / wuolah-free-Examen-Neuro-recu-junio-2023 orc.pdf (Pregunta #39)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-91","number":"91","statement":"Al solicitar a un paciente que lea un texto en voz alta en un idioma que comprende perfectamente, la información luminosa procesada por la retina viaja secuencialmente por el sistema nervioso. ¿Cuál es el orden neuroanatómico exacto y qué ocurre si lee un texto en un idioma que desconoce por completo?:","options":["Sistema visual (V1 - área 17) → Áreas secundarias (18, 19) → Giro angular (área 39, traducción de grafemas a fonemas) → Área de Wernicke (área 22) → Fascículo arqueado → Área de Broca (áreas 44, 45) → Corteza motora primaria (área 4). Si el idioma es desconocido, activa predominantemente la vía dorsal (fonológica) pero activa menos regiones de la vía ventral (semántica).","Corteza visual primaria → Fascículo arqueado directamente → Área de Broca → Corteza motora primaria. Si el idioma es desconocido, no se activa la corteza motora.","Sistema auditivo → Corteza auditiva primaria → Giro angular → Área de Broca directamente.","Sistema visual → Giro cingulado → Área de Wernicke → Área motora suplementaria sin pasar por Broca."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q33)] Hack de la Secuencia de Lectura y Rota Doble (Aitana): En la lectura en voz alta, la luz llega a la corteza visual primaria (área 17), pasa a las áreas 18 y 19, llega al giro angular (área 39) que convierte los signos gráficos en código fonológico, pasa al área de Wernicke (22) para la comprensión semántica (vía ventral), viaja por el fascículo arqueado al área de Broca (44, 45) para la programación motora del habla, y finalmente a la corteza motora primaria (área 4) para mover los músculos fonadores. Pegadinha da Banca: Si el sujeto lee un idioma desconocido, \"repite como un loro\" usando la vía dorsal (fonológica) sin activar la vía ventral semántica, por lo que se activan menos regiones corticales.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-018 / G0145 del banco canónico | integración: Tema 1.7 + Tema 1.8 + Tema 1.9.1 + Tema 1.11.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #241) / 10-10 Clase_ Lenguaje, Cerebro y Afasias / ex. 2 (respuestas).pdf (Pregunta #24)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-92","number":"92","statement":"La corteza de asociación parieto-temporo-occipital realiza la integración somatosensorial multimodal. Señale la asociación INCORRECTA entre la región asociativa o estructura y el trastorno neurológico resultante de su lesión:","options":["Áreas 5 y 7 de Brodmann (Corteza parietal superior) → Astereognosia (incapacidad para reconocer objetos mediante el tacto).","Giro angular izquierdo (Área 39 de Brodmann) → Síndrome de Gerstmann (agrafia, acalculia, agnosia digital y desorientación derecha-izquierda).","Giro fusiforme / Área facial fusiforme (FFA) → Prosopagnosia (incapacidad para reconocer rostros humanos conocidos).","Corteza prefrontal (Área 10) → Anosognosia para la ceguera (Síndrome de Anton) por lesión de las arterias auditivas."],"answer":3,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q38)] Hack de las Agnosias por Áreas Corticales: Parietal superior (5 y 7): Astereognosia (tacto 3D). Giro angular (39): Síndrome de Gerstmann (agrafia, acalculia, agnosia digital, D-I). Giro fusiforme: Prosopagnosia (rostros). La alternativa D inventa una relación falsa sobre la corteza prefrontal y la \"arteria auditiva\".","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-019 / G0150 del banco canónico | integración: Tema 1.7 + Tema 1.8 + Tema 1.10 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #181, #182) / 10-08 Clase_ Áreas Funcionales / TEMA 6 – TELENCÉFALO.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-93","number":"93","statement":"En relación con la anatomía y neurofisiología de la corteza motora primaria (M1, área 4 de Brodmann), señale la afirmación FALSA:","options":["Ocupa los dos tercios posteriores del giro precentral (frontal ascendente) inmediatamente anterior al surco central.","Su capa V (piramidal interna) contiene grandes neuronas piramidales (células de Betz) cuyos axones descienden por la cápsula interna.","Desde la corteza motora primaria se originan el 100% de los axones que constituyen el tracto corticoespinal.","Presenta una organización somatotópica (homúnculo motor) donde la representación del pie y miembro inferior se ubica medialmente (cara interna del hemisferio) y la de la cara y mano en la cara lateral."],"answer":2,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q1)] Hack del Falso Absoluto (El 100% de Fibras): La banca utiliza con frecuencia la trampa del \"100%\". El tracto corticoespinal NO nace exclusivamente en M1 (área 4); solo un 30-40% de sus axones proceden del área 4. El resto se origina en el área 6 (corteza motora secundaria/premotora) y en las cortezas somatosensitivas y asociativas del lóbulo parietal (áreas 3, 1, 2, 5 y 7). || [Explicación 2 (Neuro_Adicional_Parte4.pdf Q1)] Hack del Falso Absoluto (El 100% de Fibras): La banca utiliza con frecuencia la trampa del \"100%\"12. El tracto corticoespinal NO nace exclusivamente en M1 (área 4); solo un 30- 40% de sus axones proceden del área 434. El resto se origina en el área 6 (corteza motora secundaria/premotora) y en las cortezas somatosensitivas y asociativas del lóbulo parietal (áreas 3, 1, 2, 5 y 7).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-020 / G0153 del banco canónico | integración: Tema 1.7 + Tema 1.9.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #40, #157, #181) / 12-04 Clase magistral_ Corteza motora / wuolah-free-EXAMEN-2017-2018-1 (1).pdf (Pregunta #12)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-94","number":"94","statement":"La corteza motora secundaria (área 6 de Brodmann) se localiza inmediatamente anterior al área motora primaria y se subdivide en dos regiones funcionales distintas. Señale la afirmación CORRECTA sobre su organización y función:","options":["El área premotora se ubica en la cara lateral e inferior del área 6 (coordinando movimientos complejos multiarticulares guiados por estímulos externos), mientras que el área motora suplementaria ocupa la porción medial y superior (implicada en la ideación, planificación e iniciación interna del movimiento).","El área premotora se localiza exclusivamente en el polo occipital.","El área motora suplementaria es la responsable directa del arco reflejo miotático medular.","Ambas regiones pertenecen a la corteza somatosensitiva primaria (áreas 1, 2 y 3)."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q2)] Hack de Bipartición del Área 6 (Lateral vs Medial): La profesora Aitana resalta en clase la división estricta del Área 6 (M2): Área Premotora (APM): Lateral e inferior -> Selección de planes motores basados en pistas sensoriales externas. Área Motora Suplementaria (AMS): Medial y superior (cara interna) -> Ideación, programación mental e iniciación interna de secuencias motoras.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-021 / G0154 del banco canónico | integración: Tema 1.7 + Tema 1.9.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: Tema 1.9.1 - Corteza motora y vías motoras descendentes 25-26.pdf / 10-08 Clase_ Áreas Funcionales / 12-04 Clase magistral_ Corteza motora","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-95","number":"95","statement":"El tracto corticonuclear (corticobulbar) desciende por la rodilla de la cápsula interna para inervar los núcleos motores somáticos y branquiales de los pares craneales en el tronco del encéfalo. ¿Qué característica de inervación presenta el núcleo motor del nervio facial (VII par) que la convierte en la gran excepción del grupo?:","options":["La porción del núcleo del facial que inerva los músculos de la mitad inferior de la cara recibe inervación cortical exclusivamente contralateral, mientras que la porción para la mitad superior de la cara recibe inervación bilateral.","Todo el núcleo del facial recibe inervación exclusivamente ipsilateral.","El núcleo del facial recibe únicamente aferencias del cerebelo.","La mitad superior de la cara está inervada por el tracto rubroespinal."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q4)] Hack de la Parálisis Facial Central vs. Periférica: Generalidad corticonuclear: Inervación BILATERAL a casi todos los núcleos motores craneales (V, ambiguo, XII, etc.). EXCEPCIÓN DE EXAMEN (VII Par): La mitad superior del rostro (frente y orbicular de los ojos) recibe fibras bilaterales. La mitad inferior (boca) recibe fibras únicamente contralaterales. Un ictus en la corteza motora causa parálisis del cuadrante inferior contralateral respetando la frente (parálisis central).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-022 / G0156 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.7 + Tema 1.9.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #181, #182) / Tema 1.9.1 - Corteza motora / 09-26 Clase_ Nervios Craneales","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-96","number":"96","statement":"Durante su descenso por la sustancia blanca profunda del telencéfalo hacia el tronco del encéfalo, los axones de la vía piramidal atraviesan la cápsula interna. ¿En qué porciones específicas de la cápsula interna se sitúan las fibras del tracto corticoespinal y del tracto corticonuclear respectivamente?:","options":["El tracto corticoespinal discurre por el brazo posterior de la cápsula interna, mientras que el tracto corticonuclear atraviesa la rodilla de la cápsula interna.","El tracto corticoespinal pasa por el brazo anterior y el corticonuclear por el rodete.","Ambos tractos descienden agrupados exclusivamente por la cápsula extrema.","El tracto corticonuclear discurre posterior al tracto corticoespinal en el brazo posterior."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q9)] Hack de la Cápsula Interna (Rodilla vs. Brazo Posterior): La profesora Aitana enfatiza la somatotopía en la cápsula interna: Rodilla de la cápsula interna: Punto de paso específico del Tracto Corticonuclear (fibras para la región craneofacial). Brazo posterior (ramo posterior): Punto de paso específico del Tracto Corticoespinal (fibras para extremidades y tronco). La banca invierte las posiciones afirmando que el corticonuclear va por el brazo posterior.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-023 / G0161 del banco canónico | integración: Tema 1.5.1 + Tema 1.7 + Tema 1.9.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: Tema 1.9.1 - Corteza motora y vías motoras descendentes 25-26.pdf / 12-04 Clase_ Tractos Corticoespinal, Corticonuclear / 10-15 Clase_ Vías Motoras Descendentes.mp","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-97","number":"97","statement":"Respecto a la anatomía descriptiva y las relaciones de vecindad de los núcleos basales en las secciones del telencéfalo, señale la afirmación VERDADERA:","options":["El globo pálido es la estructura más medial del núcleo lenticular, situándose el putamen lateral a él.","El putamen es más interno o medial que el globo pálido.","En una sección transversal del cerebro, la cápsula externa separa al tálamo del globo pálido.","La cola del núcleo caudado forma parte del núcleo lenticular."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q1)] Hack de la Posición Medial/Lateral del Núcleo Lenticular (Trampa Fija de Examen): La profesora Aitana enfatiza repetidamente en clase: \"El núcleo lenticular (o lentiforme) está formado por la suma del Putamen + Globo Pálido. De ellos, el Putamen es la porción MÁS LATERAL/EXTERNA, y el Globo Pálido (segmentos externo e interno) es la porción MÁS MEDIAL/INTERNA\". Las opciones falsas invierten la relación diciendo que el putamen es medial (FALSO) o confunden la cápsula interna (que separa tálamo de lenticular) con la externa.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-024 / G0169 del banco canónico | integración: Tema 1.7 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #44, #98, #208) / Examem 2025 outro modelo juneka.pdf (Pregunta #23) / 12-05 Clase_ Núcleos Basales - Terminología y Anatomía","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-98","number":"98","statement":"Con relación a la citoarquitectura de la corteza motora primaria (M1, área 4 de Brodmann), señale la afirmación FALSA:","options":["La capa V (piramidal interna) presenta grandes motoneuronas piramidales (células de Betz) que proyectan hacia la médula espinal.","Sus proyecciones constituyen una porción fundamental del brazo posterior de la cápsula interna.","La capa III (piramidal externa) es la que contiene las células piramidales gigantes de Betz responsables de la vía corticoespinal.","Es un área ejecutora dentro de la organización jerárquica del movimiento voluntario."],"answer":2,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q17)] Hack de la Capa III vs. Capa V (Pregunta Trampa de Examen): Las células gigantes de Betz se ubican EXCLUSIVAMENTE en la Capa V (piramidal interna) de M1. La banca utiliza frecuentemente el recurso de afirmar que se encuentran en la Capa III (piramidal externa) para inducir al error en la lectura rápida. || [Explicación 2 (Neuro_Adicional_Parte4.pdf Q17)] Hack de la Capa III vs. Capa V (Pregunta Trampa de Examen): Las células gigantes de Betz se ubican EXCLUSIVAMENTE en la Capa V (piramidal interna) de M1710. La banca utiliza frecuentemente el recurso de afirmar que se encuentran en la Capa III (piramidal externa) para inducir al error en la lectura rápida.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-025 / G0177 del banco canónico | integración: Tema 1.7 + Tema 1.9.1 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #157, #181) / wuolah-free- EXAMEN-2017-2018-1.pdf (Pregunta #12) / examenes neuro compl (1).pdf (Pregunta #35)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-99","number":"99","statement":"Un paciente sufre un infarto lacunar por oclusión de las arterias lenticulostriadas que destruye el brazo posterior de la cápsula interna derecha. ¿Qué hallazgo neurológico presentará inmediatamente el paciente?:","options":["Hemiparesia/Hemiplejía fascio-corporal contralateral (izquierda) de tipo piramidal/espástico.","Sordera cortical bilateral pura.","Pérdida exclusiva de la visión en el ojo derecho.","Parálisis flácida ipsilateral aislada del músculo trapecio."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Cápsula Interna: El brazo posterior de la cápsula interna contiene los axones proyectados del tracto corticoespinal. Su destrucción interrumpe la 1ª motoneurona produciendo hemiplejía espástica contralateral con Babinski.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-026 / G0189 del banco canónico | integración: Tema 1.7 + Tema 1.9.1 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #181, #182) / Exame Neuro 2022.pdf / Tema 1.9.1 - Corteza motora","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-100","number":"100","statement":"En la preparación de un movimiento voluntario complejo (por ejemplo, tocar una secuencia memorizada en el piano sin mirar el teclado), ¿qué región cortical muestra la máxima activación previa en las pruebas de neuroimagen funcional?:","options":["Área Motora Suplementaria (AMS, cara medial del área 6 de Brodmann).","Área Premotora Lateral (APM).","Corteza Visual Primaria (área 17).","Núcleo gracilis del bulbo."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q30)] Hack de Pistas Internas vs. Pistas Externas: Área Motora Suplementaria (AMS): Se activa en movimientos iniciados por PISTAS INTERNAS / MEMORIZADAS. Área Premotora (APM): Se activa en movimientos guiados por PISTAS EXTERNAS (visuales o auditivas).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-027 / G0190 del banco canónico | integración: Tema 1.7 + Tema 1.9.1 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #181) / Tema 1.9.1 - Corteza motora / 10-14 Clase_ Control Motor y Planificación","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-101","number":"101","statement":"La Potenciación a Largo Plazo (LTP) se considera la base neurobiológica y molecular primaria para la consolidación de la memoria a largo plazo en el hipocampo. ¿Qué caracterización de este fenómeno es la CORRECTA?:","options":["Implica una facilitación sináptica duradera desencadenada por la entrada masiva de Ca2+ a través de receptores NMDA, provocando cambios estructurales y funcionales en la neurona postsináptica (expansión de espinas dendríticas).","Depende exclusivamente de la liberación de serotonina en la médula espinal.","Ocurre sin necesidad de alterar los receptores de glutamato.","Es un proceso destructivo irreversible que borra de forma permanente los recuerdos consolidados."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q43)] Hack Neuroquímico de la LTP (NMDA + Ca2+): La LTP en las neuronas piramidales del hipocampo (CA1/CA3) requiere la activación de los receptores glutamatérgicos NMDA y la entrada de calcio (Ca2+), induciendo modificaciones estructurales permanentes en las espinas dendríticas postsinápticas. || [Explicación 2 (Neuro_Adicional_Parte4.pdf Q43)] Hack Neuroquímico de la LTP (NMDA + Ca2+): La LTP en las neuronas piramidales del hipocampo (CA1/CA3) requiere la activación de los receptores glutamatérgicos NMDA y la entrada de calcio (Ca²⁺), induciendo modificaciones estructurales permanentes en las espinas dendríticas postsinápticas.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-028 / G0198 del banco canónico | integración: Tema 1.7 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: wuolah-free-Examen-Neuro-3.pdf (Pregunta #28) / TEMA 7 – FUNCIONES CEREBRALES SUPERIORES.pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #152)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-102","number":"102","statement":"Dentro del circuito límbico de recompensa que conecta el área tegmental ventral (VTA) y el núcleo accumbens, ¿qué región de la corteza cerebral procesa la experiencia placentera consciente y otorga el \"valor hedonista subjetivo\" a un estímulo?:","options":["Corteza orbitofrontal medial.","Corteza somatosensorial primaria (S1).","Área 17 de Brodmann.","Tubérculo grácil del bulbo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Corteza Orbitofrontal Hedonista (Aviso de Examen): El área tegmental ventral aporta la dopamina (motivación) hacia el núcleo accumbens, pero la vivencia consciente del placer/valor hedonista subjetivo se codifica específicamente en la corteza orbitofrontal medial.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-029 / G0200 del banco canónico | integración: Tema 1.7 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: wuolah-free-Examen-Neuro-recu-junio-2023 orc.pdf (Pregunta #38, #39) / Recopilación preguntas neuro (1).pdf (Pregunta #9)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-103","number":"103","statement":"La memoria de trabajo (working memory) es el sistema que permite mantener y manipular temporalmente la información necesaria para realizar tareas cognitivas complejas. ¿En qué región específica de la neocorteza se localiza su principal centro de control e integración neurobiológica?:","options":["Corteza prefrontal dorsolateral (áreas 9 y 46 de Brodmann).","Corteza visual primaria (área 17).","Corteza somatosensorial primaria (áreas 1, 2, 3).","Núcleo ambiguo del bulbo raquídeo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Memoria de Trabajo Dorsolateral: La corteza prefrontal dorsolateral (áreas 9 y 46) es la estructura clave del control ejecutivo. Mantiene activa la información \"en línea\" durante segundos o minutos mientras se resuelve un problema, se calcula una operación o se toma una decisión estratégica.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-030 / G0205 del banco canónico | integración: Tema 1.7 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: 10-09 Clase_ Funciones Cerebrales y Memoria / Tema 1.8 - Funciones cerebrales superiores 25-26 (1).pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.7-104","number":"104","statement":"En el estudio de la lateralización cerebral en pacientes con cerebro dividido (split-brain) por trisección quirúrgica completa del cuerpo calloso, se proyecta fugazmente una imagen de un objeto exclusivamente en el campo visual izquierdo del paciente. ¿Qué respuesta neuropsicológica se obtiene?:","options":["El paciente no puede nombrar verbalmente el objeto (porque la información proyectada a V1 derecha no puede cruzar al hemisferio izquierdo lingüístico), pero puede seleccionarlo correctamente utilizando su mano izquierda.","El paciente nombra el objeto de inmediato sin ninguna dificultad.","El paciente pierde la capacidad de mover la mano derecha.","El paciente sufre una afasia de Broca irreversible."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q52)] Hack del Split-Brain en Campo Visual Izquierdo: Campo visual izquierdo -> Proyecta a V1 del hemisferio derecho. Sin cuerpo calloso, la información NO puede cruzar a Wernicke/Broca en el hemisferio izquierdo -> El paciente dice verbalmente que \"no vio nada\". Sin embargo, el hemisferio derecho sí procesó la imagen y controla la mano izquierda, permitiéndole tomar físicamente el objeto correcto.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.7 - TELENCÉFALO | entrada I-031 / G0207 del banco canónico | integración: Tema 1.7 + Tema 1.8 + Tema 1.11.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: Tema 1.8 - Funciones cerebrales superiores 25-26 (1).pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #183)","topic":"1.7","document":"04-TEC15E-1.TXT","subject":"MEFOS"}]);